    #[cfg(feature = "ui-smoke")]
    fn install_long_line_smoke(
        &mut self,
        mode: DiffMode,
        cx: &mut Context<Root>,
    ) -> Result<(), String> {
        let index = self
            .active_tab
            .ok_or_else(|| "long-line smoke has no active tab".to_owned())?;
        let text = format!(
            "LONG-LINE-BEGIN {} {SMOKE_LONG_LINE_TOKEN}",
            "0123456789abcdef".repeat(256)
        );
        let line = DiffLine {
            kind: DiffLineKind::Addition,
            old_line: None,
            new_line: Some(1),
            text,
        };
        let rows = vec![
            DiffRow::Hunk(format!("Native {mode:?} long-line reachability fixture")),
            match mode {
                DiffMode::SideBySide => {
                    let shared = "0123456789abcdef".repeat(256);
                    DiffRow::Split(AlignedRow {
                        old: Some(DiffLine {
                            kind: DiffLineKind::Deletion,
                            old_line: Some(1),
                            new_line: None,
                            text: format!("{SMOKE_OLD_LINE_START} {shared} {SMOKE_OLD_LINE_END}"),
                        }),
                        new: Some(DiffLine {
                            kind: DiffLineKind::Addition,
                            old_line: None,
                            new_line: Some(1),
                            text: format!("{SMOKE_NEW_LINE_START} {shared} {SMOKE_NEW_LINE_END}"),
                        }),
                    })
                }
                DiffMode::Auto | DiffMode::Unified => DiffRow::Unified(line),
            },
        ];
        if let Some(session) = &mut self.tabs[index].session {
            session.set_diff_mode(mode);
        }
        self.tabs[index].diff_content_width = diff_content_width(&rows, mode);
        self.tabs[index].diff_rows = rows;
        self.tabs[index].diff_scroll = ListState::new(
            self.tabs[index].diff_rows.len(),
            ListAlignment::Top,
            px(480.),
        );
        self.tabs[index].diff_horizontal = ScrollHandle::new();
        self.tabs[index].diff_scroll.scroll_to_reveal_item(1);
        cx.notify();
        Ok(())
    }

    #[cfg(feature = "ui-smoke")]
    fn scroll_long_line_smoke_to_end(&mut self, cx: &mut Context<Root>) -> Result<f32, String> {
        let index = self
            .active_tab
            .ok_or_else(|| "long-line smoke has no active tab".to_owned())?;
        let handle = &self.tabs[index].diff_horizontal;
        let maximum = handle.max_offset().x.as_f32();
        if maximum < 1_000. {
            return Err(format!(
                "long-line viewport did not expose meaningful horizontal overflow ({maximum}px)"
            ));
        }
        handle.set_offset(point(px(-maximum), px(0.)));
        cx.notify();
        Ok(maximum)
    }

    #[cfg(feature = "ui-smoke")]
    fn validate_long_line_smoke(&self, maximum: f32, mode: DiffMode) -> Result<(), String> {
        let index = self
            .active_tab
            .ok_or_else(|| "long-line smoke has no active tab".to_owned())?;
        let tab = &self.tabs[index];
        if tab
            .session
            .as_ref()
            .is_none_or(|session| session.diff_mode() != mode)
        {
            return Err(format!("long-line scene did not expose {mode:?} mode"));
        }
        let rendered_source_has_token = tab.diff_rows.iter().any(|row| match (mode, row) {
            (DiffMode::Unified, DiffRow::Unified(line)) => {
                line.text.ends_with(SMOKE_LONG_LINE_TOKEN)
            }
            (DiffMode::SideBySide, DiffRow::Split(row)) => {
                row.old
                    .as_ref()
                    .is_some_and(|line| line.text.ends_with(SMOKE_OLD_LINE_END))
                    && row
                        .new
                        .as_ref()
                        .is_some_and(|line| line.text.ends_with(SMOKE_NEW_LINE_END))
            }
            _ => false,
        });
        let offset = tab.diff_horizontal.offset().x.as_f32();
        if !rendered_source_has_token || (offset + maximum).abs() > 1. {
            return Err(format!(
                "long-line far-end render state is invalid (token={rendered_source_has_token}, offset={offset}, maximum={maximum})"
            ));
        }
        Ok(())
    }

    #[cfg(feature = "ui-smoke")]
    fn validate_split_long_line_start(&self) -> Result<(), String> {
        let index = self
            .active_tab
            .ok_or_else(|| "split long-line smoke has no active tab".to_owned())?;
        let tab = &self.tabs[index];
        if tab.diff_horizontal.offset().x.as_f32().abs() > 1. {
            return Err("split long-line fixture did not begin at its left edge".to_owned());
        }
        let sentinels_are_side_specific = tab.diff_rows.iter().any(|row| {
            let DiffRow::Split(row) = row else {
                return false;
            };
            row.old
                .as_ref()
                .is_some_and(|line| line.text.starts_with(SMOKE_OLD_LINE_START))
                && row
                    .new
                    .as_ref()
                    .is_some_and(|line| line.text.starts_with(SMOKE_NEW_LINE_START))
        });
        if !sentinels_are_side_specific {
            return Err("split long-line start sentinels lost OLD/NEW identity".to_owned());
        }
        Ok(())
    }

    #[cfg(feature = "ui-smoke")]
    fn restore_real_diff_after_long_line(&mut self, cx: &mut Context<Root>) {
        if let Some(index) = self.active_tab {
            if let Some(session) = &mut self.tabs[index].session {
                session.set_diff_mode(DiffMode::Unified);
            }
            self.rebuild_diff(index, self.wide);
            cx.notify();
        }
    }

    #[cfg(feature = "ui-smoke")]
    fn run_primary_smoke_actions(
        &mut self,
        second_pr: Option<u64>,
        expect_restore: bool,
        auto_layout_verified: bool,
        window: &mut Window,
        cx: &mut Context<Root>,
    ) -> Result<SmokeActions, String> {
        let index = self
            .active_tab
            .ok_or_else(|| "no active pull request".to_owned())?;
        let tab = &self.tabs[index];
        let session = tab
            .session
            .as_ref()
            .ok_or_else(|| "active comparison is not loaded".to_owned())?;
        let restored =
            matches!(&tab.state, LoadState::Cached(notice) if notice.contains("Restored"));
        if expect_restore && !restored {
            return Err("expected a persisted review session to restore".to_owned());
        }
        let original_key = session
            .selected_file()
            .map(file_key)
            .ok_or_else(|| "comparison has no selected file".to_owned())?;
        let file_count = session.comparison().files.len();
        if file_count < 2 {
            return Err("native navigation smoke requires a multi-file pull request".to_owned());
        }
        let repository = tab.repository.clone();
        let number = tab.pull_request.number;
        let title = tab.pull_request.title.clone();
        let source_branch = tab.pull_request.source_branch.clone();
        let target_branch = tab.pull_request.target_branch.clone();
        let branches = format!("{} -> {}", source_branch, target_branch);
        let revision = session.revision().head_sha.clone();
        let initial_mode = session.diff_mode();
        let initial_rows_are_split = tab
            .diff_rows
            .iter()
            .any(|row| matches!(row, DiffRow::Split(_)));
        let actual_diff_width = effective_diff_viewport_width(&tab.diff_rows, &tab.diff_horizontal);
        let calculated_diff_width = self.available_diff_width(window);
        if actual_diff_width <= 0.
            || (actual_diff_width - calculated_diff_width).abs() > SPLITTER_WIDTH + 2.
        {
            return Err(format!(
                "actual diff viewport {actual_diff_width}px differs from pane calculation {calculated_diff_width}px"
            ));
        }
        if !expect_restore
            && (initial_mode != DiffMode::Auto || !self.wide || !initial_rows_are_split)
        {
            return Err(format!(
                "initial wide Auto layout was not split (pane {actual_diff_width}px)"
            ));
        }
        if expect_restore && initial_mode == DiffMode::Auto {
            return Err("explicit diff mode did not restore with the tab".into());
        }
        if !auto_layout_verified {
            return Err(
                "native Auto layout did not switch wide split -> narrow unified -> wide split"
                    .into(),
            );
        }
        if number == 14130
            && !tab
                .details
                .as_ref()
                .is_some_and(|details| details.body.contains("Issue fields are not currently"))
        {
            return Err("cli/cli#14130 Markdown overlap probe text is absent".into());
        }
        let next_expected_key = session
            .comparison()
            .files
            .iter()
            .position(|file| file_key(file) == original_key)
            .and_then(|position| session.comparison().files.get(position + 1))
            .map(file_key)
            .ok_or_else(|| "selected file has no next file for tree reveal smoke".to_owned())?;
        let saved_view_report =
            self.exercise_saved_view_smoke(&source_branch, &target_branch, expect_restore)?;

        if self.tabs[index]
            .file_tree
            .collapse_ancestor_of(&next_expected_key)
            .is_some()
            && self.tabs[index]
                .file_tree
                .file_is_visible(&next_expected_key)
        {
            return Err("collapsed tree ancestor left its changed file visible".into());
        }
        self.next_file(&NextFile, window, cx);
        let next_key = self.tabs[index]
            .session
            .as_ref()
            .and_then(ReviewSession::selected_file)
            .map(file_key)
            .ok_or_else(|| "next-file handler cleared selection".to_owned())?;
        if next_key == original_key {
            return Err("next-file handler did not advance selection".to_owned());
        }
        if next_key != next_expected_key || !self.tabs[index].file_tree.file_is_visible(&next_key) {
            return Err("next-file navigation did not expand and reveal its tree ancestors".into());
        }
        self.previous_file(&PreviousFile, window, cx);
        let returned_key = self.tabs[index]
            .session
            .as_ref()
            .and_then(ReviewSession::selected_file)
            .map(file_key)
            .ok_or_else(|| "previous-file handler cleared selection".to_owned())?;
        if returned_key != original_key {
            return Err("previous-file handler did not restore selection".to_owned());
        }

        let default_tree_width = self.panel_layout.file_tree_width;
        self.adjust_panel(PanelKind::FileTree, PANEL_KEYBOARD_STEP, window, cx);
        if self.panel_layout.file_tree_width <= default_tree_width {
            return Err("programmatic file-tree splitter adjustment had no effect".into());
        }
        self.reset_layout(window, cx);
        if self.panel_layout.file_tree_width != DEFAULT_FILE_TREE_WIDTH {
            return Err("reset-layout action did not restore file-tree width".into());
        }

        if self.tabs[index]
            .session
            .as_ref()
            .is_some_and(|session| session.diff_mode() == DiffMode::Auto)
        {
            self.cycle_diff(&CycleDiffMode, window, cx);
        }
        window.resize(size(px(1040.), px(720.)));
        if self.tabs[index]
            .session
            .as_ref()
            .is_none_or(|session| session.diff_mode() == DiffMode::Auto)
        {
            return Err("diff mode was not explicit before resize".to_owned());
        }

        if let Some(second) = second_pr
            && second != number
        {
            let repo_index = self
                .repositories
                .iter()
                .position(|runtime| runtime.repository.cache_key() == repository.cache_key())
                .ok_or_else(|| "active repository is absent from sidebar".to_owned())?;
            self.open_pr(repo_index, second, cx);
        }

        Ok(SmokeActions {
            primary_number: number,
            report: format!(
                "Real read complete\nRepository: {}\nPR: #{number} {title}\nBranches: {branches}\nRevision: {revision}\nFiles: {file_count}\nSelected: {}\nSidebar and details reads: settled\n{saved_view_report}\nRestart restore observed: {restored}\nInitial actual diff pane: {actual_diff_width}px ({initial_mode:?})\nInitial wide Auto split: {}\nNarrow Auto unified: {}\nCollapsed-directory next/previous reveal: {original_key} -> {next_key} -> {returned_key}\nProgrammatic splitter adjustment and Reset layout: passed\ncli/cli#14130 Markdown probe source: {}\nExplicit diff mode survived narrow resize\n",
                repository.full_name(),
                self.tabs[index]
                    .session
                    .as_ref()
                    .and_then(ReviewSession::selected_file)
                    .map(|file| file.path.as_str())
                    .unwrap_or("none"),
                !expect_restore,
                if expect_restore {
                    "covered by fresh light run"
                } else if auto_layout_verified {
                    "passed"
                } else {
                    "failed"
                },
                number == 14130,
            ),
            expectations: Vec::new(),
        })
    }

    #[cfg(feature = "ui-smoke")]
    fn exercise_saved_view_smoke(
        &mut self,
        source_branch: &str,
        target_branch: &str,
        expect_restore: bool,
    ) -> Result<String, String> {
        const NAME: &str = "Smoke · target → repository → source prefix";
        let prefix = source_branch
            .split_once('/')
            .map(|(first, _)| format!("{first}/"))
            .unwrap_or_else(|| source_branch.to_owned());
        if !expect_restore {
            self.view_editor.begin(&self.workspace);
            self.view_editor.replace_filter(Filter {
                source_branch: source_branch.to_owned(),
                state: "open".into(),
                ..Default::default()
            });
            self.view_editor.replace_groups(vec![
                GroupBy::TargetBranch,
                GroupBy::Repository,
                GroupBy::SourcePrefix(prefix.clone()),
            ]);
            self.view_editor.save_as(&mut self.workspace, NAME)?;
            self.save_workspace();
        }
        let view = self.workspace.view();
        if view.name != NAME
            || view.filter.source_branch != source_branch
            || view.filter.state != "open"
            || view.groups
                != vec![
                    GroupBy::TargetBranch,
                    GroupBy::Repository,
                    GroupBy::SourcePrefix(prefix.clone()),
                ]
        {
            return Err("saved composed view did not restore exactly".into());
        }
        let store = self
            .store
            .as_ref()
            .ok_or_else(|| "saved-view smoke requires an isolated persistent store".to_owned())?;
        let restored = store
            .load_workspace()
            .map_err(|error| format!("cannot read saved view back: {error:#}"))?;
        if restored.view().name != NAME
            || restored.view().filter.source_branch != source_branch
            || restored.view().groups != view.groups
        {
            return Err("saved composed view read-back differs from active view".into());
        }
        Ok(format!(
            "Saved view: {NAME}\nExact source filter: {source_branch}\nGlobal grouping: {target_branch} → repository → prefix {prefix}\nSaved-view restart/read-back: passed"
        ))
    }

    #[cfg(feature = "ui-smoke")]
    fn run_tab_smoke_actions(
        &mut self,
        second_pr: Option<u64>,
        actions: &mut SmokeActions,
        window: &mut Window,
        cx: &mut Context<Root>,
    ) -> Result<(), String> {
        let primary_number = actions.primary_number;
        let primary = self
            .tabs
            .iter()
            .position(|tab| tab.pull_request.number == primary_number)
            .unwrap_or(0);
        let original_key = self.tabs[primary]
            .session
            .as_ref()
            .and_then(ReviewSession::selected_file)
            .map(file_key)
            .ok_or_else(|| "primary tab has no selected file".to_owned())?;

        let mut indices = vec![primary];
        if let Some(second) = second_pr
            && second != self.tabs[primary].pull_request.number
        {
            let secondary = self
                .tabs
                .iter()
                .position(|tab| tab.pull_request.number == second)
                .ok_or_else(|| format!("second PR #{second} did not load"))?;
            self.activate_tab(secondary, window, cx);
            self.activate_tab(primary, window, cx);
            let restored_key = self.tabs[primary]
                .session
                .as_ref()
                .and_then(ReviewSession::selected_file)
                .map(file_key)
                .ok_or_else(|| "tab switch cleared primary selection".to_owned())?;
            if restored_key != original_key {
                return Err("tab switch did not restore primary selection".to_owned());
            }
            indices.push(secondary);
            actions
                .report
                .push_str(&format!("Tab switch/restore: passed with PR #{second}\n"));
        }

        for index in indices {
            self.activate_tab(index, window, cx);
            let key = self.tabs[index]
                .session
                .as_ref()
                .and_then(ReviewSession::selected_file)
                .map(file_key)
                .ok_or_else(|| "tab has no selected file".to_owned())?;
            let previous = self.tabs[index]
                .session
                .as_ref()
                .is_some_and(|session| session.is_viewed(&key));
            self.toggle_viewed(&key, cx);
            actions.expectations.push(SmokeExpectation {
                repository: self.tabs[index].repository.clone(),
                number: self.tabs[index].pull_request.number,
                file_key: key,
                viewed: !previous,
            });
        }
        self.activate_tab(primary, window, cx);
        window.resize(size(px(1440.), px(900.)));
        if self.tabs[primary]
            .session
            .as_ref()
            .is_none_or(|session| session.diff_mode() == DiffMode::Auto)
        {
            return Err("explicit diff mode was lost after wide resize".to_owned());
        }
        self.save_workspace();
        Ok(())
    }

    #[cfg(feature = "ui-smoke")]
    fn validate_smoke_persistence(&self, expectations: &[SmokeExpectation]) -> Result<(), String> {
        let store = self
            .store
            .as_ref()
            .ok_or_else(|| "smoke requires an isolated persistent store".to_owned())?;
        for expected in expectations {
            let session = store
                .load_review_session(&expected.repository, expected.number)
                .map_err(|error| format!("cannot reload PR #{}: {error:#}", expected.number))?;
            if session.is_viewed(&expected.file_key) != expected.viewed {
                return Err(format!(
                    "queued save for PR #{} did not preserve its latest viewed state",
                    expected.number
                ));
            }
        }
        Ok(())
    }

    #[cfg(not(feature = "ui-smoke"))]
    fn start_smoke(&mut self, _: &mut Window, _: &mut Context<Root>) {}

    #[cfg(feature = "ui-smoke")]
    fn start_lifecycle_smoke(
        &mut self,
        window: &mut Window,
        cx: &mut Context<Root>,
        output: PathBuf,
        second_pr: Option<u64>,
    ) {
        let submitted_draft_phase = std::env::var("CIBERGIT_SMOKE_SUBMITTED_DRAFT_PHASE")
            .unwrap_or_else(|_| "populate".into());
        let mut primary_number = self
            .active_tab
            .and_then(|index| self.tabs.get(index))
            .map(|tab| tab.pull_request.number)
            .unwrap_or_default();
        let mut second_requested = false;
        if let Some(second) = second_pr.filter(|second| *second != primary_number)
            && let Some(active) = self.active_tab
            && let Some(repository_index) = self.repositories.iter().position(|runtime| {
                runtime.repository.cache_key() == self.tabs[active].repository.cache_key()
            })
        {
            self.open_pr(repository_index, second, cx);
            second_requested = true;
        }
        let weak = cx.weak_entity();
        window
            .spawn(cx, async move |window| {
                let started = std::time::Instant::now();
                let readiness_satisfied: bool;
                loop {
                    window
                        .background_executor()
                        .timer(Duration::from_millis(250))
                        .await;
                    if primary_number == 0 {
                        primary_number = window
                            .update(|_, cx| {
                                weak.read_with(cx, |root, _| {
                                    let Root::Review(this) = root else { return 0 };
                                    this.active_tab
                                        .and_then(|index| this.tabs.get(index))
                                        .map(|tab| tab.pull_request.number)
                                        .unwrap_or_default()
                                })
                                .unwrap_or_default()
                            })
                            .unwrap_or_default();
                    }
                    if !second_requested
                        && let Some(second) = second_pr.filter(|second| *second != primary_number)
                    {
                        second_requested = window
                            .update(|_, cx| {
                                weak.update(cx, |root, cx| {
                                    let Root::Review(this) = root else { return false };
                                    let Some(repository_key) = this
                                        .tabs
                                        .iter()
                                        .find(|tab| tab.pull_request.number == primary_number)
                                        .map(|tab| tab.repository.cache_key())
                                    else {
                                        return false;
                                    };
                                    let Some(repository_index) =
                                        this.repositories.iter().position(|runtime| {
                                            runtime.repository.cache_key() == repository_key
                                        })
                                    else {
                                        return false;
                                    };
                                    this.open_pr(repository_index, second, cx);
                                    true
                                })
                                .unwrap_or(false)
                            })
                            .unwrap_or(false);
                    }
                    let ready = window
                        .update(|_, cx| {
                            weak.read_with(cx, |root, _| {
                                matches!(root, Root::Review(this) if this.smoke_ready()
                                    && [Some(primary_number), second_pr]
                                        .into_iter()
                                        .flatten()
                                        .all(|number| this.tabs.iter().any(|tab| {
                                            tab.pull_request.number == number
                                                && tab.lifecycle.snapshot.is_some()
                                                && tab.lifecycle.choices.is_some()
                                                && tab.details.is_some()
                                                && tab.submitted_summary_editor.is_ready()
                                                && !matches!(tab.lifecycle_state, LoadState::Loading(_))
                                        })))
                            })
                            .unwrap_or(false)
                        })
                        .unwrap_or(false);
                    if ready {
                        readiness_satisfied = true;
                        break;
                    }
                    if started.elapsed() > Duration::from_secs(90) {
                        readiness_satisfied = false;
                        break;
                    }
                }
                let _ = std::fs::create_dir_all(&output);
                if !readiness_satisfied {
                    let readiness = window
                        .update(|_, cx| {
                            weak.read_with(cx, |root, _| {
                                let Root::Review(this) = root else {
                                    return "workspace=not-review".to_owned();
                                };
                                [Some(primary_number), second_pr]
                                    .into_iter()
                                    .flatten()
                                    .map(|number| {
                                        let Some(tab) = this
                                            .tabs
                                            .iter()
                                            .find(|tab| tab.pull_request.number == number)
                                        else {
                                            return format!("PR #{number}: tab=missing");
                                        };
                                        format!(
                                            "PR #{number}: tab=present details={} lifecycle_snapshot={} lifecycle_choices={} lifecycle_not_loading={} lifecycle_notice={:?}",
                                            tab.details.is_some(),
                                            tab.lifecycle.snapshot.is_some(),
                                            tab.lifecycle.choices.is_some(),
                                            !matches!(tab.lifecycle_state, LoadState::Loading(_)),
                                            tab.lifecycle_state.notice(),
                                        )
                                    })
                                    .collect::<Vec<_>>()
                                    .join("\n")
                            })
                            .unwrap_or_else(|error| format!("entity unavailable: {error:#}"))
                        })
                        .unwrap_or_else(|error| format!("window unavailable: {error:#}"));
                    let report = format!(
                        "Native lifecycle readiness failed before synthetic submitted-review scenes.\n{readiness}\nMutation transport: not invoked; ZERO updatePullRequestReview and zero live writes.\n"
                    );
                    let _ = std::fs::write(
                        output.join("native-lifecycle-readiness-failure.txt"),
                        &report,
                    );
                    panic!("native lifecycle readiness failed before synthetic scenes: {readiness}");
                }
                let _ = window.update(|window, cx| {
                    let _ = weak.update(cx, |root, cx| {
                        if let Root::Review(this) = root
                            && let Some(primary) = this.tabs.iter().position(|tab| {
                                tab.pull_request.number == primary_number
                            })
                        {
                            this.activate_tab(primary, window, cx);
                        }
                    });
                });
                let before = window
                    .update(|_, cx| {
                        weak.read_with(cx, |root, _| {
                            let Root::Review(this) = root else {
                                return Err("lifecycle smoke left review workspace".to_owned());
                            };
                            let index = this
                                .active_tab
                                .ok_or_else(|| "lifecycle smoke has no tab".to_owned())?;
                            let tab = &this.tabs[index];
                            let snapshot = tab.lifecycle.snapshot.as_ref().ok_or_else(|| {
                                tab.lifecycle_state.notice().unwrap_or_else(|| {
                                    "real lifecycle read unavailable".into()
                                })
                            })?;
                            Ok((
                                tab.canonical_full_revision.clone(),
                                tab.session.as_ref().map(|session| session.revision().clone()),
                                snapshot.title.clone(),
                                snapshot.viewer_login.clone(),
                                snapshot.values_complete,
                                snapshot.capabilities_complete,
                            ))
                        })
                        .unwrap_or_else(|error| Err(format!("smoke entity unavailable: {error:#}")))
                    })
                    .unwrap_or_else(|error| Err(format!("smoke window unavailable: {error:#}")));
                let _ = window.update(|_, cx| {
                    let _ = weak.update(cx, |root, cx| {
                        if let Root::Review(this) = root {
                            this.inspector_scroll.set_offset(point(px(0.), px(0.)));
                            cx.notify();
                        }
                    });
                });
                window
                    .background_executor()
                    .timer(Duration::from_millis(300))
                    .await;
                let real_read_captured = before.is_ok()
                    && window
                        .update(|window, _| {
                            window
                                .render_to_image()
                                .and_then(|image| {
                                    image
                                        .save(output.join("native-lifecycle-real-read.png"))
                                        .map_err(Into::into)
                                })
                                .is_ok()
                        })
                        .unwrap_or(false);

                let restored_draft_witness = window
                    .update(|_, cx| {
                        weak.read_with(cx, |root, _| {
                            let Root::Review(this) = root else {
                                return false;
                            };
                            let Some(index) = this.active_tab else {
                                return false;
                            };
                            let restored = this.tabs[index]
                                .submitted_summary_editor
                                .drafts
                                .iter()
                                .find(|draft| {
                                    draft.review.coordinates.remote_id
                                        == "SYNTHETIC_OWNED_SUBMITTED_REVIEW_NO_DISPATCH"
                                });
                            if submitted_draft_phase == "restart" {
                                restored.is_some_and(|draft| {
                                    draft.body == SMOKE_SUBMITTED_DRAFT
                                        && draft.review.edit_summary_capability.is_none()
                                })
                            } else {
                                restored.is_none()
                            }
                        })
                        .unwrap_or(false)
                    })
                    .unwrap_or(false);
                let restored_draft_captured = if submitted_draft_phase == "restart"
                    && restored_draft_witness
                {
                    let _ = window.update(|_, cx| {
                        let _ = weak.update(cx, |root, cx| {
                            if let Root::Review(this) = root
                                && let Some(index) = this.active_tab
                            {
                                this.tabs[index].inspector_section = InspectorSection::Activity;
                                this.inspector_scroll.set_offset(point(px(0.), px(0.)));
                                cx.notify();
                            }
                        });
                    });
                    window
                        .background_executor()
                        .timer(Duration::from_millis(300))
                        .await;
                    window
                        .update(|window, _| {
                            window
                                .render_to_image()
                                .and_then(|image| {
                                    image
                                        .save(output.join("native-submitted-summary-restored.png"))
                                        .map_err(Into::into)
                                })
                                .is_ok()
                        })
                        .unwrap_or(false)
                } else {
                    submitted_draft_phase == "populate"
                };

                let metadata_scene = window
                    .update(|window, cx| {
                        weak.update(cx, |root, cx| {
                            let Root::Review(this) = root else {
                                return Err("lifecycle smoke left review workspace".to_owned());
                            };
                            let index = this.active_tab.ok_or_else(|| "no active tab".to_owned())?;
                            let mut synthetic_snapshot = this.tabs[index]
                                .lifecycle
                                .snapshot
                                .as_ref()
                                .ok_or_else(|| "no lifecycle snapshot".to_owned())?
                                .clone();
                            synthetic_snapshot.can_update_metadata.available = true;
                            synthetic_snapshot.can_update_metadata.reason = None;
                            synthetic_snapshot.can_comment.available = true;
                            synthetic_snapshot.can_comment.reason = None;
                            this.tabs[index]
                                .lifecycle
                                .install_snapshot(synthetic_snapshot)?;
                            this.begin_metadata_edit(window, cx);
                            let snapshot = this.tabs[index]
                                .lifecycle
                                .snapshot
                                .as_ref()
                                .expect("synthetic snapshot installed")
                                .clone();
                            let synthetic = format!("{} [synthetic confirmation only]", snapshot.title);
                            this.tabs[index].lifecycle.stage_metadata(
                                synthetic.clone(),
                                snapshot.body.clone(),
                                snapshot.base_branch.clone(),
                            );
                            this.metadata_title_input.update(cx, |input, cx| {
                                input.set_value(synthetic.clone(), window, cx)
                            });
                            this.tabs[index].lifecycle.stage_metadata(
                                synthetic,
                                snapshot.body,
                                snapshot.base_branch,
                            );
                            let operation_id = next_attempt_id("synthetic-lifecycle-smoke");
                            let attempt_id = next_attempt_id(&operation_id);
                            this.tabs[index]
                                .lifecycle
                                .prepare_metadata_apply(operation_id, attempt_id)?;
                            if this.tabs[index].lifecycle.confirmation.is_none() {
                                return Err(this.status.clone());
                            }
                            this.tabs[index].inspector_section = InspectorSection::Overview;
                            this.inspector_scroll.set_offset(point(px(0.), px(0.)));
                            Ok(())
                        })
                        .unwrap_or_else(|error| Err(format!("smoke entity unavailable: {error:#}")))
                    })
                    .unwrap_or_else(|error| Err(format!("smoke window unavailable: {error:#}")));
                window
                    .background_executor()
                    .timer(Duration::from_millis(350))
                    .await;
                let metadata_captured = metadata_scene.is_ok()
                    && window
                        .update(|window, _| {
                            window
                                .render_to_image()
                                .and_then(|image| {
                                    image
                                        .save(output.join("native-lifecycle-synthetic-metadata.png"))
                                        .map_err(Into::into)
                                })
                                .is_ok()
                        })
                        .unwrap_or(false);

                let activity_scene = window
                    .update(|window, cx| {
                        weak.update(cx, |root, cx| {
                            let Root::Review(this) = root else {
                                return Err("lifecycle smoke left review workspace".to_owned());
                            };
                            let index = this.active_tab.ok_or_else(|| "no active tab".to_owned())?;
                            this.tabs[index].lifecycle.cancel_metadata();
                            this.tabs[index].lifecycle.cancel_confirmation();
                            let repository = this.tabs[index].repository.clone();
                            let number = this.tabs[index].pull_request.number;
                            let viewer = this.tabs[index]
                                .lifecycle
                                .snapshot
                                .as_ref()
                                .ok_or_else(|| "no lifecycle snapshot".to_owned())?
                                .viewer_login
                                .clone();
                            let comment = cibergit::domain::IssueComment {
                                coordinates: cibergit::domain::ProviderCoordinates {
                                    provider: "github".into(),
                                    host: repository.host.clone(),
                                    owner: repository.owner.clone(),
                                    repository: repository.name.clone(),
                                    pull_request: number,
                                    remote_id: "SYNTHETIC_NO_DISPATCH_COMMENT_ID".into(),
                                },
                                author: Some(viewer),
                                body: "Synthetic exact-ID comment. No provider mutation is dispatched by this scene."
                                    .into(),
                                created_at: "2026-09-13T12:00:00Z".into(),
                                updated_at: "2026-09-13T12:00:00Z".into(),
                                url: String::new(),
                            };
                            let details = this.tabs[index]
                                .details
                                .as_mut()
                                .ok_or_else(|| "real details read unavailable".to_owned())?;
                            details.issue_comments.insert(0, comment.clone());
                            this.tabs[index].inspector_section = InspectorSection::Activity;
                            this.begin_comment_edit(comment, window, cx);
                            this.tabs[index].lifecycle.stage_discussion_body(
                                "Synthetic edited body frozen for native confirmation; no remote write."
                                    .into(),
                            );
                            this.discussion_input.update(cx, |input, cx| {
                                input.set_value(
                                    "Synthetic edited body frozen for native confirmation; no remote write.",
                                    window,
                                    cx,
                                )
                            });
                            let operation_id = next_attempt_id("synthetic-discussion-smoke");
                            let attempt_id = next_attempt_id(&operation_id);
                            this.tabs[index]
                                .lifecycle
                                .prepare_discussion_apply(operation_id, attempt_id)?;
                            if this.tabs[index].lifecycle.confirmation.is_none() {
                                return Err(this.status.clone());
                            }
                            this.inspector_scroll.set_offset(point(px(0.), px(0.)));
                            Ok(())
                        })
                        .unwrap_or_else(|error| Err(format!("smoke entity unavailable: {error:#}")))
                    })
                    .unwrap_or_else(|error| Err(format!("smoke window unavailable: {error:#}")));
                let _ = window.update(|window, _| window.resize(size(px(1040.), px(760.))));
                window
                    .background_executor()
                    .timer(Duration::from_millis(350))
                    .await;
                let activity_captured = activity_scene.is_ok()
                    && window
                        .update(|window, _| {
                            window
                                .render_to_image()
                                .and_then(|image| {
                                    image
                                        .save(output.join(
                                            "native-lifecycle-synthetic-activity-narrow.png",
                                        ))
                                        .map_err(Into::into)
                                })
                                .is_ok()
                        })
                        .unwrap_or(false);

                let submitted_scene = window
                    .update(|window, cx| {
                        weak.update(cx, |root, cx| {
                            let Root::Review(this) = root else {
                                return Err("submitted-review smoke left review workspace".to_owned());
                            };
                            let index = this.active_tab.ok_or_else(|| "no active tab".to_owned())?;
                            this.tabs[index].lifecycle.cancel_confirmation();
                            let repository = this.tabs[index].repository.clone();
                            let number = this.tabs[index].pull_request.number;
                            let viewer = this.tabs[index]
                                .lifecycle
                                .snapshot
                                .as_ref()
                                .ok_or_else(|| "no lifecycle snapshot".to_owned())?
                                .viewer_login
                                .clone();
                            let reviewed_commit = this.tabs[index]
                                .canonical_session
                                .as_ref()
                                .ok_or_else(|| "no canonical review session".to_owned())?
                                .revision()
                                .head_sha
                                .clone();
                            let review = cibergit::domain::PullRequestReview {
                                coordinates: cibergit::domain::ProviderCoordinates {
                                    provider: "github".into(),
                                    host: repository.host.clone(),
                                    owner: repository.owner.clone(),
                                    repository: repository.name.clone(),
                                    pull_request: number,
                                    remote_id: "SYNTHETIC_OWNED_SUBMITTED_REVIEW_NO_DISPATCH".into(),
                                },
                                author: Some(viewer),
                                body: "Synthetic original submitted summary. No provider write is permitted by this scene."
                                    .into(),
                                state: "COMMENTED".into(),
                                submitted_at: Some("2026-09-13T12:00:00Z".into()),
                                commit_sha: Some(reviewed_commit),
                                edit_summary_capability: Some(
                                    cibergit::domain::SubmittedReviewEditCapability {
                                        viewer_did_author: true,
                                        viewer_can_update: true,
                                        viewer_cannot_update_reasons: Vec::new(),
                                    },
                                ),
                                url: String::new(),
                            };
                            let mut second_review = review.clone();
                            second_review.coordinates.remote_id =
                                "SYNTHETIC_SECOND_OWNED_REVIEW_NO_DISPATCH".into();
                            second_review.body = "Synthetic second original summary.".into();
                            this.tabs[index]
                                .details
                                .as_mut()
                                .ok_or_else(|| "real details read unavailable".to_owned())?
                                .reviews
                                .splice(0..0, [review.clone(), second_review.clone()]);
                            this.tabs[index].inspector_section = InspectorSection::Activity;
                            this.tabs[index].review_page = 0;
                            this.begin_submitted_summary_edit(review.clone(), window, cx);
                            this.submitted_summary_input.update(cx, |input, cx| {
                                input.set_value(SMOKE_SUBMITTED_DRAFT, window, cx)
                            });
                            this.begin_submitted_summary_edit(review.clone(), window, cx);
                            let repeated_a_retained = this
                                .submitted_summary_input
                                .read(cx)
                                .value()
                                .contains("zero update mutation transport");
                            this.begin_submitted_summary_edit(second_review.clone(), window, cx);
                            this.submitted_summary_input.update(cx, |input, cx| {
                                input.set_value(
                                    "Synthetic typed draft B; zero transport.",
                                    window,
                                    cx,
                                )
                            });
                            this.begin_submitted_summary_edit(review.clone(), window, cx);
                            let a_after_b_retained = this
                                .submitted_summary_input
                                .read(cx)
                                .value()
                                .contains("zero update mutation transport");
                            this.begin_submitted_summary_edit(second_review, window, cx);
                            let b_after_a_retained = this
                                .submitted_summary_input
                                .read(cx)
                                .value()
                                .contains("typed draft B");
                            this.begin_submitted_summary_edit(review, window, cx);
                            let per_review_draft_routing =
                                repeated_a_retained && a_after_b_retained && b_after_a_retained;
                            let mut cross_tab_editor_restore = second_pr.is_none();
                            if let Some(second) = second_pr
                                && let Some(second_index) = this
                                    .tabs
                                    .iter()
                                    .position(|tab| tab.pull_request.number == second)
                            {
                                this.activate_tab(second_index, window, cx);
                                let secondary_empty = this
                                    .submitted_summary_input
                                    .read(cx)
                                    .value()
                                    .is_empty();
                                this.activate_tab(index, window, cx);
                                let primary_restored = this
                                    .submitted_summary_input
                                    .read(cx)
                                    .value()
                                    .contains("zero update mutation transport");
                                cross_tab_editor_restore = secondary_empty && primary_restored;
                            }
                            Ok((
                                repository,
                                number,
                                per_review_draft_routing,
                                cross_tab_editor_restore,
                            ))
                        })
                        .unwrap_or_else(|error| Err(format!("smoke entity unavailable: {error:#}")))
                    })
                    .unwrap_or_else(|error| Err(format!("smoke window unavailable: {error:#}")));
                let durable_started = std::time::Instant::now();
                let submitted_durable = loop {
                    let durable = window
                        .update(|_, cx| {
                            weak.read_with(cx, |root, _| {
                                let Root::Review(this) = root else { return false };
                                this.active_tab.is_some_and(|index| {
                                    this.tabs[index]
                                        .submitted_summary_editor
                                        .is_current_durable()
                                })
                            })
                            .unwrap_or(false)
                        })
                        .unwrap_or(false);
                    if durable || durable_started.elapsed() > Duration::from_secs(10) {
                        break durable;
                    }
                    window
                        .background_executor()
                        .timer(Duration::from_millis(100))
                        .await;
                };
                let submitted_scene = if let Ok((
                    repository,
                    number,
                    per_review_draft_routing,
                    cross_tab_editor_restore,
                )) = submitted_scene
                    && submitted_durable
                {
                    window
                        .update(|window, cx| {
                            weak.update(cx, |root, cx| {
                                let Root::Review(this) = root else {
                                    return Err(
                                        "submitted-review smoke left review workspace".to_owned()
                                    );
                                };
                                let index = this
                                    .active_tab
                                    .ok_or_else(|| "no active submitted-review tab".to_owned())?;
                                this.prepare_submitted_summary_confirmation(cx);
                                let Some(NativeConfirmation::UpdateSubmittedSummary {
                                    generation,
                                    action,
                                }) = this.tabs[index].confirmation.as_ref()
                                else {
                                    return Err(this.status.clone());
                                };
                                let token = SubmittedConfirmationToken {
                                    workspace_instance: this.workspace_instance,
                                    tab_instance: this.tabs[index].instance_generation,
                                    repository_key: repository.cache_key(),
                                    pull_request: number,
                                    confirmation_generation: *generation,
                                    action: action.as_ref().clone(),
                                };
                                let mut cross_tab_stale_handler = second_pr.is_none();
                                if let Some(second) = second_pr
                                    && let Some(second_index) = this
                                        .tabs
                                        .iter()
                                        .position(|tab| tab.pull_request.number == second)
                                {
                                    this.activate_tab(second_index, window, cx);
                                    let stale_cancel_rejected =
                                        !this.cancel_submitted_summary_confirmation(&token, cx);
                                    let primary_confirmation_retained = this.tabs[index]
                                        .confirmation
                                        .as_ref()
                                        .is_some_and(|confirmation| {
                                            token.matches_values(
                                                this.workspace_instance,
                                                this.tabs[index].instance_generation,
                                                &this.tabs[index].repository.cache_key(),
                                                this.tabs[index].pull_request.number,
                                                Some(confirmation),
                                            )
                                        });
                                    this.activate_tab(index, window, cx);
                                    cross_tab_stale_handler =
                                        stale_cancel_rejected && primary_confirmation_retained;
                                }
                                this.inspector_scroll.set_offset(point(px(0.), px(0.)));
                                Ok((
                                    token,
                                    per_review_draft_routing,
                                    cross_tab_editor_restore,
                                    cross_tab_stale_handler,
                                ))
                            })
                            .unwrap_or_else(|error| {
                                Err(format!("smoke entity unavailable: {error:#}"))
                            })
                        })
                        .unwrap_or_else(|error| {
                            Err(format!("smoke window unavailable: {error:#}"))
                        })
                } else {
                    Err("submitted-review synthetic draft did not become durable".to_owned())
                };
                window
                    .background_executor()
                    .timer(Duration::from_millis(350))
                    .await;
                let submitted_captured = submitted_scene.is_ok()
                    && window
                        .update(|window, _| {
                            window
                                .render_to_image()
                                .and_then(|image| {
                                    image
                                        .save(output.join("native-submitted-summary-confirmation.png"))
                                        .map_err(Into::into)
                                })
                                .is_ok()
                        })
                        .unwrap_or(false);
                let submitted_continuation_scrolled = submitted_scene.is_ok()
                    && window
                        .update(|_, cx| {
                            weak.update(cx, |root, cx| {
                                let Root::Review(this) = root else { return false };
                                let maximum = this.inspector_scroll.max_offset().y;
                                let continuation_offset = maximum.min(px(420.));
                                this.inspector_scroll
                                    .set_offset(point(px(0.), -continuation_offset));
                                cx.notify();
                                continuation_offset > px(0.)
                            })
                            .unwrap_or(false)
                        })
                        .unwrap_or(false);
                window
                    .background_executor()
                    .timer(Duration::from_millis(350))
                    .await;
                let submitted_continuation_captured = submitted_continuation_scrolled
                    && window
                        .update(|window, _| {
                            window
                                .render_to_image()
                                .and_then(|image| {
                                    image
                                        .save(output.join(
                                            "native-submitted-summary-confirmation-continuation.png",
                                        ))
                                        .map_err(Into::into)
                                })
                                .is_ok()
                        })
                        .unwrap_or(false);
                let submitted_cancelled = if let Ok((token, _, _, _)) = &submitted_scene {
                    window
                        .update(|_, cx| {
                            weak.update(cx, |root, cx| {
                                let Root::Review(this) = root else { return false };
                                this.cancel_submitted_summary_confirmation(token, cx)
                            })
                            .unwrap_or(false)
                        })
                        .unwrap_or(false)
                } else {
                    false
                };
                let confirmation_aba_guard = if submitted_cancelled
                    && let Ok((old_token, _, _, _)) = &submitted_scene
                {
                    window
                        .update(|_, cx| {
                            weak.update(cx, |root, cx| {
                                let Root::Review(this) = root else { return false };
                                let Some(index) = this.active_tab else { return false };
                                this.prepare_submitted_summary_confirmation(cx);
                                let Some(NativeConfirmation::UpdateSubmittedSummary {
                                    generation,
                                    action,
                                }) = this.tabs[index].confirmation.as_ref()
                                else {
                                    return false;
                                };
                                let new_token = SubmittedConfirmationToken {
                                    workspace_instance: this.workspace_instance,
                                    tab_instance: this.tabs[index].instance_generation,
                                    repository_key: this.tabs[index].repository.cache_key(),
                                    pull_request: this.tabs[index].pull_request.number,
                                    confirmation_generation: *generation,
                                    action: action.as_ref().clone(),
                                };
                                let generation_advanced = new_token.confirmation_generation
                                    > old_token.confirmation_generation;
                                let stale_cancel_rejected =
                                    !this.cancel_submitted_summary_confirmation(old_token, cx);
                                let new_confirmation_retained = this.tabs[index]
                                    .confirmation
                                    .as_ref()
                                    .is_some_and(|confirmation| {
                                        new_token.matches_values(
                                            this.workspace_instance,
                                            this.tabs[index].instance_generation,
                                            &this.tabs[index].repository.cache_key(),
                                            this.tabs[index].pull_request.number,
                                            Some(confirmation),
                                        )
                                    });
                                let new_cancelled =
                                    this.cancel_submitted_summary_confirmation(&new_token, cx);
                                generation_advanced
                                    && stale_cancel_rejected
                                    && new_confirmation_retained
                                    && new_cancelled
                            })
                            .unwrap_or(false)
                        })
                        .unwrap_or(false)
                } else {
                    false
                };
                let per_review_draft_routing = submitted_scene
                    .as_ref()
                    .is_ok_and(|(_, routed, _, _)| *routed);
                let cross_tab_editor_restore = submitted_scene
                    .as_ref()
                    .is_ok_and(|(_, _, restored, _)| *restored);
                let cross_tab_stale_handler = submitted_scene
                    .as_ref()
                    .is_ok_and(|(_, _, _, rejected)| *rejected);
                let submitted_draft_retained = window
                    .update(|_, cx| {
                        weak.read_with(cx, |root, _| {
                            let Root::Review(this) = root else { return false };
                            let Some(index) = this.active_tab else { return false };
                            this.tabs[index].confirmation.is_none()
                                && this.tabs[index]
                                    .submitted_summary_editor
                                    .active_draft()
                                    .is_some_and(|draft| {
                                        draft.body.contains("zero update mutation transport")
                                    })
                        })
                        .unwrap_or(false)
                    })
                    .unwrap_or(false);
                let changed_source_draft_retained = window
                    .update(|window, cx| {
                        weak.update(cx, |root, cx| {
                            let Root::Review(this) = root else { return false };
                            let Some(index) = this.active_tab else { return false };
                            let Some(details) = this.tabs[index].details.as_mut() else {
                                return false;
                            };
                            let Some(review) = details.reviews.iter_mut().find(|review| {
                                review.coordinates.remote_id
                                    == "SYNTHETIC_OWNED_SUBMITTED_REVIEW_NO_DISPATCH"
                            }) else {
                                return false;
                            };
                            review.body = "Synthetic source changed after editing began.".into();
                            let refreshed_review = review.clone();
                            this.prepare_submitted_summary_confirmation(cx);
                            let rejected_with_draft = this.tabs[index].confirmation.is_none()
                                && this.tabs[index]
                                    .submitted_summary_editor
                                    .active_draft()
                                    .is_some_and(|draft| {
                                        draft.body.contains("zero update mutation transport")
                                    });
                            this.begin_submitted_summary_edit(refreshed_review, window, cx);
                            let adopted_with_draft = this
                                .submitted_summary_input
                                .read(cx)
                                .value()
                                .contains("zero update mutation transport")
                                && this.tabs[index]
                                    .submitted_summary_editor
                                    .active_draft()
                                    .is_some_and(|draft| {
                                        draft.review.body
                                            == "Synthetic source changed after editing began."
                                    });
                            rejected_with_draft && adopted_with_draft
                        })
                        .unwrap_or(false)
                    })
                    .unwrap_or(false);

                let unchanged = window
                    .update(|_, cx| {
                        weak.read_with(cx, |root, _| {
                            let Root::Review(this) = root else { return false };
                            let Some(index) = this.active_tab else { return false };
                            let Ok((canonical, selected, ..)) = &before else {
                                return false;
                            };
                            this.tabs[index].canonical_full_revision == *canonical
                                && this.tabs[index]
                                    .session
                                    .as_ref()
                                    .map(|session| session.revision().clone())
                                    == *selected
                                && this.tabs[index].lifecycle.active_operation.is_none()
                        })
                        .unwrap_or(false)
                    })
                    .unwrap_or(false);
                let late_journal_callback_fenced = window
                    .update(|_, cx| {
                        weak.update(cx, |root, _| {
                            let Root::Review(this) = root else { return false };
                            let Some(index) = this.active_tab else { return false };
                            let workspace_instance = this.workspace_instance;
                            let tab_instance = this.tabs[index].instance_generation;
                            let repository_key = this.tabs[index].repository.cache_key();
                            let pull_request = this.tabs[index].pull_request.number;
                            let sentinel = JournalOperation {
                                request: JournalRequest::Auxiliary(Box::new(
                                    ReviewAuxiliaryRequest {
                                        operation_id: "native-reconciliation-sentinel".into(),
                                        attempt_id: "native-reconciliation-sentinel-attempt"
                                            .into(),
                                        action: ReviewAuxiliaryAction::Reply {
                                            thread: cibergit::domain::ProviderCoordinates {
                                                provider: "github".into(),
                                                host: this.tabs[index].repository.host.clone(),
                                                owner: this.tabs[index].repository.owner.clone(),
                                                repository: this.tabs[index]
                                                    .repository
                                                    .name
                                                    .clone(),
                                                pull_request,
                                                remote_id: "native-sentinel-thread".into(),
                                            },
                                            pending_review: None,
                                            body: "native sentinel body".into(),
                                        },
                                    },
                                )),
                                status: JournalStatus::Uncertain {
                                    reason: "native sentinel outcome".into(),
                                },
                            };
                            let saved_operations = std::mem::replace(
                                &mut this.tabs[index].journal_operations,
                                vec![sentinel.clone()],
                            );
                            let saved_error = this.tabs[index]
                                .journal_error
                                .replace("native sentinel journal error".into());
                            let saved_busy = std::mem::replace(
                                &mut this.tabs[index].write_in_flight,
                                true,
                            );
                            let saved_status = this.status.clone();
                            let stale_workspace = ActionJournalCompletionToken {
                                workspace_instance: workspace_instance.wrapping_add(1),
                                tab_instance,
                                repository_key: repository_key.clone(),
                                pull_request,
                            };
                            let rejected_success = this
                                .apply_action_journal_completion(
                                    &stale_workspace,
                                    Ok((1, Vec::new(), Vec::new())),
                                )
                                .is_none()
                                && this.tabs[index].write_in_flight
                                && this.tabs[index].journal_operations == [sentinel.clone()]
                                && this.tabs[index].journal_error.as_deref()
                                    == Some("native sentinel journal error")
                                && this.status == saved_status;
                            let stale_tab = ActionJournalCompletionToken {
                                workspace_instance,
                                tab_instance: tab_instance.wrapping_add(1),
                                repository_key,
                                pull_request,
                            };
                            let rejected_error = this
                                .apply_action_journal_completion(
                                    &stale_tab,
                                    Err("synthetic late reconciliation error".into()),
                                )
                                .is_none()
                                && this.tabs[index].write_in_flight
                                && this.tabs[index].journal_operations == [sentinel]
                                && this.tabs[index].journal_error.as_deref()
                                    == Some("native sentinel journal error")
                                && this.status == saved_status;
                            this.tabs[index].journal_operations = saved_operations;
                            this.tabs[index].journal_error = saved_error;
                            this.tabs[index].write_in_flight = saved_busy;
                            rejected_success && rejected_error
                        })
                        .unwrap_or(false)
                    })
                    .unwrap_or(false);
                let (real_title, viewer, values_complete, capabilities_complete) = before
                    .as_ref()
                    .map(|(_, _, title, viewer, values, capabilities)| {
                        (title.as_str(), viewer.as_str(), *values, *capabilities)
                    })
                    .unwrap_or(("unavailable", "unavailable", false, false));
                let secondary_target = second_pr
                    .map(|number| format!("cli/cli#{number}"))
                    .unwrap_or_else(|| "none".into());
                let passed = real_read_captured
                    && restored_draft_witness
                    && restored_draft_captured
                    && metadata_captured
                    && activity_captured
                    && submitted_captured
                    && submitted_continuation_captured
                    && submitted_cancelled
                    && confirmation_aba_guard
                    && submitted_draft_retained
                    && changed_source_draft_retained
                    && per_review_draft_routing
                    && cross_tab_editor_restore
                    && cross_tab_stale_handler
                    && late_journal_callback_fenced
                    && unchanged;
                let report = format!(
                    "Native PR lifecycle and submitted-summary smoke: {}\nSubmitted-draft phase: {}\nSynthetic saved-draft witness (exact text, historical source has no capability): {}\nRestart recovery capture or populate precondition: {}\nExact read-only target pair: cli/cli#{}, secondary {}\nReal read-only provider preparation: cli/cli snapshot title {:?}, selected account {}, values_complete={}, capabilities_complete={}\nSynthetic metadata confirmation capture: {}\nSynthetic exact-ID discussion confirmation capture: {}\nClearly labelled synthetic owned-review summary top capture: {}\nSubmitted-summary bottom continuation capture showing remaining disclosure/warning/controls: {}\nSubmitted-summary cancellation through exact native handler: {}\nCancelled/reprepared identical confirmation rejects the stale native handler token: {}\nPer-review A→B→A and repeated-edit typed drafts retained: {}\nCross-tab editor save/restore retained exact typed draft: {}\nCross-tab stale confirmation handler rejected and original retained: {}\nChanged-source rejection plus explicit refresh retained typed draft: {}\nActual journal completion apply rejected stale success and error without changing busy/sentinel state: {}\nCanonical and selected comparison identities unchanged: {}\nMutation transport: not invoked; ZERO updatePullRequestReview and zero live metadata/comment/review/merge writes\nWindow focus requested: false when CIBERGIT_SMOKE_BACKGROUND=1\nPhysical input is not implied by an in-process scene render.\n",
                    if passed { "passed" } else { "failed" },
                    submitted_draft_phase,
                    restored_draft_witness,
                    restored_draft_captured,
                    primary_number,
                    secondary_target,
                    real_title,
                    viewer,
                    values_complete,
                    capabilities_complete,
                    metadata_captured,
                    activity_captured,
                    submitted_captured,
                    submitted_continuation_captured,
                    submitted_cancelled,
                    confirmation_aba_guard,
                    submitted_draft_retained && per_review_draft_routing,
                    cross_tab_editor_restore,
                    cross_tab_stale_handler,
                    changed_source_draft_retained,
                    late_journal_callback_fenced,
                    unchanged,
                );
                let _ = std::fs::write(output.join("native-lifecycle-smoke.txt"), report);
                if !passed {
                    panic!(
                        "native lifecycle smoke failed: before={before:?}, metadata={metadata_scene:?}, activity={activity_scene:?}, submitted={submitted_scene:?}"
                    );
                }
                let _ = window.update(|_, cx| cx.quit());
            })
            .detach();
    }

    fn add_repository(&mut self, cx: &mut Context<Root>) {
        let input = self.repository_input.read(cx).value().trim().to_owned();
        let Some(account) = self.accounts.get(self.selected_account).cloned() else {
            self.status = "Choose a discovered GitHub account".into();
            cx.notify();
            return;
        };
        if input.is_empty() {
            self.status = "Enter owner/name, a GitHub URL, or a local folder".into();
            cx.notify();
            return;
        }
        self.status = format!("Resolving {input} as {}…", account.login);
        let task =
            cx.background_spawn(async move { GithubProvider::new(account).repository(&input) });
        cx.spawn(async move |root, cx| {
            let result = task.await;
            let _ = root.update(cx, |root, cx| {
                let Root::Review(this) = root else { return };
                match result {
                    Ok(repository) => {
                        let key = repository.cache_key();
                        let existing = this
                            .repositories
                            .iter()
                            .position(|runtime| runtime.repository.cache_key() == key);
                        let index = if let Some(index) = existing {
                            index
                        } else {
                            this.workspace.add_repository(repository.clone());
                            this.repositories.push(RepoRuntime {
                                repository: repository.clone(),
                                pull_requests: Vec::new(),
                                state: LoadState::Loading("Loading pull requests…".into()),
                                generation: 0,
                                refresh: RefreshGate::default(),
                            });
                            this.save_workspace();
                            this.repositories.len() - 1
                        };
                        this.refresh_repository(index, cx);
                        this.refresh_notifications(cx);
                        if let Some(number) = this.startup_pr.take() {
                            this.open_pr_with_intent(
                                index,
                                number,
                                OpenPrIntent::ExplicitStartup,
                                None,
                                cx,
                            );
                        }
                        this.status = format!(
                            "Added {} for {}",
                            repository.full_name(),
                            repository.account.login
                        );
                        this.setup_open = false;
                    }
                    Err(error) => {
                        this.status = format!("Cannot add repository: {error:#}");
                    }
                }
                cx.notify();
            });
        })
        .detach();
    }

    #[cfg(feature = "ui-smoke")]
    fn start_comparison_smoke(
        &mut self,
        window: &mut Window,
        cx: &mut Context<Root>,
        output: PathBuf,
        second_pr: Option<u64>,
        expect_restore: bool,
    ) {
        let weak = cx.weak_entity();
        window
            .spawn(cx, async move |window| {
                let started = std::time::Instant::now();
                loop {
                    window
                        .background_executor()
                        .timer(Duration::from_millis(250))
                        .await;
                    let ready = window
                        .update(|_, cx| {
                            weak.read_with(cx, |root, _| {
                                matches!(root, Root::Review(this) if this.smoke_ready() && this.active_tab.is_some_and(|index| {
                                    !this.tabs[index].comparison_picker.inventory_loading
                                        && this.tabs[index].comparison_picker.inventory_ready()
                                }))
                            })
                            .unwrap_or(false)
                        })
                        .unwrap_or(false);
                    if ready || started.elapsed() > Duration::from_secs(90) {
                        break;
                    }
                }
                let _ = std::fs::create_dir_all(&output);
                if expect_restore {
                    let restored = window
                        .update(|window, cx| {
                            let valid = weak
                                .read_with(cx, |root, _| {
                                    matches!(root, Root::Review(this) if this.active_tab.is_some_and(|index| {
                                        matches!(this.tabs[index].comparison_picker.request, ComparisonRequest::CommitRange { .. })
                                            && this.tabs[index].session.as_ref().is_some_and(|session| session.revision() != &this.tabs[index].canonical_full_revision)
                                    }))
                                })
                                .unwrap_or(false);
                            valid
                                && window
                                    .render_to_image()
                                    .and_then(|image| {
                                        image
                                            .save(output.join("native-comparison-restart.png"))
                                            .map_err(Into::into)
                                    })
                                    .is_ok()
                        })
                        .unwrap_or(false);
                    let report = format!(
                        "Dark restart restored canonical full identity plus lossless CommitRange request and distinct selected pair: {}\nPhysical input / AX / acrylic material identity: not established by in-process capture\nRemote writes: none\n",
                        if restored { "passed" } else { "failed" }
                    );
                    let _ = std::fs::write(output.join("native-comparison-smoke.txt"), report);
                    if !restored {
                        panic!("comparison restart smoke failed");
                    }
                    let _ = window.update(|_, cx| cx.quit());
                    return;
                }

                let full_installed = window
                    .update(|_, cx| {
                        weak.update(cx, |root, cx| {
                            let Root::Review(this) = root else { return false };
                            let Some(index) = this.active_tab else { return false };
                            this.tabs[index].comparison_picker.expanded = true;
                            this.tabs[index].comparison_picker.editing_mode = PickerMode::Commit;
                            cx.notify();
                            true
                        })
                        .unwrap_or(false)
                    })
                    .unwrap_or(false);
                window
                    .background_executor()
                    .timer(Duration::from_millis(300))
                    .await;
                let full_ready = full_installed
                    && window
                        .update(|window, _| {
                            window
                                .render_to_image()
                                .and_then(|image| {
                                    image
                                        .save(output.join("native-comparison-full-list.png"))
                                        .map_err(Into::into)
                                })
                                .is_ok()
                        })
                        .unwrap_or(false);
                let commit_started = window
                    .update(|_, cx| {
                        weak.update(cx, |root, cx| {
                            let Root::Review(this) = root else { return false };
                            let Some(index) = this.active_tab else { return false };
                            this.select_picker_commit(index, 0, cx);
                            true
                        })
                        .unwrap_or(false)
                    })
                    .unwrap_or(false);
                for _ in 0..160 {
                    window
                        .background_executor()
                        .timer(Duration::from_millis(125))
                        .await;
                    let ready = window
                        .update(|_, cx| {
                            weak.read_with(cx, |root, _| {
                                matches!(root, Root::Review(this) if this.active_tab.is_some_and(|index| {
                                    matches!(this.tabs[index].comparison_picker.request, ComparisonRequest::Commit { .. })
                                        && !matches!(this.tabs[index].state, LoadState::Loading(_))
                                }))
                            })
                            .unwrap_or(false)
                        })
                        .unwrap_or(false);
                    if ready {
                        break;
                    }
                }
                let commit_captured = window
                    .update(|window, _| {
                        window
                            .render_to_image()
                            .and_then(|image| {
                                image
                                    .save(output.join("native-comparison-commit.png"))
                                    .map_err(Into::into)
                            })
                            .is_ok()
                    })
                    .unwrap_or(false);
                let range_started = window
                    .update(|_, cx| {
                        weak.update(cx, |root, cx| {
                            let Root::Review(this) = root else { return false };
                            let Some(index) = this.active_tab else { return false };
                            let count = this.tabs[index].comparison_picker.commits().len();
                            if count < 2
                                || this.tabs[index]
                                    .comparison_picker
                                    .begin_endpoint_selection(PickerMode::Range)
                                    .is_err()
                            {
                                return false;
                            }
                            this.select_picker_range_endpoint(index, 0, cx);
                            this.select_picker_range_endpoint(index, count - 1, cx);
                            true
                        })
                        .unwrap_or(false)
                    })
                    .unwrap_or(false);
                for _ in 0..160 {
                    window
                        .background_executor()
                        .timer(Duration::from_millis(125))
                        .await;
                    let ready = window
                        .update(|_, cx| {
                            weak.read_with(cx, |root, _| {
                                matches!(root, Root::Review(this) if this.active_tab.is_some_and(|index| {
                                    matches!(this.tabs[index].comparison_picker.request, ComparisonRequest::CommitRange { .. })
                                        && !matches!(this.tabs[index].state, LoadState::Loading(_))
                                }))
                            })
                            .unwrap_or(false)
                        })
                        .unwrap_or(false);
                    if ready {
                        break;
                    }
                }
                let range_captured = window
                    .update(|window, _| {
                        window
                            .render_to_image()
                            .and_then(|image| {
                                image
                                    .save(output.join("native-comparison-range.png"))
                                    .map_err(Into::into)
                            })
                            .is_ok()
                    })
                    .unwrap_or(false);
                let since_started = window
                    .update(|_, cx| {
                        weak.update(cx, |root, cx| {
                            let Root::Review(this) = root else { return false };
                            let Some(index) = this.active_tab else { return false };
                            this.select_comparison_request(
                                index,
                                ComparisonRequest::SinceLastReview {
                                    baseline: BaselineResolution::Unavailable(
                                        cibergit::comparisons::BaselineUnavailableReason::NoSubmittedReview,
                                    ),
                                },
                                cx,
                            );
                            true
                        })
                        .unwrap_or(false)
                    })
                    .unwrap_or(false);
                for _ in 0..160 {
                    window
                        .background_executor()
                        .timer(Duration::from_millis(125))
                        .await;
                    let ready = window
                        .update(|_, cx| {
                            weak.read_with(cx, |root, _| {
                                matches!(root, Root::Review(this) if this.active_tab.is_some_and(|index| {
                                    matches!(this.tabs[index].comparison_picker.request, ComparisonRequest::SinceLastReview { .. })
                                        && !matches!(this.tabs[index].state, LoadState::Loading(_))
                                }))
                            })
                            .unwrap_or(false)
                        })
                        .unwrap_or(false);
                    if ready {
                        break;
                    }
                }
                let since_captured = window
                    .update(|window, _| {
                        window
                            .render_to_image()
                            .and_then(|image| {
                                image
                                    .save(output.join("native-comparison-since-fallback.png"))
                                    .map_err(Into::into)
                            })
                            .is_ok()
                    })
                    .unwrap_or(false);
                let full_returned = window
                    .update(|_, cx| {
                        weak.update(cx, |root, cx| {
                            let Root::Review(this) = root else { return false };
                            let Some(index) = this.active_tab else { return false };
                            this.restore_full_comparison(index, cx);
                            true
                        })
                        .unwrap_or(false)
                    })
                    .unwrap_or(false);
                window
                    .background_executor()
                    .timer(Duration::from_millis(300))
                    .await;
                let full_return_captured = window
                    .update(|window, _| {
                        window
                            .render_to_image()
                            .and_then(|image| {
                                image
                                    .save(output.join("native-comparison-return-full.png"))
                                    .map_err(Into::into)
                            })
                            .is_ok()
                    })
                    .unwrap_or(false);
                let poll_indicator_installed = window
                    .update(|_, cx| {
                        weak.update(cx, |root, cx| {
                            let Root::Review(this) = root else { return false };
                            let Some(index) = this.active_tab else { return false };
                            let mut newer = this.tabs[index].canonical_full_revision.clone();
                            newer.head_sha = "f".repeat(40);
                            if let Some(session) = &mut this.tabs[index].canonical_session {
                                session.observe_revision(newer.clone());
                            }
                            if let Some(session) = &mut this.tabs[index].session {
                                session.observe_revision(newer);
                            }
                            cx.notify();
                            true
                        })
                        .unwrap_or(false)
                    })
                    .unwrap_or(false);
                window
                    .background_executor()
                    .timer(Duration::from_millis(300))
                    .await;
                let poll_indicator_captured = poll_indicator_installed
                    && window
                        .update(|window, _| {
                            window
                                .render_to_image()
                                .and_then(|image| {
                                    image
                                        .save(output.join("native-comparison-newer-head.png"))
                                        .map_err(Into::into)
                                })
                                .is_ok()
                        })
                        .unwrap_or(false);
                let tabs_captured = if let Some(second) = second_pr {
                    let _ = window.update(|_, cx| {
                        let _ = weak.update(cx, |root, cx| {
                            if let Root::Review(this) = root {
                                this.open_pr(0, second, cx);
                            }
                        });
                    });
                    for _ in 0..240 {
                        window
                            .background_executor()
                            .timer(Duration::from_millis(125))
                            .await;
                        let ready = window
                            .update(|_, cx| {
                                weak.read_with(cx, |root, _| {
                                    matches!(root, Root::Review(this) if this.tabs.len() >= 2 && this.smoke_ready())
                                })
                                .unwrap_or(false)
                            })
                            .unwrap_or(false);
                        if ready {
                            break;
                        }
                    }
                    window
                        .update(|window, _| {
                            window
                                .render_to_image()
                                .and_then(|image| {
                                    image
                                        .save(output.join("native-comparison-two-tabs.png"))
                                        .map_err(Into::into)
                                })
                                .is_ok()
                        })
                        .unwrap_or(false)
                } else {
                    true
                };
                let final_started = window
                    .update(|_, cx| {
                        weak.update(cx, |root, cx| {
                            let Root::Review(this) = root else { return None };
                            let primary = this
                                .tabs
                                .iter()
                                .position(|tab| tab.pull_request.number == 14130)?;
                            this.activate_tab_context(primary, false, cx);
                            let canonical = this.tabs[primary].canonical_full_revision.clone();
                            if let Some(session) = &mut this.tabs[primary].canonical_session {
                                session.observe_revision(canonical.clone());
                            }
                            if let Some(session) = &mut this.tabs[primary].session {
                                session.observe_revision(canonical);
                            }
                            let count = this.tabs[primary].comparison_picker.commits().len();
                            this.tabs[primary]
                                .comparison_picker
                                .begin_endpoint_selection(PickerMode::Range)
                                .ok()?;
                            this.select_picker_range_endpoint(primary, 0, cx);
                            this.select_picker_range_endpoint(primary, count.checked_sub(1)?, cx);
                            Some(())
                        })
                        .ok()
                        .flatten()
                    })
                    .ok()
                    .flatten()
                    .is_some();
                for _ in 0..160 {
                    window
                        .background_executor()
                        .timer(Duration::from_millis(125))
                        .await;
                    let ready = window
                        .update(|_, cx| {
                            weak.read_with(cx, |root, _| {
                                matches!(root, Root::Review(this) if this.tabs.iter().any(|tab| {
                                    tab.pull_request.number == 14130
                                        && matches!(tab.comparison_picker.request, ComparisonRequest::CommitRange { .. })
                                        && !matches!(tab.state, LoadState::Loading(_))
                                }))
                            })
                            .unwrap_or(false)
                        })
                        .unwrap_or(false);
                    if ready {
                        break;
                    }
                }
                let final_state = window
                    .update(|_, cx| {
                        weak.read_with(cx, |root, _| {
                            let Root::Review(this) = root else { return None };
                            let tab = this
                                .tabs
                                .iter()
                                .find(|tab| tab.pull_request.number == 14130)?;
                            Some((
                                tab.canonical_full_revision.clone(),
                                tab.session
                                    .as_ref()
                                    .map(|session| session.revision().clone()),
                            ))
                        })
                        .ok()
                        .flatten()
                    })
                    .ok()
                    .flatten();
                window
                    .background_executor()
                    .timer(Duration::from_secs(1))
                    .await;
                let passed = full_ready
                    && commit_started
                    && commit_captured
                    && range_started
                    && range_captured
                    && since_started
                    && since_captured
                    && full_returned
                    && full_return_captured
                    && poll_indicator_captured
                    && tabs_captured
                    && final_started
                    && final_state.is_some();
                let report = final_state.map_or_else(
                    || "Final persisted range state unavailable".into(),
                    |(canonical, selected)| {
                        format!(
                            "Canonical full: {} -> {}\nSelected before restart: {}\n",
                            canonical.base_sha,
                            canonical.head_sha,
                            selected
                                .map(|revision| format!("{} -> {}", revision.base_sha, revision.head_sha))
                                .unwrap_or_else(|| "unavailable".into())
                        )
                    },
                );
                let report = format!(
                    "{report}Full list: {full_ready}\nCommit: {}\nRange: {}\nSince no-baseline fallback: {}\nReturn full: {}\nNewer canonical indicator without selected-pair advance: {poll_indicator_captured}\nTwo PR tabs: {tabs_captured}\nActual native controller handlers: used\nPhysical input / AX / acrylic material identity: not established by in-process capture\nRemote writes: none\n",
                    commit_started && commit_captured,
                    range_started && range_captured,
                    since_started && since_captured,
                    full_returned && full_return_captured,
                );
                let _ = std::fs::write(output.join("native-comparison-smoke.txt"), report);
                if !passed {
                    panic!("native comparison smoke assertions failed");
                }
                let _ = window.update(|_, cx| cx.quit());
            })
            .detach();
    }

    fn save_workspace(&mut self) {
        if self.persistence_error.is_some() || self.startup_restore_pending {
            return;
        }
        let active_identity = self.active_tab.and_then(|index| {
            self.tabs
                .get(index)
                .map(|tab| (tab.repository.cache_key(), tab.pull_request.number))
        });
        let mut active_tab = None;
        let mut tabs = Vec::new();
        for tab in &self.tabs {
            if let Some(session) = &tab.session {
                if active_identity.as_ref().is_some_and(|(key, number)| {
                    *key == tab.repository.cache_key() && *number == tab.pull_request.number
                }) {
                    active_tab = Some(tabs.len());
                }
                tabs.push(TabState {
                    repository_key: tab.repository.cache_key(),
                    number: tab.pull_request.number,
                    revision: tab.canonical_full_revision.clone(),
                    pull_request: Some(tab.pull_request.clone()),
                    selected_file: session.selected_file().map(file_key),
                    scroll_offset: session.scroll_position(),
                    diff_mode: match session.diff_mode() {
                        DiffMode::Auto => "auto",
                        DiffMode::Unified => "unified",
                        DiffMode::SideBySide => "side-by-side",
                    }
                    .into(),
                });
            }
        }
        let active_identity = active_tab.and_then(|index| {
            tabs.get(index)
                .map(|tab| (tab.repository_key.clone(), tab.number))
        });
        self.workspace
            .merge_tabs(tabs, &self.closed_workspace_tabs, active_identity);
        if let Some(store) = &self.store
            && let Err(error) = store.save_workspace(&self.workspace)
        {
            self.persistence_error = Some(format!("Workspace was not saved: {error:#}"));
        }
    }

    fn save_current_request_progress(&mut self, index: usize) {
        let Some(tab) = self.tabs.get_mut(index) else {
            return;
        };
        let Some(session) = tab.session.clone() else {
            return;
        };
        let request = tab.comparison_picker.request.clone();
        if matches!(request, ComparisonRequest::FullPullRequest) {
            tab.canonical_session = Some(session);
            return;
        }
        remember_request_progress(
            &mut tab.request_sessions,
            request,
            session,
            tab.selected_local_file_load.clone(),
        );
    }

    fn persist_session(&mut self, index: usize, cx: &mut Context<Root>) {
        self.save_current_request_progress(index);
        let Some(store) = self.store.clone() else {
            return;
        };
        let Some(tab) = self.tabs.get(index) else {
            return;
        };
        if tab.session_persistence_error.is_some() {
            return;
        }
        let Some(selected_session) = tab.session.clone() else {
            return;
        };
        let Some(canonical_session) = (if matches!(
            tab.comparison_picker.request,
            ComparisonRequest::FullPullRequest
        ) {
            Some(selected_session.clone())
        } else {
            tab.canonical_session.clone()
        }) else {
            return;
        };
        let context = PersistedComparisonContext {
            canonical_full_revision: tab.canonical_full_revision.clone(),
            canonical_session,
            selected_request: tab.comparison_picker.request.clone(),
            selected_session,
            local_file_load: tab.selected_local_file_load.clone(),
            request_sessions: tab.request_sessions.clone(),
        };
        let repository = tab.repository.clone();
        let number = tab.pull_request.number;
        let key = repository.cache_key();
        let save_key = format!("{key}\n{number}");
        let latest = self
            .session_save_latest
            .entry(save_key.clone())
            .or_insert_with(|| Arc::new(AtomicU64::new(0)))
            .clone();
        let lock = self
            .session_save_locks
            .entry(save_key)
            .or_insert_with(|| Arc::new(Mutex::new(())))
            .clone();
        let sequence = latest.fetch_add(1, Ordering::AcqRel) + 1;
        let task = cx.background_spawn(async move {
            let _guard = lock
                .lock()
                .map_err(|_| anyhow::anyhow!("review session save lock failed"))?;
            if latest.load(Ordering::Acquire) != sequence {
                return Ok(());
            }
            store.save_review_context(&repository, number, &context)
        });
        cx.spawn(async move |root, cx| {
            let result = task.await;
            let _ = root.update(cx, |root, cx| {
                let Root::Review(this) = root else { return };
                if let Err(error) = result
                    && let Some(tab) = this.tabs.iter_mut().find(|tab| {
                        tab.repository.cache_key() == key && tab.pull_request.number == number
                    })
                {
                    tab.session_persistence_error = Some(format!(
                        "Review progress was not saved; existing data was preserved: {error:#}"
                    ));
                    cx.notify();
                }
            });
        })
        .detach();
    }

    fn next_review_state_write(
        &mut self,
        repository_key: &str,
        pull_request: u64,
    ) -> (Arc<AtomicU64>, Arc<Mutex<()>>, u64) {
        let save_key = format!("{repository_key}\n{pull_request}");
        let latest = self
            .review_state_latest
            .entry(save_key.clone())
            .or_insert_with(|| Arc::new(AtomicU64::new(0)))
            .clone();
        let lock = self
            .review_state_locks
            .entry(save_key)
            .or_insert_with(|| Arc::new(Mutex::new(())))
            .clone();
        let sequence = latest.fetch_add(1, Ordering::AcqRel) + 1;
        (latest, lock, sequence)
    }

    fn load_commit_inventory(&mut self, index: usize, cx: &mut Context<Root>) {
        let generation = self.issue_request_generation();
        let Some(tab) = self.tabs.get_mut(index) else {
            return;
        };
        tab.inventory_generation = generation;
        let repository = tab.repository.clone();
        let repository_key = repository.cache_key();
        let number = tab.pull_request.number;
        let canonical = tab.canonical_full_revision.clone();
        let token = RequestToken {
            repository_key: repository_key.clone(),
            pull_request: number,
            canonical_full_revision: canonical.clone(),
            generation,
        };
        tab.comparison_picker.inventory_loading = true;
        let task = cx.background_spawn(async move {
            if let Some(path) = repository.local_path.as_deref()
                && let Ok(inventory) = local_commit_inventory(path, &canonical)
            {
                return inventory;
            }
            match GithubProvider::new(repository.account.clone()).commit_inventory(
                &repository,
                number,
                &canonical,
            ) {
                Ok(inventory) => inventory,
                Err(error) => CommitInventory {
                    full_revision: canonical,
                    commits: Vec::new(),
                    availability: InventoryAvailability::Unavailable,
                    notice: Some(format!("Commit inventory unavailable: {error:#}")),
                },
            }
        });
        cx.spawn(async move |root, cx| {
            let inventory = task.await;
            let _ = root.update(cx, |root, cx| {
                let Root::Review(this) = root else { return };
                let Some(tab) = this.tabs.iter_mut().find(|tab| {
                    token.matches(
                        &tab.repository.cache_key(),
                        tab.pull_request.number,
                        &tab.canonical_full_revision,
                        tab.inventory_generation,
                    ) && tab.canonical_full_revision == inventory.full_revision
                }) else {
                    return;
                };
                tab.comparison_picker
                    .install_inventory(&tab.canonical_full_revision, inventory);
                cx.notify();
            });
        })
        .detach();
    }

    fn restore_full_comparison(&mut self, index: usize, cx: &mut Context<Root>) {
        if self.active_tab == Some(index)
            && self.persist_active_composer_before_transition(
                index,
                "Saving the exact active comment before changing comparisons; choose Full PR again after it is durable.",
                cx,
            )
        {
            return;
        }
        self.capture_scroll(index);
        self.save_current_request_progress(index);
        let generation = self.issue_request_generation();
        let Some(tab) = self.tabs.get_mut(index) else {
            return;
        };
        if matches!(
            tab.comparison_picker.request,
            ComparisonRequest::FullPullRequest
        ) && let Some(session) = tab.session.clone()
        {
            tab.canonical_session = Some(session);
        }
        let Some(canonical) = tab.canonical_session.clone() else {
            tab.state = LoadState::Error("The pinned full pull request is unavailable.".into());
            return;
        };
        tab.request_generation = generation;
        tab.session = Some(canonical);
        tab.comparison_picker
            .select_request(ComparisonRequest::FullPullRequest);
        tab.comparison_picker.expanded = false;
        tab.selected_local_file_load =
            tab.repository
                .local_path
                .as_ref()
                .map(|_| LocalFileLoadPlan {
                    revision: tab.canonical_full_revision.clone(),
                    full_pr: true,
                });
        if let Some(session) = &tab.session {
            tab.file_tree.sync(&session.comparison().files);
        }
        tab.state = LoadState::Ready;
        self.rebuild_diff(index, self.wide);
        self.persist_session(index, cx);
        if self.tabs[index]
            .session
            .as_ref()
            .and_then(ReviewSession::selected_file)
            .is_some_and(|file| file.patch.is_none())
        {
            self.load_selected_local_file(index, cx);
        }
        cx.notify();
    }

    fn select_comparison_request(
        &mut self,
        index: usize,
        request: ComparisonRequest,
        cx: &mut Context<Root>,
    ) {
        if self.active_tab == Some(index)
            && self.persist_active_composer_before_transition(
                index,
                "Saving the exact active comment before changing comparisons; choose the comparison again after it is durable.",
                cx,
            )
        {
            return;
        }
        if matches!(request, ComparisonRequest::FullPullRequest) {
            self.restore_full_comparison(index, cx);
            return;
        }
        self.capture_scroll(index);
        self.save_current_request_progress(index);
        let generation = self.issue_request_generation();
        let Some(tab) = self.tabs.get_mut(index) else {
            return;
        };
        let Some(previous) = tab.session.clone() else {
            return;
        };
        if matches!(
            tab.comparison_picker.request,
            ComparisonRequest::FullPullRequest
        ) {
            tab.canonical_session = Some(previous.clone());
        }
        let previous_key = previous.selected_file().map(file_key);
        let previous_scroll = previous.scroll_position();
        let previous_mode = previous.diff_mode();
        if let Some(saved) = saved_request_progress(&tab.request_sessions, &request) {
            let mut session = saved.session;
            session.set_diff_mode(previous_mode);
            tab.request_generation = generation;
            tab.session = Some(session);
            tab.selected_local_file_load = saved.local_file_load;
            tab.comparison_picker.select_request(request);
            tab.comparison_picker.expanded = false;
            tab.state = LoadState::Ready;
            if let Some(session) = &tab.session {
                tab.file_tree.sync(&session.comparison().files);
            }
            self.rebuild_diff(index, self.wide);
            self.persist_session(index, cx);
            if self.tabs[index]
                .session
                .as_ref()
                .and_then(ReviewSession::selected_file)
                .is_some_and(|file| file.patch.is_none())
            {
                self.load_selected_local_file(index, cx);
            }
            cx.notify();
            return;
        }
        let repository = tab.repository.clone();
        let repository_key = repository.cache_key();
        let number = tab.pull_request.number;
        let canonical = tab.canonical_full_revision.clone();
        let token = RequestToken {
            repository_key: repository_key.clone(),
            pull_request: number,
            canonical_full_revision: canonical.clone(),
            generation,
        };
        let inventory =
            tab.comparison_picker
                .inventory
                .clone()
                .unwrap_or_else(|| CommitInventory {
                    full_revision: canonical.clone(),
                    commits: Vec::new(),
                    availability: InventoryAvailability::Unavailable,
                    notice: Some("The commit inventory has not been established.".into()),
                });
        tab.request_generation = generation;
        tab.comparison_picker.expanded = false;
        tab.state = LoadState::Loading("Loading selected immutable comparison…".into());
        let task_canonical = canonical.clone();
        let task = cx.background_spawn(async move {
            if let Some(path) = repository.local_path.as_deref()
                && let Ok(selection) = select_local_comparison(
                    path,
                    &task_canonical,
                    &inventory,
                    request.clone(),
                    true,
                )
            {
                return Ok(selection);
            }
            select_github_comparison(
                &GithubProvider::new(repository.account.clone()),
                &repository,
                number,
                &task_canonical,
                &inventory,
                request,
            )
        });
        cx.spawn(async move |root, cx| {
            let result = task.await;
            let _ = root.update(cx, |root, cx| {
                let Root::Review(this) = root else { return };
                let Some(tab_index) = this.tabs.iter().position(|tab| {
                    token.matches(
                        &tab.repository.cache_key(),
                        tab.pull_request.number,
                        &tab.canonical_full_revision,
                        tab.request_generation,
                    )
                }) else {
                    return;
                };
                match result {
                    Ok(selection) if selection.full_revision == canonical => {
                        let comparison = selection.comparison;
                        let mut selected = ReviewSession::new(comparison.clone());
                        selected.select_comparison(comparison, selection.metadata);
                        selected.set_diff_mode(previous_mode);
                        if let Some(key) = previous_key.as_deref()
                            && selected.select_file(key)
                        {
                            selected.set_scroll_position(previous_scroll);
                        }
                        let tab = &mut this.tabs[tab_index];
                        tab.session = Some(selected);
                        tab.selected_local_file_load = selection.local_file_load;
                        tab.comparison_picker.select_request(selection.request);
                        tab.state = LoadState::Ready;
                        if let Some(session) = &tab.session {
                            tab.file_tree.sync(&session.comparison().files);
                        }
                        this.rebuild_diff(tab_index, this.wide);
                        this.persist_session(tab_index, cx);
                        if this.tabs[tab_index]
                            .session
                            .as_ref()
                            .and_then(ReviewSession::selected_file)
                            .is_some_and(|file| file.patch.is_none())
                        {
                            this.load_selected_local_file(tab_index, cx);
                        }
                    }
                    Ok(_) => {
                        this.tabs[tab_index].state = LoadState::Error(
                            "Comparison service returned another canonical snapshot.".into(),
                        );
                    }
                    Err(error) => {
                        this.tabs[tab_index].state =
                            LoadState::Error(format!("Comparison unavailable: {error:#}"));
                    }
                }
                cx.notify();
            });
        })
        .detach();
    }

    fn select_since_last_review(&mut self, index: usize, cx: &mut Context<Root>) {
        let Some(tab) = self.tabs.get(index) else {
            return;
        };
        let baseline = tab.details.as_ref().map_or_else(
            || {
                BaselineResolution::Unavailable(
                    cibergit::comparisons::BaselineUnavailableReason::ReviewActivityIncomplete,
                )
            },
            |details| {
                resolve_review_baseline(
                    &tab.repository,
                    tab.pull_request.number,
                    &details.reviews,
                    details.activity_complete,
                    None,
                )
            },
        );
        self.select_comparison_request(index, ComparisonRequest::SinceLastReview { baseline }, cx);
    }

    fn select_picker_commit(&mut self, index: usize, commit: usize, cx: &mut Context<Root>) {
        let request = self.tabs.get_mut(index).and_then(|tab| {
            match tab.comparison_picker.choose_commit(commit) {
                Ok(request) => Some(request),
                Err(error) => {
                    self.status = error;
                    None
                }
            }
        });
        if let Some(request) = request {
            self.select_comparison_request(index, request, cx);
        }
    }

    fn select_picker_range_endpoint(
        &mut self,
        index: usize,
        commit: usize,
        cx: &mut Context<Root>,
    ) {
        let result = self
            .tabs
            .get_mut(index)
            .map(|tab| tab.comparison_picker.choose_range_endpoint(commit));
        match result {
            Some(Ok(Some(request))) => self.select_comparison_request(index, request, cx),
            Some(Ok(None)) => cx.notify(),
            Some(Err(error)) => {
                self.status = error;
                cx.notify();
            }
            None => {}
        }
    }

    fn step_comparison_commit(&mut self, delta: isize, cx: &mut Context<Root>) {
        let Some(index) = self.active_tab else { return };
        let Some(tab) = self.tabs.get(index) else {
            return;
        };
        if !tab.comparison_picker.inventory_ready() {
            self.status = tab.comparison_picker.inventory_reason();
            cx.notify();
            return;
        }
        let commits = tab.comparison_picker.commits();
        if commits.is_empty() {
            self.status = "This pull request has no selectable commits.".into();
            cx.notify();
            return;
        }
        let current = match &tab.comparison_picker.request {
            ComparisonRequest::Commit { sha } => {
                commits.iter().position(|commit| commit.sha == *sha)
            }
            ComparisonRequest::CommitRange { last_sha, .. } => {
                commits.iter().position(|commit| commit.sha == *last_sha)
            }
            _ => None,
        }
        .unwrap_or(commits.len() - 1);
        let target = current
            .saturating_add_signed(delta)
            .min(commits.len().saturating_sub(1));
        self.select_picker_commit(index, target, cx);
    }

    fn load_selected_local_file(&mut self, index: usize, cx: &mut Context<Root>) {
        let Some(tab) = self.tabs.get_mut(index) else {
            return;
        };
        let generation = tab.request_generation;
        let Some(path) = tab.repository.local_path.clone() else {
            return;
        };
        let Some(session) = tab.session.as_ref() else {
            return;
        };
        let Some(file) = session.selected_file() else {
            return;
        };
        let selected_needs_load = file.patch.is_none();
        let Some(plan) = tab.selected_local_file_load.clone() else {
            tab.state = LoadState::Error(
                "The selected local comparison has no exact lazy-load plan.".into(),
            );
            return;
        };
        let repository_key = tab.repository.cache_key();
        let number = tab.pull_request.number;
        let canonical_revision = tab.canonical_full_revision.clone();
        let token = RequestToken {
            repository_key: repository_key.clone(),
            pull_request: number,
            canonical_full_revision: canonical_revision.clone(),
            generation,
        };
        let selected_key = file_key(file);
        let hydrate_canonical = tab
            .canonical_session
            .as_ref()
            .and_then(|canonical| {
                canonical
                    .comparison()
                    .files
                    .iter()
                    .find(|file| file_key(file) == selected_key)
            })
            .is_some_and(|file| file.patch.is_none());
        if !selected_needs_load && !hydrate_canonical {
            self.persist_session(index, cx);
            return;
        }
        tab.state = LoadState::Loading("Loading selected local file…".into());
        let request_key = selected_key.clone();
        let task_canonical_revision = canonical_revision.clone();
        let task = cx.background_spawn(async move {
            let selected = if selected_needs_load {
                Some(load_local_file(
                    &path,
                    &plan.revision,
                    &request_key,
                    plan.full_pr,
                )?)
            } else {
                None
            };
            let canonical = if hydrate_canonical {
                if plan.full_pr && plan.revision == task_canonical_revision {
                    match selected.clone() {
                        Some(file) => Some(file),
                        None => Some(load_local_file(
                            &path,
                            &task_canonical_revision,
                            &request_key,
                            true,
                        )?),
                    }
                } else {
                    Some(load_local_file(
                        &path,
                        &task_canonical_revision,
                        &request_key,
                        true,
                    )?)
                }
            } else {
                None
            };
            Ok::<_, anyhow::Error>((selected, canonical, plan))
        });
        cx.spawn(async move |root, cx| {
            let result = task.await;
            let _ = root.update(cx, |root, cx| {
                let Root::Review(this) = root else { return };
                let Some(tab_index) = this.tabs.iter().position(|tab| {
                    token.matches(
                        &tab.repository.cache_key(),
                        tab.pull_request.number,
                        &tab.canonical_full_revision,
                        tab.request_generation,
                    ) && tab.local_inventory
                        && tab
                            .session
                            .as_ref()
                            .and_then(ReviewSession::selected_file)
                            .is_some_and(|file| file_key(file) == selected_key)
                }) else {
                    return;
                };
                match result {
                    Ok((file, canonical_file, plan)) => {
                        let installed = file.is_none_or(|file| {
                            this.tabs[tab_index]
                                .session
                                .as_mut()
                                .is_some_and(|session| {
                                    session.install_file_patch(&plan.revision, file).is_ok()
                                })
                        });
                        let canonical_installed = canonical_file.is_none_or(|file| {
                            this.tabs[tab_index]
                                .canonical_session
                                .as_mut()
                                .is_some_and(|session| {
                                    session
                                        .install_file_patch(&canonical_revision, file)
                                        .is_ok()
                                })
                        });
                        if installed && canonical_installed {
                            this.tabs[tab_index].state = LoadState::Ready;
                            this.rebuild_diff(tab_index, this.wide);
                            this.persist_session(tab_index, cx);
                        }
                    }
                    Err(error) => {
                        this.tabs[tab_index].state =
                            LoadState::Error(format!("Selected local file unavailable: {error:#}"));
                    }
                }
                cx.notify();
            });
        })
        .detach();
    }

    fn refresh_all(&mut self, cx: &mut Context<Root>) {
        for index in 0..self.repositories.len() {
            self.refresh_repository(index, cx);
        }
    }

    fn resume_general_read_followups(&mut self, cx: &mut Context<Root>) {
        let mut followups = self
            .tabs
            .iter()
            .enumerate()
            .filter(|(_, tab)| {
                general_read_tab_can_start(tab.submitted_summary_editor.close_after_save)
            })
            .flat_map(|(index, tab)| {
                [
                    tab.metadata_refresh
                        .has_deferred()
                        .then_some(GeneralReadFollowup::Tab { index, kind: 0 }),
                    tab.details_refresh
                        .has_deferred()
                        .then_some(GeneralReadFollowup::Tab { index, kind: 1 }),
                    tab.lifecycle_refresh
                        .has_deferred()
                        .then_some(GeneralReadFollowup::Tab { index, kind: 2 }),
                ]
                .into_iter()
                .flatten()
            })
            .collect::<Vec<_>>();
        followups.extend(
            self.repositories
                .iter()
                .enumerate()
                .filter_map(|(index, runtime)| {
                    runtime
                        .refresh
                        .has_deferred()
                        .then_some(GeneralReadFollowup::Repository { index })
                }),
        );
        rotate_general_read_followups(&mut followups, &mut self.general_read_followup_cursor);
        for followup in followups {
            match followup {
                GeneralReadFollowup::Tab { index, kind: 0 } => {
                    self.refresh_metadata(index, false, cx)
                }
                GeneralReadFollowup::Tab { index, kind: 1 } => {
                    self.refresh_details_with_intent(index, false, cx)
                }
                GeneralReadFollowup::Tab { index, .. } => {
                    self.refresh_lifecycle_with_intent(index, false, cx)
                }
                GeneralReadFollowup::Repository { index } => {
                    self.refresh_repository_with_intent(index, false, cx)
                }
            }
        }
    }

    fn refresh_repository(&mut self, index: usize, cx: &mut Context<Root>) {
        self.refresh_repository_with_intent(index, true, cx);
    }

    fn refresh_repository_with_intent(
        &mut self,
        index: usize,
        explicit: bool,
        cx: &mut Context<Root>,
    ) {
        let Some((repository, effective_explicit)) =
            self.repositories.get_mut(index).and_then(|runtime| {
                runtime
                    .refresh
                    .begin_admission(explicit)
                    .map(|effective| (runtime.repository.clone(), effective))
            })
        else {
            return;
        };
        let admission = match self.general_reads.begin(&repository.account) {
            Ok(admission) => admission,
            Err(read_sync::ReadDeferral::Busy) => {
                self.repositories[index]
                    .refresh
                    .defer_admission(effective_explicit);
                return;
            }
            Err(read_sync::ReadDeferral::Server(notice)) => {
                self.repositories[index]
                    .refresh
                    .defer_admission(effective_explicit);
                self.status = notice.into();
                cx.notify();
                return;
            }
        };
        // A removed and re-added repository must not reuse the old read ID.
        let generation = self.issue_request_generation();
        let runtime = &mut self.repositories[index];
        runtime.generation = generation;
        let repo_key = repository.cache_key();
        if runtime.pull_requests.is_empty() {
            runtime.state = LoadState::Loading("Loading pull requests…".into());
        }
        let provider = GithubProvider::new(repository.account.clone());
        let read_workspace_instance = self.workspace_instance;
        let requested_state = {
            let state = self.workspace.view().filter.state;
            if state.is_empty() {
                "open".to_owned()
            } else {
                state
            }
        };
        let (read_token, cache) = admission.into_parts();
        let task = cx.background_spawn(async move {
            let outcome =
                provider.list_pull_requests_conditional(&repository, &requested_state, cache);
            (read_token, outcome)
        });
        cx.spawn(async move |root, cx| {
            let (read_token, outcome) = task.await;
            let _ = root.update(cx, |root, cx| {
                let Root::Review(this) = root else { return };
                let (result, cache, directive, failure) = outcome.into_parts();
                if !general_read_callback_is_current(
                    read_workspace_instance,
                    this.workspace_instance,
                ) {
                    this.general_reads
                        .complete(&read_token, &directive, cache, false);
                    return;
                }
                let matching_index = this.repositories.iter().position(|runtime| {
                    runtime.repository.cache_key() == repo_key && runtime.generation == generation
                });
                let superseded = matching_index
                    .is_some_and(|index| this.repositories[index].refresh.superseded_by_explicit());
                let accept_payload = matching_index.is_some() && !superseded && result.is_ok();
                let disposition =
                    this.general_reads
                        .complete(&read_token, &directive, cache, accept_payload);
                if !disposition.matching_operation_released {
                    return;
                }
                let follow_up = matching_index
                    .map(|index| this.repositories[index].refresh.complete())
                    .unwrap_or(false);
                if let Some(index) = matching_index
                    && follow_up
                {
                    this.refresh_repository(index, cx);
                    this.resume_general_read_followups(cx);
                    return;
                }
                if let Some(index) = matching_index {
                    let runtime = &mut this.repositories[index];
                    match result {
                        Ok(pull_requests) if disposition.payload_accepted => {
                            if let Some(store) = &this.store {
                                let _ =
                                    store.save_pull_requests(&runtime.repository, &pull_requests);
                            }
                            runtime.pull_requests = pull_requests;
                            runtime.state = LoadState::Ready;
                            this.schedule.succeeded(&format!("sidebar:{repo_key}"));
                        }
                        Ok(_) => {}
                        Err(_) => {
                            this.schedule.failed(&format!("sidebar:{repo_key}"));
                            let notice = general_read_failure_notice(failure);
                            runtime.state = if runtime.pull_requests.is_empty() {
                                LoadState::Error(notice.into())
                            } else {
                                LoadState::Cached(notice.into())
                            };
                        }
                    }
                }
                this.resume_general_read_followups(cx);
                cx.notify();
            });
        })
        .detach();
    }

    fn open_pr(&mut self, repo_index: usize, number: u64, cx: &mut Context<Root>) {
        self.open_pr_with_intent(repo_index, number, OpenPrIntent::User, None, cx);
    }

    fn open_pr_in_window(
        &mut self,
        repo_index: usize,
        number: u64,
        window: &mut Window,
        cx: &mut Context<Root>,
    ) {
        self.open_pr_with_intent(repo_index, number, OpenPrIntent::User, Some(window), cx);
    }

    fn open_pr_with_intent(
        &mut self,
        repo_index: usize,
        number: u64,
        intent: OpenPrIntent,
        mut window: Option<&mut Window>,
        cx: &mut Context<Root>,
    ) {
        let Some(repository) = self
            .repositories
            .get(repo_index)
            .map(|runtime| runtime.repository.clone())
        else {
            return;
        };
        let user_intent_generation = match intent {
            OpenPrIntent::User => {
                self.record_user_navigation();
                self.user_intent_generation
            }
            OpenPrIntent::ExplicitStartup => {
                let Some(generation) = self.explicit_startup_generation else {
                    return;
                };
                if generation != self.user_intent_generation {
                    return;
                }
                generation
            }
        };
        let identity = (repository.cache_key(), number);
        self.closed_workspace_tabs.remove(&identity);
        if intent == OpenPrIntent::ExplicitStartup {
            self.explicit_startup_selection = Some(identity.clone());
        }
        if let Some(index) = self.tabs.iter().position(|tab| {
            tab.repository.cache_key() == identity.0 && tab.pull_request.number == identity.1
        }) {
            if let Some(window) = window.as_deref_mut() {
                self.activate_tab_in_window(index, false, window, cx);
            } else {
                self.activate_tab_context(index, false, cx);
            }
            return;
        }
        if let Some(pull_request) = self.repositories[repo_index]
            .pull_requests
            .iter()
            .find(|pull_request| pull_request.number == number)
            .cloned()
        {
            if let Some(window) = window {
                self.install_tab_in_window(repository, pull_request, window, cx);
            } else {
                self.install_tab(repository, pull_request, cx);
            }
            return;
        }
        self.status = format!("Loading #{} from {}…", number, repository.full_name());
        let key = repository.cache_key();
        let expected_repository = repository.clone();
        let request_repo = repository.clone();
        let token = OpenPrToken {
            workspace_instance: self.workspace_instance,
            user_intent_generation,
            identity: identity.clone(),
            intent,
        };
        let task = cx.background_spawn(async move {
            GithubProvider::new(request_repo.account.clone()).pull_request(&request_repo, number)
        });
        cx.spawn(async move |root, cx| {
            let result = task.await;
            let _ = root.update(cx, |root, cx| {
                let Root::Review(this) = root else { return };
                let current = this
                    .tabs
                    .iter()
                    .map(|tab| (tab.repository.cache_key(), tab.pull_request.number))
                    .collect::<Vec<_>>();
                let completion = admit_open_pr_completion(
                    &token,
                    this.workspace_instance,
                    this.user_intent_generation,
                    &current,
                );
                if completion == OpenPrCompletion::Refused {
                    return;
                }
                match result {
                    Ok(pull_request) => {
                        match completion {
                            OpenPrCompletion::Refused => unreachable!("checked above"),
                            OpenPrCompletion::Existing(index) => {
                                // Provider metadata can be newer than the pinned session. It is
                                // presentation only and must not replace restored review state.
                                this.tabs[index].pull_request = pull_request;
                                if token.intent == OpenPrIntent::ExplicitStartup {
                                    this.activate_tab_context(index, false, cx);
                                }
                                this.save_workspace();
                                cx.notify();
                                return;
                            }
                            OpenPrCompletion::Install => {}
                        }
                        if let Some(runtime) = this.repositories.iter_mut().find(|runtime| {
                            runtime.repository.cache_key() == key
                                && runtime.repository == expected_repository
                        }) && !runtime
                            .pull_requests
                            .iter()
                            .any(|listed| listed.number == pull_request.number)
                        {
                            runtime.pull_requests.push(pull_request.clone());
                        }
                        let Some(repository) = this
                            .repositories
                            .iter()
                            .find(|runtime| {
                                runtime.repository.cache_key() == key
                                    && runtime.repository == expected_repository
                            })
                            .map(|runtime| runtime.repository.clone())
                        else {
                            return;
                        };
                        this.install_tab(repository, pull_request, cx);
                    }
                    Err(error) => {
                        this.status = format!("Cannot load PR #{number}: {error:#}");
                    }
                }
                cx.notify();
            });
        })
        .detach();
    }

    fn activate_tab(&mut self, index: usize, window: &mut Window, cx: &mut Context<Root>) {
        self.activate_tab_in_window(index, true, window, cx);
    }

    fn activate_tab_in_window(
        &mut self,
        index: usize,
        record_navigation: bool,
        window: &mut Window,
        cx: &mut Context<Root>,
    ) {
        if self.begin_active_tab_transition(index, record_navigation, cx) {
            self.active_tab_input_restore = None;
            self.restore_active_tab_shared_inputs(index, window, cx);
        }
    }

    fn activate_tab_context(
        &mut self,
        index: usize,
        record_navigation: bool,
        cx: &mut Context<Root>,
    ) {
        if self.begin_active_tab_transition(index, record_navigation, cx) {
            let tab = &self.tabs[index];
            let token = ActiveTabInputRestoreToken {
                workspace_instance: self.workspace_instance,
                tab_instance: tab.instance_generation,
                repository_key: tab.repository.cache_key(),
                pull_request: tab.pull_request.number,
            };
            self.active_tab_input_restore = Some(token.clone());
            self.composer_input
                .update(cx, |input, cx| input.set_disabled(true, cx));
            self.submitted_summary_input
                .update(cx, |input, cx| input.set_disabled(true, cx));
            self.defer_active_tab_input_restore(token, 0, cx);
        }
    }

    fn begin_active_tab_transition(
        &mut self,
        index: usize,
        record_navigation: bool,
        cx: &mut Context<Root>,
    ) -> bool {
        if index < self.tabs.len() {
            if self
                .active_tab
                .is_some_and(|active| self.tabs[active].submitted_summary_editor.close_after_save)
            {
                self.status = "Wait for the submitted-review draft close barrier to finish.".into();
                cx.notify();
                return false;
            }
            if record_navigation {
                self.record_user_navigation();
            }
            let prior_input_is_current = self.active_tab_input_restore.is_none();
            if prior_input_is_current {
                self.stage_active_metadata_inputs(cx);
                if let Some(previous) = self.active_tab {
                    let body = self.discussion_input.read(cx).value().to_string();
                    self.tabs[previous].lifecycle.stage_discussion_body(body);
                    let submitted_body = self.submitted_summary_input.read(cx).value().to_string();
                    self.tabs[previous]
                        .submitted_summary_editor
                        .store_active_body(submitted_body);
                }
                if let Some(previous) = self.active_tab {
                    self.capture_scroll(previous);
                    let current = self.composer_input.read(cx).value().to_string();
                    let unsaved = match &self.tabs[previous].interactions {
                        InteractionState::Ready(controller) => {
                            active_review_composer_needs_save(controller, &current)
                        }
                        _ => false,
                    };
                    if unsaved {
                        self.persist_composer(cx);
                    }
                }
            }
            self.active_tab = Some(index);
            if let Some(key) = self.tabs[index]
                .session
                .as_ref()
                .and_then(ReviewSession::selected_file)
                .map(file_key)
                && let Some(row) = self.tabs[index].file_tree.reveal_file(&key)
            {
                self.tabs[index]
                    .file_tree_scroll
                    .scroll_to_item(row, gpui::ScrollStrategy::Nearest);
            }
            self.setup_open = false;
            cx.notify();
            true
        } else {
            false
        }
    }

    fn defer_active_tab_input_restore(
        &mut self,
        token: ActiveTabInputRestoreToken,
        attempt: u8,
        cx: &mut Context<Root>,
    ) {
        let weak = cx.weak_entity();
        cx.defer(move |cx| {
            let _ = weak.update(cx, |root, cx| {
                let Root::Review(this) = root else { return };
                if this.active_tab_input_restore.as_ref() != Some(&token)
                    || this.workspace_instance != token.workspace_instance
                {
                    return;
                }
                let Some(index) = this.active_tab else { return };
                let Some(tab) = this.tabs.get(index) else { return };
                if tab.instance_generation != token.tab_instance
                    || tab.repository.cache_key() != token.repository_key
                    || tab.pull_request.number != token.pull_request
                {
                    return;
                }
                let root_entity = cx.entity_id();
                let restored = cx
                    .with_window(root_entity, |window, cx| {
                        this.restore_active_tab_shared_inputs(index, window, cx);
                    })
                    .is_some();
                if restored {
                    this.active_tab_input_restore = None;
                } else if attempt == 0 {
                    this.defer_active_tab_input_restore(token, 1, cx);
                } else {
                    this.status = "Submitted-review input restoration is still unavailable; text remains safely disabled until another admitted tab transition.".into();
                    cx.notify();
                }
            });
        });
    }

    fn restore_active_tab_shared_inputs(
        &mut self,
        index: usize,
        window: &mut Window,
        cx: &mut App,
    ) {
        let Some(tab) = self.tabs.get(index) else {
            return;
        };
        let composer_body = match &tab.interactions {
            InteractionState::Ready(controller) => active_review_composer_body(controller)
                .unwrap_or_default()
                .to_owned(),
            _ => String::new(),
        };
        let submitted_body = tab
            .submitted_summary_editor
            .active_draft()
            .map(|draft| draft.body.clone())
            .unwrap_or_default();
        let mutation_disabled =
            tab.write_in_flight || tab.submitted_summary_editor.close_after_save;
        let submitted_disabled = mutation_disabled
            || tab.submitted_summary_editor.clear_in_flight
            || tab.submitted_summary_editor.pending_clear.is_some()
            || tab.submitted_summary_editor.close_after_save;
        let metadata_form = tab
            .lifecycle
            .metadata_form
            .clone()
            .filter(|_| tab.lifecycle.editing_metadata);
        let discussion_form = tab.lifecycle.discussion_form.clone();
        self.composer_input.update(cx, |input, cx| {
            input.set_value(composer_body, window, cx);
            input.set_disabled(mutation_disabled, cx);
        });
        self.review_summary_input
            .update(cx, |input, cx| input.set_disabled(mutation_disabled, cx));
        apply_submitted_input_restore(
            &self.submitted_summary_input,
            SubmittedInputRestore {
                body: submitted_body,
                disabled: submitted_disabled,
            },
            window,
            cx,
        );
        if let Some(form) = metadata_form {
            self.metadata_title_input
                .update(cx, |input, cx| input.set_value(form.title, window, cx));
            self.metadata_body_input
                .update(cx, |input, cx| input.set_value(form.body, window, cx));
            self.metadata_base_input.update(cx, |input, cx| {
                input.set_value(form.base_branch, window, cx)
            });
        }
        if let Some(form) = discussion_form {
            self.discussion_input
                .update(cx, |input, cx| input.set_value(form.body, window, cx));
        }
    }

    fn restore_pending_active_tab_input_in_window(
        &mut self,
        window: &mut Window,
        cx: &mut Context<Root>,
    ) -> bool {
        let Some(token) = self.active_tab_input_restore.clone() else {
            return true;
        };
        let Some(index) = self.active_tab else {
            return false;
        };
        let Some(tab) = self.tabs.get(index) else {
            return false;
        };
        if token.workspace_instance != self.workspace_instance
            || token.tab_instance != tab.instance_generation
            || token.repository_key != tab.repository.cache_key()
            || token.pull_request != tab.pull_request.number
        {
            return false;
        }
        self.restore_active_tab_shared_inputs(index, window, cx);
        self.active_tab_input_restore = None;
        true
    }

    fn install_tab(
        &mut self,
        repository: Repository,
        pull_request: PullRequest,
        cx: &mut Context<Root>,
    ) {
        let restored = self
            .store
            .as_ref()
            .map(|store| store.load_review_context(&repository, pull_request.number));
        self.install_tab_with_restore(
            repository,
            pull_request,
            restored,
            InstallTabOptions {
                activate: true,
                window: None,
                start_background_work: true,
            },
            cx,
        );
    }

    fn install_tab_in_window(
        &mut self,
        repository: Repository,
        pull_request: PullRequest,
        window: &mut Window,
        cx: &mut Context<Root>,
    ) {
        let restored = self
            .store
            .as_ref()
            .map(|store| store.load_review_context(&repository, pull_request.number));
        self.install_tab_with_restore(
            repository,
            pull_request,
            restored,
            InstallTabOptions {
                activate: true,
                window: Some(window),
                start_background_work: true,
            },
            cx,
        );
    }

    fn install_tab_with_restore(
        &mut self,
        repository: Repository,
        pull_request: PullRequest,
        restored: Option<anyhow::Result<PersistedComparisonContext>>,
        options: InstallTabOptions<'_>,
        cx: &mut Context<Root>,
    ) {
        let InstallTabOptions {
            activate,
            window,
            start_background_work,
        } = options;
        let revision = pull_request.revision();
        let (
            session,
            canonical_session,
            canonical_full_revision,
            selected_request,
            selected_local_file_load,
            request_sessions,
            state,
            session_persistence_error,
        ) = match restored {
            Some(Ok(context)) => (
                Some(context.selected_session),
                Some(context.canonical_session),
                context.canonical_full_revision,
                context.selected_request,
                context.local_file_load,
                context.request_sessions,
                LoadState::Cached("Restored pinned review session · refreshing metadata".into()),
                None,
            ),
            Some(Err(error))
                if error
                    .downcast_ref::<std::io::Error>()
                    .is_some_and(|error| error.kind() == std::io::ErrorKind::NotFound) =>
            {
                (
                    None,
                    None,
                    revision.clone(),
                    ComparisonRequest::FullPullRequest,
                    None,
                    Vec::new(),
                    LoadState::Loading("Loading immutable comparison…".into()),
                    None,
                )
            }
            Some(Err(error)) => (
                None,
                None,
                revision.clone(),
                ComparisonRequest::FullPullRequest,
                None,
                Vec::new(),
                LoadState::Loading("Loading immutable comparison…".into()),
                Some(format!(
                    "Saved review session is unreadable and will not be overwritten: {error:#}"
                )),
            ),
            None => (
                None,
                None,
                revision.clone(),
                ComparisonRequest::FullPullRequest,
                None,
                Vec::new(),
                LoadState::Loading("Loading immutable comparison…".into()),
                None,
            ),
        };
        let local_inventory = repository.local_path.is_some()
            && (selected_local_file_load.is_some()
                || session.as_ref().is_some_and(|session| {
                    session
                        .comparison()
                        .files
                        .iter()
                        .any(|file| file.patch.is_none())
                })
                || canonical_session.as_ref().is_some_and(|session| {
                    session
                        .comparison()
                        .files
                        .iter()
                        .any(|file| file.patch.is_none())
                }));
        let file_tree = session
            .as_ref()
            .map(|session| FileTree::new(&session.comparison().files))
            .unwrap_or_default();
        let request_generation = self.issue_request_generation();
        let lifecycle = PrLifecycleController::new(repository.clone(), pull_request.number);
        self.tabs.push(ReviewTab {
            instance_generation: request_generation,
            stack: StackViewController::new(
                self.stack_data_root.clone(),
                &repository,
                pull_request.number,
            ),
            repository,
            pull_request,
            session,
            canonical_session,
            canonical_full_revision,
            comparison_picker: ComparisonPicker::new(selected_request),
            selected_local_file_load,
            request_sessions,
            state,
            request_generation,
            inventory_generation: request_generation,
            metadata_generation: 0,
            metadata_refresh: RefreshGate::default(),
            diff_rows: Vec::new(),
            diff_scroll: ListState::new(0, ListAlignment::Top, px(480.)),
            diff_horizontal: ScrollHandle::new(),
            diff_content_width: 0.,
            file_tree,
            file_tree_scroll: UniformListScrollHandle::new(),
            inspector_section: InspectorSection::Overview,
            local_inventory,
            session_persistence_error,
            details: None,
            cached_collaboration: None,
            collaboration_cache_notice: None,
            collaboration_cache_generation: 0,
            #[cfg(feature = "ui-smoke")]
            collaboration_cache_completed_generation: 0,
            pending_snapshot: None,
            journal_operations: Vec::new(),
            journal_error: None,
            details_state: LoadState::Loading("Loading PR details…".into()),
            details_generation: 0,
            details_refresh: RefreshGate::default(),
            lifecycle,
            lifecycle_state: LoadState::Loading("Loading lifecycle metadata…".into()),
            lifecycle_generation: 0,
            lifecycle_refresh: RefreshGate::default(),
            interactions: InteractionState::Loading,
            interaction_generation: 0,
            confirmation: None,
            write_in_flight: false,
            reply_thread: None,
            editing_pending_summary: false,
            submitted_summary_editor: SubmittedSummaryEditor::default(),
            submitted_confirmation_generation: 0,
            file_confirmation_generation: 0,
            recovery_details_expanded: false,
            lifecycle_details_expanded: false,
            lifecycle_choice_pages: [0; 3],
            lifecycle_confirmation_details: false,
            issue_comment_page: 0,
            review_page: 0,
            local_workspace: None,
            local_visible: false,
        });
        let index = self.tabs.len() - 1;
        if activate {
            if let Some(window) = window {
                self.activate_tab_in_window(index, false, window, cx);
            } else {
                self.activate_tab_context(index, false, cx);
            }
        }
        self.setup_open = false;
        if !start_background_work {
            return;
        }
        self.start_submitted_draft_load(index, cx);
        self.load_cached_collaboration(index, cx);
        #[cfg(feature = "ui-smoke")]
        if std::env::var_os("CIBERGIT_SMOKE_STACK").is_some() {
            return;
        }
        if self.tabs[index].session.is_some() {
            self.rebuild_diff(index, self.wide);
            self.load_interactions(index, cx);
            if self.tabs[index].local_inventory {
                self.load_selected_local_file(index, cx);
            }
            self.refresh_metadata(index, true, cx);
            self.refresh_details_with_intent(index, true, cx);
            self.load_commit_inventory(index, cx);
        } else {
            self.load_comparison(index, revision, false, cx);
            self.refresh_details(index, cx);
        }
        self.refresh_lifecycle(index, cx);
    }

    fn load_interactions(&mut self, index: usize, cx: &mut Context<Root>) {
        let Some(tab) = self.tabs.get_mut(index) else {
            return;
        };
        let Some(session) = tab.canonical_session.clone() else {
            return;
        };
        if !matches!(tab.interactions, InteractionState::Loading) {
            return;
        }
        tab.interaction_generation += 1;
        let read_epoch = TabReadEpoch {
            instance: tab.instance_generation,
            generation: tab.interaction_generation,
        };
        let repository = tab.repository.clone();
        let number = tab.pull_request.number;
        let identity = repository.cache_key();
        let root = self.interaction_root.clone();
        let task = cx.background_spawn(async move {
            ReviewInteractionController::load(&root, &repository, number, &session)
        });
        cx.spawn(async move |entity, cx| {
            let result = task.await;
            let _ = entity.update(cx, |root, cx| {
                let Root::Review(this) = root else { return };
                let Some(index) = this.tabs.iter().position(|tab| {
                    tab.repository.cache_key() == identity
                        && tab.pull_request.number == number
                        && read_epoch.matches(tab.instance_generation, tab.interaction_generation)
                }) else {
                    return;
                };
                this.tabs[index].interactions = match result {
                    Ok(ControllerLoad::Ready(mut controller)) => {
                        if let Some(details) = &this.tabs[index].details
                            && let Err(error) = controller.reconcile_details(details)
                        {
                            controller.notice = Some(format!(
                                "Pending-review refresh could not be reconciled: {error}"
                            ));
                        }
                        controller
                            .install_pending_snapshot(this.tabs[index].pending_snapshot.clone());
                        InteractionState::Ready(controller)
                    }
                    Ok(ControllerLoad::RecoveryRequired(reason)) | Err(reason) => {
                        InteractionState::RecoveryRequired(reason)
                    }
                };
                this.rebuild_diff(index, this.wide);
                cx.notify();
            });
        })
        .detach();
    }

    fn shared_composer_admitted(&self, index: usize) -> bool {
        self.active_tab == Some(index)
            && self.active_tab_input_restore.is_none()
            && self.tabs.get(index).is_some_and(|tab| {
                !tab.write_in_flight && !tab.submitted_summary_editor.close_after_save
            })
    }

    fn update_shared_composer_disabled(&self, cx: &mut Context<Root>) {
        let disabled = self
            .active_tab
            .is_none_or(|index| !self.shared_composer_admitted(index));
        self.composer_input
            .update(cx, |input, cx| input.set_disabled(disabled, cx));
    }

    fn persist_active_composer_before_transition(
        &mut self,
        index: usize,
        message: &str,
        cx: &mut Context<Root>,
    ) -> bool {
        if !self.shared_composer_admitted(index) {
            self.status =
                "Wait for the active editor restoration or local close operation to finish.".into();
            cx.notify();
            return true;
        }
        let visible = self.composer_input.read(cx).value().to_string();
        let needs_save = matches!(
            &self.tabs[index].interactions,
            InteractionState::Ready(controller)
                if active_review_composer_needs_save(controller, &visible)
        );
        if !needs_save {
            return false;
        }
        self.persist_composer(cx);
        self.status = message.into();
        cx.notify();
        true
    }

    fn open_inline_composer(
        &mut self,
        side: DiffSide,
        line: u64,
        extend: bool,
        window: &mut Window,
        cx: &mut Context<Root>,
    ) {
        let Some(index) = self.active_tab else { return };
        if !self.restore_pending_active_tab_input_in_window(window, cx)
            || !self.shared_composer_admitted(index)
        {
            return;
        }
        if self.tabs[index].write_in_flight {
            self.status =
                "This review state is frozen until the started write is reconciled.".into();
            return;
        }
        if self.persist_active_composer_before_transition(
            index,
            "Saving the current exact comment target; choose the line again after it is durable.",
            cx,
        ) {
            return;
        }
        let Some(session) = self.tabs[index].session.clone() else {
            self.status = "The immutable comparison is still loading.".into();
            return;
        };
        let Some(canonical) = self.tabs[index].canonical_session.clone() else {
            self.status = "The canonical full pull request is still loading.".into();
            return;
        };
        let selection = match &self.tabs[index].interactions {
            InteractionState::Ready(controller) if extend => controller
                .composer
                .as_ref()
                .filter(|composer| composer.coordinate.side == side)
                .map(|composer| LineSelection {
                    side,
                    start_line: composer.coordinate.start_line.min(line),
                    line: composer.coordinate.line.max(line),
                })
                .unwrap_or_else(|| LineSelection::single(side, line)),
            _ => LineSelection::single(side, line),
        };
        let result = match &mut self.tabs[index].interactions {
            InteractionState::Ready(controller) => {
                controller.select_line_with_canonical(&session, &canonical, selection)
            }
            InteractionState::Loading => Err("Review recovery is still loading.".into()),
            InteractionState::RecoveryRequired(reason) => Err(reason.clone()),
        };
        match result {
            Ok(()) => {
                let body = match &self.tabs[index].interactions {
                    InteractionState::Ready(controller) => controller
                        .composer
                        .as_ref()
                        .map(|composer| composer.body.clone())
                        .unwrap_or_default(),
                    _ => String::new(),
                };
                self.composer_input.update(cx, |input, cx| {
                    input.set_value(body, window, cx);
                    input.focus(window, cx);
                });
                self.rebuild_diff(index, self.wide);
                self.status = if selection.start_line == selection.line {
                    format!("Composer bound to {} line {}", side.provider_name(), line)
                } else {
                    format!(
                        "Composer bound to {} lines {}–{}",
                        side.provider_name(),
                        selection.start_line,
                        selection.line
                    )
                };
            }
            Err(error) => self.status = error,
        }
        cx.notify();
    }

    fn compose_first_selectable(&mut self, window: &mut Window, cx: &mut Context<Root>) {
        let Some(index) = self.active_tab else { return };
        let selection = self.tabs[index].diff_rows.iter().find_map(|row| match row {
            DiffRow::Unified(line) => line
                .new_line
                .map(|line| (DiffSide::New, line))
                .or_else(|| line.old_line.map(|line| (DiffSide::Old, line))),
            DiffRow::Split(row) => row
                .new
                .as_ref()
                .and_then(|line| line.new_line)
                .map(|line| (DiffSide::New, line))
                .or_else(|| {
                    row.old
                        .as_ref()
                        .and_then(|line| line.old_line)
                        .map(|line| (DiffSide::Old, line))
                }),
            DiffRow::Hunk(_) | DiffRow::Thread(_) | DiffRow::Composer { .. } => None,
        });
        if let Some((side, line)) = selection {
            self.open_inline_composer(side, line, false, window, cx);
        } else {
            self.status = "The selected file has no provider-safe selectable text line.".into();
            cx.notify();
        }
    }

    fn open_file_composer(&mut self, window: &mut Window, cx: &mut Context<Root>) {
        let Some(index) = self.active_tab else { return };
        if !self.restore_pending_active_tab_input_in_window(window, cx)
            || !self.shared_composer_admitted(index)
        {
            return;
        }
        if self.tabs[index].write_in_flight {
            self.status =
                "This review state is frozen until the started write is reconciled.".into();
            return;
        }
        if self.persist_active_composer_before_transition(
            index,
            "Saving the current exact comment target; choose Comment on file again after it is durable.",
            cx,
        ) {
            return;
        }
        let (Some(displayed), Some(canonical)) = (
            self.tabs[index].session.clone(),
            self.tabs[index].canonical_session.clone(),
        ) else {
            self.status = "The canonical full pull request is still loading.".into();
            return;
        };
        let result = match &mut self.tabs[index].interactions {
            InteractionState::Ready(controller) => {
                controller.select_file_with_canonical(&displayed, &canonical)
            }
            InteractionState::Loading => Err("Review recovery is still loading.".into()),
            InteractionState::RecoveryRequired(reason) => Err(reason.clone()),
        };
        match result {
            Ok(()) => {
                let body = match &self.tabs[index].interactions {
                    InteractionState::Ready(controller) => controller
                        .file_composer
                        .as_ref()
                        .map(|composer| composer.body.clone())
                        .unwrap_or_default(),
                    _ => String::new(),
                };
                self.composer_input.update(cx, |input, cx| {
                    input.set_value(body, window, cx);
                    input.focus(window, cx);
                });
                self.rebuild_diff(index, self.wide);
                self.status = "File-level draft bound to the exact canonical file.".into();
            }
            Err(error) => self.status = error,
        }
        cx.notify();
    }

    fn reopen_pending_draft(
        &mut self,
        draft_id: &str,
        window: &mut Window,
        cx: &mut Context<Root>,
    ) {
        let Some(index) = self.active_tab else { return };
        if !self.restore_pending_active_tab_input_in_window(window, cx)
            || !self.shared_composer_admitted(index)
        {
            return;
        }
        if self.tabs[index].write_in_flight {
            self.status = "Wait for the started review action before editing this comment.".into();
            return;
        }
        if self.persist_active_composer_before_transition(
            index,
            "Saving the active comment before opening another draft; open the linked draft again after it is durable.",
            cx,
        ) {
            return;
        }
        let routed_to_full = !matches!(
            self.tabs[index].comparison_picker.request,
            ComparisonRequest::FullPullRequest
        );
        if routed_to_full {
            self.restore_full_comparison(index, cx);
        }
        let result = match &mut self.tabs[index].interactions {
            InteractionState::Ready(controller) => controller.reopen_draft(draft_id),
            InteractionState::Loading => Err("Review recovery is still loading.".into()),
            InteractionState::RecoveryRequired(reason) => Err(reason.clone()),
        };
        match result {
            Ok(composer) => {
                if self.tabs[index]
                    .session
                    .as_mut()
                    .is_some_and(|session| session.select_file(&composer.coordinate.file_key))
                    && let Some(row) = self.tabs[index]
                        .file_tree
                        .reveal_file(&composer.coordinate.file_key)
                {
                    self.tabs[index]
                        .file_tree_scroll
                        .scroll_to_item(row, ScrollStrategy::Nearest);
                }
                self.composer_input.update(cx, |input, cx| {
                    input.set_value(composer.body, window, cx);
                    input.focus(window, cx);
                });
                self.rebuild_diff(index, self.wide);
                self.status = if routed_to_full {
                    "Pending comment reopened in Full PR because its persisted canonical coordinate does not claim the earlier narrow source view."
                        .into()
                } else {
                    composer
                        .notice
                        .unwrap_or_else(|| "Pending comment opened.".into())
                };
            }
            Err(error) => self.status = error,
        }
        cx.notify();
    }

    fn reopen_file_draft(&mut self, draft_id: &str, window: &mut Window, cx: &mut Context<Root>) {
        let Some(index) = self.active_tab else { return };
        if !self.restore_pending_active_tab_input_in_window(window, cx)
            || !self.shared_composer_admitted(index)
        {
            return;
        }
        if self.tabs[index].write_in_flight {
            self.status =
                "Wait for the started review action before editing this file draft.".into();
            return;
        }
        if self.persist_active_composer_before_transition(
            index,
            "Saving the active comment before changing targets; open the saved file draft again afterward.",
            cx,
        ) {
            return;
        }
        if !matches!(
            self.tabs[index].comparison_picker.request,
            ComparisonRequest::FullPullRequest
        ) {
            self.restore_full_comparison(index, cx);
        }
        let result = match &mut self.tabs[index].interactions {
            InteractionState::Ready(controller) => controller.reopen_file_draft(draft_id),
            InteractionState::Loading => Err("Review recovery is still loading.".into()),
            InteractionState::RecoveryRequired(reason) => Err(reason.clone()),
        };
        match result {
            Ok(composer) => {
                if self.tabs[index]
                    .session
                    .as_mut()
                    .is_some_and(|session| session.select_file(&composer.target.file_key))
                    && let Some(row) = self.tabs[index]
                        .file_tree
                        .reveal_file(&composer.target.file_key)
                {
                    self.tabs[index]
                        .file_tree_scroll
                        .scroll_to_item(row, ScrollStrategy::Nearest);
                }
                self.composer_input.update(cx, |input, cx| {
                    input.set_value(composer.body, window, cx);
                    input.focus(window, cx);
                });
                self.rebuild_diff(index, self.wide);
                self.status = composer
                    .notice
                    .unwrap_or_else(|| "File-level draft opened.".into());
            }
            Err(error) => self.status = error,
        }
        cx.notify();
    }

    fn persist_composer(&mut self, cx: &mut Context<Root>) {
        let Some(index) = self.active_tab else { return };
        if !self.shared_composer_admitted(index) {
            return;
        }
        if self.tabs[index].write_in_flight {
            self.status = "Wait for the started review operation to settle.".into();
            return;
        }
        let body = self.composer_input.read(cx).value().to_string();
        let (snapshot, store, authority, expected, draft_id, identity, number) = {
            let tab = &mut self.tabs[index];
            let InteractionState::Ready(controller) = &mut tab.interactions else {
                self.status = "Review recovery is unavailable.".into();
                return;
            };
            let snapshot = match controller.stage_composer_text(body.clone()) {
                Ok(snapshot) => snapshot,
                Err(error) => {
                    self.status = error;
                    return;
                }
            };
            let draft_id = controller
                .composer
                .as_ref()
                .and_then(|composer| composer.draft_id.clone())
                .or_else(|| {
                    controller
                        .file_composer
                        .as_ref()
                        .and_then(|composer| composer.draft_id.clone())
                })
                .expect("staging creates a draft identity");
            (
                snapshot,
                controller.store.clone(),
                controller.authority.clone(),
                controller.durable_composition.clone(),
                draft_id,
                tab.repository.cache_key(),
                tab.pull_request.number,
            )
        };
        self.status = "Saving local review recovery…".into();
        let (latest, lock, sequence) = self.next_review_state_write(&identity, number);
        let save_epoch = TabReadEpoch {
            instance: self.tabs[index].instance_generation,
            generation: sequence,
        };
        let completion_latest = latest.clone();
        let snapshot_for_save = snapshot.clone();
        let task = cx.background_spawn(async move {
            let _guard = lock
                .lock()
                .map_err(|_| "Review recovery save lock failed.".to_owned())?;
            if latest.load(Ordering::Acquire) != sequence {
                return Ok(false);
            }
            authority
                .save_if_current(&store, expected.as_ref(), &snapshot_for_save)
                .map(|()| true)
        });
        cx.spawn(async move |root, cx| {
            let result = task.await;
            let _ = root.update(cx, |root, cx| {
                let Root::Review(this) = root else { return };
                let Some(index) = this.tabs.iter().position(|tab| {
                    tab.repository.cache_key() == identity
                        && tab.pull_request.number == number
                        && save_epoch.matches(
                            tab.instance_generation,
                            completion_latest.load(Ordering::Acquire),
                        )
                }) else {
                    return;
                };
                if !matches!(result, Ok(false))
                    && let InteractionState::Ready(controller) = &mut this.tabs[index].interactions
                {
                    controller.finish_composer_save(
                        &snapshot,
                        &draft_id,
                        &body,
                        result.clone().map(|_| ()),
                    );
                }
                this.status = match result {
                    Ok(true) => "Review text saved locally.".into(),
                    Ok(false) => "A newer local review save superseded this completion.".into(),
                    Err(error) => {
                        format!("Local save failed; text remains in the open composer: {error}")
                    }
                };
                this.rebuild_diff(index, this.wide);
                cx.notify();
            });
        })
        .detach();
    }

    fn close_inline_composer(&mut self, cx: &mut Context<Root>) {
        let Some(index) = self.active_tab else { return };
        if !self.shared_composer_admitted(index) {
            return;
        }
        if self.tabs[index].write_in_flight {
            self.status = "Wait for the started review action before closing this composer.".into();
            return;
        }
        if self.persist_active_composer_before_transition(
            index,
            "Saving local recovery before close; close again after it is durable.",
            cx,
        ) {
            return;
        }
        if let InteractionState::Ready(controller) = &mut self.tabs[index].interactions {
            controller.composer = None;
            controller.file_composer = None;
        }
        self.rebuild_diff(index, self.wide);
        self.status = "Inline composer closed; saved text remains available.".into();
        cx.notify();
    }

    fn start_comment_write(&mut self, immediate: bool, cx: &mut Context<Root>) {
        let Some(index) = self.active_tab else { return };
        if !self.shared_composer_admitted(index) {
            return;
        }
        if self.tabs[index].write_in_flight {
            self.status = "A review write is already in progress.".into();
            return;
        }
        if matches!(
            &self.tabs[index].interactions,
            InteractionState::Ready(controller) if controller.file_composer.is_some()
        ) {
            self.status = "Use Review pending-only write for a file-level comment; file comments are never posted immediately."
                .into();
            return;
        }
        let input_body = self.composer_input.read(cx).value().to_string();
        let needs_save = match &self.tabs[index].interactions {
            InteractionState::Ready(controller) => controller
                .composer
                .as_ref()
                .map(|composer| !composer.durable || composer.body != input_body)
                .or_else(|| {
                    controller
                        .file_composer
                        .as_ref()
                        .map(|composer| !composer.durable || composer.body != input_body)
                })
                .unwrap_or(true),
            _ => true,
        };
        if needs_save {
            self.persist_composer(cx);
            self.status =
                "The current text must finish saving locally; invoke the remote action again."
                    .into();
            return;
        }
        let (repository, number, mut composition, store, authority, expected, operation_id) = {
            let tab = &mut self.tabs[index];
            let (Some(session), Some(canonical)) =
                (tab.session.as_ref(), tab.canonical_session.as_ref())
            else {
                return;
            };
            let InteractionState::Ready(controller) = &mut tab.interactions else {
                return;
            };
            let operation_id = if immediate {
                controller.prepare_immediate_with_canonical(session, canonical)
            } else {
                controller.prepare_pending_with_canonical(session, canonical)
            };
            let operation_id = match operation_id {
                Ok(operation_id) => operation_id,
                Err(error) => {
                    self.status = error;
                    return;
                }
            };
            tab.details_generation += 1;
            tab.write_in_flight = true;
            (
                tab.repository.clone(),
                tab.pull_request.number,
                controller.composition.clone(),
                controller.store.clone(),
                controller.authority.clone(),
                controller.durable_composition.clone(),
                operation_id,
            )
        };
        self.composer_input
            .update(cx, |input, cx| input.set_disabled(true, cx));
        let identity = repository.cache_key();
        let (latest, lock, sequence) = self.next_review_state_write(&identity, number);
        let attempt_id = next_attempt_id(&operation_id);
        let provider = GithubProvider::new(repository.account.clone());
        let task = cx.background_spawn(async move {
            let fallback = expected.clone();
            let execution = match lock.lock() {
                Err(_) => Err("Review recovery save lock failed; zero writes sent.".to_owned()),
                Ok(_guard) if latest.load(Ordering::Acquire) != sequence => Err(
                    "A newer review-state write superseded this preparation; zero writes sent."
                        .to_owned(),
                ),
                Ok(_guard) => authority.execute_if_current(&store, expected.as_ref(), || {
                    provider.execute_review_operation(
                        &repository,
                        &mut composition,
                        &store,
                        &operation_id,
                        &attempt_id,
                    )
                }),
            };
            let (outcome, durable) = match execution {
                Ok((outcome, durable)) => (outcome, durable),
                Err(reason) => (
                    ProviderMutationOutcome::PreflightRejected { reason },
                    fallback,
                ),
            };
            if matches!(outcome, ProviderMutationOutcome::PreflightRejected { .. }) {
                let _ = composition.cancel_prepared(&operation_id);
            }
            (composition, durable, outcome)
        });
        cx.spawn(async move |root, cx| {
            let (composition, durable, outcome) = task.await;
            let _ = root.update(cx, |root, cx| {
                let Root::Review(this) = root else { return };
                let Some(index) = this.tabs.iter().position(|tab| {
                    tab.repository.cache_key() == identity && tab.pull_request.number == number
                }) else {
                    // The provider already saved the authoritative outcome in DraftStore.
                    return;
                };
                this.tabs[index].write_in_flight = false;
                if let InteractionState::Ready(controller) = &mut this.tabs[index].interactions {
                    controller.composition = composition;
                    controller.durable_composition = durable;
                    if let Some(composer) = &mut controller.composer
                        && let Some(draft) = composer
                            .draft_id
                            .as_deref()
                            .and_then(|id| controller.composition.drafts.iter().find(|d| d.id == id))
                    {
                        composer.body = draft.body.clone();
                        composer.durable = true;
                    }
                }
                if this.active_tab == Some(index) {
                    this.composer_input
                        .update(cx, |input, cx| input.set_disabled(false, cx));
                }
                this.status = match outcome {
                    ProviderMutationOutcome::Acknowledged(_) if immediate => {
                        "Comment posted immediately; no review was submitted.".into()
                    }
                    ProviderMutationOutcome::Acknowledged(_) => {
                        "Comment added to the selected account’s pending review; review remains unsubmitted."
                            .into()
                    }
                    ProviderMutationOutcome::PreflightRejected { reason } => {
                        format!("Review action was not sent: {reason}")
                    }
                    ProviderMutationOutcome::Uncertain { reason, .. } => format!(
                        "Review outcome is uncertain and will not replay automatically: {reason}"
                    ),
                };
                this.rebuild_diff(index, this.wide);
                this.refresh_details(index, cx);
                cx.notify();
            });
        })
        .detach();
    }

    fn open_submit_confirmation(&mut self, cx: &mut Context<Root>) {
        let Some(index) = self.active_tab else { return };
        if self.tabs[index].submitted_summary_editor.close_after_save {
            self.status = "Wait for the local draft close operation to finish.".into();
            return;
        }
        if !matches!(self.tabs[index].interactions, InteractionState::Ready(_)) {
            self.status = "Review recovery must load before submission.".into();
            return;
        }
        self.tabs[index].confirmation = Some(NativeConfirmation::Submit {
            event: ReviewEvent::Comment,
        });
        self.inspector_open = true;
        self.status = "Review submission requires explicit confirmation.".into();
        cx.notify();
    }

    fn prepare_merge_confirmation(&mut self, cx: &mut Context<Root>) {
        let Some(index) = self.active_tab else { return };
        if self.tabs[index].submitted_summary_editor.close_after_save {
            self.status = "Wait for the local draft close operation to finish.".into();
            return;
        }
        let tab = &mut self.tabs[index];
        let Some(session) = tab.canonical_session.as_ref() else {
            return;
        };
        if tab.session.as_ref().is_none_or(|displayed| {
            displayed.revision().head_sha != tab.canonical_full_revision.head_sha
        }) {
            self.status =
                "Merge is unavailable from an older selected pair. Return to Full PR or choose a range ending at the canonical head."
                    .into();
            return;
        }
        if session.requires_advance_before_merge()
            || tab.pull_request.head_sha != tab.canonical_full_revision.head_sha
        {
            self.status = format!(
                "Merge is unavailable: advance the displayed review from {} to the last observed provider head {} before fresh merge preflight.",
                short_sha(tab.canonical_full_revision.head_sha.as_str()),
                short_sha(tab.pull_request.head_sha.as_str())
            );
            return;
        }
        if tab.write_in_flight {
            self.status = "Another mutation is still in progress.".into();
            return;
        }
        tab.write_in_flight = true;
        let repository = tab.repository.clone();
        let number = tab.pull_request.number;
        let reviewed_head = tab.canonical_full_revision.head_sha.clone();
        let identity = repository.cache_key();
        let preference_root = self.interaction_root.clone();
        let provider = GithubProvider::new(repository.account.clone());
        let task = cx.background_spawn(async move {
            let preparation = provider.prepare_merge(&repository, number, &reviewed_head)?;
            let preference = load_merge_preference(&preference_root, &repository)
                .ok()
                .flatten();
            Ok::<_, anyhow::Error>((preparation, preference))
        });
        cx.spawn(async move |root, cx| {
            let result = task.await;
            let _ = root.update(cx, |root, cx| {
                let Root::Review(this) = root else { return };
                let Some(index) = this.tabs.iter().position(|tab| {
                    tab.repository.cache_key() == identity && tab.pull_request.number == number
                }) else {
                    return;
                };
                this.tabs[index].write_in_flight = false;
                match result {
                    Ok((preparation, preferred)) => {
                        if preparation.current_head_sha != preparation.reviewed_head_sha {
                            this.status = "Merge preflight refused a stale reviewed head.".into();
                            return;
                        }
                        let method = preferred
                            .filter(|method| preparation.allowed_methods.contains(method))
                            .or_else(|| preparation.allowed_methods.first().copied());
                        let Some(method) = method else {
                            this.status =
                                "Repository settings expose no supported merge method.".into();
                            return;
                        };
                        let action = if preparation.merge_queue_required {
                            MergeConfirmationAction::Enqueue
                        } else if !preparation.blockers.is_empty()
                            && preparation.auto_merge_allowed
                            && preparation.can_enable_auto_merge
                        {
                            MergeConfirmationAction::EnableAutoMerge
                        } else {
                            MergeConfirmationAction::Merge
                        };
                        this.tabs[index].confirmation = Some(NativeConfirmation::Merge {
                            preparation: Box::new(preparation),
                            method,
                            action,
                        });
                        this.inspector_open = true;
                        this.status =
                            "Fresh merge preflight loaded; confirmation is required.".into();
                    }
                    Err(error) => {
                        this.status = format!("Merge preflight failed; no write sent: {error:#}")
                    }
                }
                cx.notify();
            });
        })
        .detach();
    }

    fn confirm_submission(&mut self, cx: &mut Context<Root>) {
        let Some(index) = self.active_tab else { return };
        if self.tabs[index].submitted_summary_editor.close_after_save {
            self.status = "Wait for the local draft close operation to finish.".into();
            return;
        }
        if self.tabs[index].write_in_flight {
            return;
        }
        let event = match &self.tabs[index].confirmation {
            Some(NativeConfirmation::Submit { event }) => event.clone(),
            _ => return,
        };
        let body = self.review_summary_input.read(cx).value().to_string();
        let (repository, number, mut composition, store, authority, expected, operation_id) = {
            let tab = &mut self.tabs[index];
            let current_head = tab.pull_request.head_sha.as_str();
            let (Some(displayed), Some(canonical)) =
                (tab.session.as_ref(), tab.canonical_session.as_ref())
            else {
                return;
            };
            let InteractionState::Ready(controller) = &mut tab.interactions else {
                return;
            };
            let operation_id = match controller.prepare_submission_with_displayed(
                displayed,
                canonical,
                event,
                body,
                Some(current_head),
            ) {
                Ok(operation_id) => operation_id,
                Err(error) => {
                    self.status = format!("Review is not ready to submit: {error}");
                    return;
                }
            };
            tab.details_generation += 1;
            tab.write_in_flight = true;
            (
                tab.repository.clone(),
                tab.pull_request.number,
                controller.composition.clone(),
                controller.store.clone(),
                controller.authority.clone(),
                controller.durable_composition.clone(),
                operation_id,
            )
        };
        self.review_summary_input
            .update(cx, |input, cx| input.set_disabled(true, cx));
        let identity = repository.cache_key();
        let (latest, lock, sequence) = self.next_review_state_write(&identity, number);
        let attempt_id = next_attempt_id(&operation_id);
        let provider = GithubProvider::new(repository.account.clone());
        let task = cx.background_spawn(async move {
            let fallback = expected.clone();
            let execution = match lock.lock() {
                Err(_) => Err("Review recovery save lock failed; zero writes sent.".to_owned()),
                Ok(_guard) if latest.load(Ordering::Acquire) != sequence => Err(
                    "A newer review-state write superseded this preparation; zero writes sent."
                        .to_owned(),
                ),
                Ok(_guard) => authority.execute_if_current(&store, expected.as_ref(), || {
                    provider.execute_review_operation(
                        &repository,
                        &mut composition,
                        &store,
                        &operation_id,
                        &attempt_id,
                    )
                }),
            };
            let (outcome, durable) = match execution {
                Ok((outcome, durable)) => (outcome, durable),
                Err(reason) => (
                    ProviderMutationOutcome::PreflightRejected { reason },
                    fallback,
                ),
            };
            if matches!(outcome, ProviderMutationOutcome::PreflightRejected { .. }) {
                let _ = composition.cancel_prepared(&operation_id);
            }
            (composition, durable, outcome)
        });
        cx.spawn(async move |root, cx| {
            let (composition, durable, outcome) = task.await;
            let _ = root.update(cx, |root, cx| {
                let Root::Review(this) = root else { return };
                let Some(index) = this.tabs.iter().position(|tab| {
                    tab.repository.cache_key() == identity && tab.pull_request.number == number
                }) else {
                    return;
                };
                this.tabs[index].write_in_flight = false;
                if let InteractionState::Ready(controller) = &mut this.tabs[index].interactions {
                    controller.composition = composition;
                    controller.durable_composition = durable;
                }
                if this.active_tab == Some(index) {
                    this.review_summary_input
                        .update(cx, |input, cx| input.set_disabled(false, cx));
                }
                match outcome {
                    ProviderMutationOutcome::Acknowledged(_) => {
                        this.tabs[index].confirmation = None;
                        this.status = "Review submitted against the explicitly confirmed displayed head."
                            .into();
                    }
                    ProviderMutationOutcome::PreflightRejected { reason } => {
                        this.status = format!("Review submission was not sent: {reason}");
                    }
                    ProviderMutationOutcome::Uncertain { reason, .. } => {
                        this.status = format!(
                            "Submission outcome is uncertain. Authoritative reads only; explicit reconciliation is required: {reason}"
                        );
                    }
                }
                this.refresh_details(index, cx);
                cx.notify();
            });
        })
        .detach();
    }

    fn confirm_merge(&mut self, cx: &mut Context<Root>) {
        let Some(index) = self.active_tab else { return };
        if self.tabs[index].submitted_summary_editor.close_after_save {
            self.status = "Wait for the local draft close operation to finish.".into();
            return;
        }
        if self.tabs[index].write_in_flight {
            return;
        }
        let (preparation, method, confirmation_action) = match self.tabs[index].confirmation.clone()
        {
            Some(NativeConfirmation::Merge {
                preparation,
                method,
                action,
            }) => (preparation, method, action),
            _ => return,
        };
        let title = nonempty_option(self.merge_title_input.read(cx).value().to_string());
        let body = nonempty_option(self.merge_body_input.read(cx).value().to_string());
        let action = match confirmation_action {
            MergeConfirmationAction::Merge => MergeAction::Merge {
                method,
                commit_title: title,
                commit_message: body,
            },
            MergeConfirmationAction::EnableAutoMerge => MergeAction::EnableAutoMerge {
                method,
                commit_title: title,
                commit_message: body,
            },
            MergeConfirmationAction::DisableAutoMerge => MergeAction::DisableAutoMerge,
            MergeConfirmationAction::Enqueue => MergeAction::Enqueue,
            MergeConfirmationAction::Dequeue => MergeAction::Dequeue,
        };
        let repository = self.tabs[index].repository.clone();
        let number = self.tabs[index].pull_request.number;
        let identity = repository.cache_key();
        let operation_id = next_attempt_id("merge-operation");
        let request = MergeExecutionRequest {
            attempt_id: next_attempt_id(&operation_id),
            operation_id,
            action,
        };
        let key = match ReviewKey::for_repository("github", &repository, number) {
            Ok(key) => key,
            Err(error) => {
                self.status = error.to_string();
                return;
            }
        };
        self.tabs[index].details_generation += 1;
        self.tabs[index].write_in_flight = true;
        let journal_root = self.interaction_root.clone();
        let preference_root = self.interaction_root.clone();
        let provider = GithubProvider::new(repository.account.clone());
        let task = cx.background_spawn(async move {
            let journal = ActionJournal::open(&journal_root, key).map_err(|reason| {
                ProviderMutationOutcome::<cibergit::domain::MergeAcknowledgement>::PreflightRejected {
                    reason: format!("Cannot open caller journal; zero writes sent: {reason}"),
                }
            });
            let outcome = match journal {
                Ok(journal) => dispatch_merge(
                    &journal,
                    &provider,
                    &repository,
                    &preparation,
                    &request,
                ),
                Err(outcome) => outcome,
            };
            let preference = if matches!(
                outcome,
                ProviderMutationOutcome::Acknowledged(_)
            ) {
                save_merge_preference(&preference_root, &repository, method)
            } else {
                Ok(())
            };
            (outcome, preference)
        });
        cx.spawn(async move |root, cx| {
            let (outcome, preference) = task.await;
            let _ = root.update(cx, |root, cx| {
                let Root::Review(this) = root else { return };
                let Some(index) = this.tabs.iter().position(|tab| {
                    tab.repository.cache_key() == identity && tab.pull_request.number == number
                }) else {
                    // The caller journal owns this completion even if the tab closed.
                    return;
                };
                this.tabs[index].write_in_flight = false;
                this.status = match outcome {
                    ProviderMutationOutcome::Acknowledged(ack) if ack.merged => format!(
                        "Pull request merged{}.",
                        ack.merge_commit_sha
                            .map(|sha| format!(" as {}", short_sha(&sha)))
                            .unwrap_or_default()
                    ),
                    ProviderMutationOutcome::Acknowledged(_) => match confirmation_action {
                        MergeConfirmationAction::EnableAutoMerge => {
                            "Auto-merge enabled; the pull request is not yet merged.".into()
                        }
                        MergeConfirmationAction::Enqueue => {
                            "Pull request queued; queue acceptance is not a completed merge.".into()
                        }
                        MergeConfirmationAction::DisableAutoMerge => {
                            "Auto-merge disabled after authoritative reconciliation.".into()
                        }
                        MergeConfirmationAction::Dequeue => {
                            "Pull request removed from the merge queue.".into()
                        }
                        MergeConfirmationAction::Merge => {
                            "Merge acknowledged; refreshing authoritative state.".into()
                        }
                    },
                    ProviderMutationOutcome::PreflightRejected { reason } => {
                        format!("Merge action was not sent: {reason}")
                    }
                    ProviderMutationOutcome::Uncertain { reason, .. } => format!(
                        "Merge outcome is uncertain and will not replay automatically: {reason}"
                    ),
                };
                if let Err(error) = preference {
                    this.status.push_str(&format!(
                        " Preferred method was not saved and is not claimed durable: {error}"
                    ));
                }
                this.tabs[index].confirmation = None;
                this.refresh_active(cx);
                cx.notify();
            });
        })
        .detach();
    }

    fn start_submitted_draft_load(&mut self, index: usize, cx: &mut Context<Root>) {
        let Some(tab) = self.tabs.get_mut(index) else {
            return;
        };
        tab.submitted_summary_editor.load_generation = tab
            .submitted_summary_editor
            .load_generation
            .saturating_add(1);
        tab.submitted_summary_editor.load_state = SubmittedDraftLoadState::Loading;
        let captured_edit_generation = tab.submitted_summary_editor.edit_generation;
        let repository = tab.repository.clone();
        let pull_request = tab.pull_request.number;
        let token = SubmittedDraftCallbackToken {
            workspace_instance: self.workspace_instance,
            tab_instance: tab.instance_generation,
            repository_key: repository.cache_key(),
            pull_request,
            generation: tab.submitted_summary_editor.load_generation,
        };
        let store = self.submitted_draft_store.clone();
        let task = cx.background_spawn(async move {
            store
                .load(&repository, pull_request)
                .map_err(|error| format!("{error:#}"))
        });
        cx.spawn(async move |root, cx| {
            let result = task.await;
            let _ = root.update(cx, |root, cx| {
                let Root::Review(this) = root else { return };
                this.apply_submitted_draft_load_completion(
                    &token,
                    captured_edit_generation,
                    result,
                    cx,
                );
            });
        })
        .detach();
    }

    fn apply_submitted_draft_load_completion(
        &mut self,
        token: &SubmittedDraftCallbackToken,
        captured_edit_generation: u64,
        result: Result<SubmittedDraftStoreSnapshot, String>,
        cx: &mut Context<Root>,
    ) -> bool {
        let Some(index) = self.tabs.iter().position(|tab| {
            token.matches_values(
                self.workspace_instance,
                tab.instance_generation,
                &tab.repository.cache_key(),
                tab.pull_request.number,
                tab.submitted_summary_editor.load_generation,
            )
        }) else {
            return false;
        };
        match result {
            Ok(snapshot) => {
                let recovered = snapshot.drafts.len();
                let queued = self.tabs[index]
                    .submitted_summary_editor
                    .merge_loaded(captured_edit_generation, snapshot);
                if self.tabs[index]
                    .submitted_summary_editor
                    .conflict()
                    .is_some()
                {
                    self.status = "A same-review saved draft and newer local text are both preserved. Choose which version to keep; no overwrite was scheduled.".into();
                } else if recovered > 0 {
                    self.status = format!(
                        "Recovered {recovered} unsent submitted-review draft{} as local history. Choose Edit against fresh Activity to continue.",
                        if recovered == 1 { "" } else { "s" }
                    );
                }
                if queued {
                    self.start_next_submitted_draft_save(index, cx);
                }
            }
            Err(error) => {
                let editor = &mut self.tabs[index].submitted_summary_editor;
                editor.load_state = SubmittedDraftLoadState::Failed;
                editor.persistence_error = Some(format!(
                    "Submitted-review draft recovery failed; the original was preserved and editing is disabled: {error}"
                ));
                self.status = editor.persistence_error.clone().unwrap_or_default();
            }
        }
        cx.notify();
        true
    }

    fn retry_submitted_draft_load(&mut self, cx: &mut Context<Root>) {
        let Some(index) = self.active_tab else { return };
        if self.tabs[index]
            .submitted_summary_editor
            .in_flight
            .is_some()
            || self.tabs[index].submitted_summary_editor.clear_in_flight
        {
            self.status =
                "Wait for the current local draft operation before retrying recovery.".into();
            cx.notify();
            return;
        }
        self.start_submitted_draft_load(index, cx);
        self.status = "Retrying bounded submitted-review draft recovery…".into();
        cx.notify();
    }

    fn resolve_submitted_draft_conflict(
        &mut self,
        keep_current: bool,
        window: &mut Window,
        cx: &mut Context<Root>,
    ) {
        let Some(index) = self.active_tab else { return };
        let resolved = if keep_current {
            self.tabs[index]
                .submitted_summary_editor
                .resolve_conflict_keep_current()
        } else {
            self.tabs[index]
                .submitted_summary_editor
                .resolve_conflict_use_saved()
        };
        if !resolved {
            return;
        }
        let body = self.tabs[index]
            .submitted_summary_editor
            .active_draft()
            .map(|draft| draft.body.clone())
            .unwrap_or_default();
        self.submitted_summary_input
            .update(cx, |input, cx| input.set_value(body, window, cx));
        if keep_current {
            self.status = "Current text was explicitly chosen; the saved version remains visible until the CAS save succeeds.".into();
        } else {
            self.status = "The saved same-review text was explicitly restored; unrelated local-only and disk-only drafts were retained and are queued for CAS save.".into();
        }
        self.start_next_submitted_draft_save(index, cx);
        cx.notify();
    }

    fn retry_submitted_draft_save(&mut self, cx: &mut Context<Root>) {
        let Some(index) = self.active_tab else { return };
        let editor = &mut self.tabs[index].submitted_summary_editor;
        if !editor.is_ready()
            || editor.in_flight.is_some()
            || editor.clear_in_flight
            || editor.pending_clear.is_some()
        {
            return;
        }
        editor.persistence_error = None;
        editor.queue_current();
        self.start_next_submitted_draft_save(index, cx);
        cx.notify();
    }

    fn schedule_submitted_draft_save(&mut self, index: usize, cx: &mut Context<Root>) {
        let Some(tab) = self.tabs.get(index) else {
            return;
        };
        let edit_generation = tab.submitted_summary_editor.edit_generation;
        let tab_instance = tab.instance_generation;
        let repository_key = tab.repository.cache_key();
        let pull_request = tab.pull_request.number;
        let workspace_instance = self.workspace_instance;
        cx.spawn(async move |root, cx| {
            cx.background_executor()
                .timer(Duration::from_millis(350))
                .await;
            let _ = root.update(cx, |root, cx| {
                let Root::Review(this) = root else { return };
                if this.workspace_instance != workspace_instance {
                    return;
                }
                let Some(index) = this.tabs.iter().position(|tab| {
                    tab.instance_generation == tab_instance
                        && tab.repository.cache_key() == repository_key
                        && tab.pull_request.number == pull_request
                        && tab.submitted_summary_editor.edit_generation == edit_generation
                }) else {
                    return;
                };
                if this.tabs[index].submitted_summary_editor.is_ready() {
                    this.tabs[index].submitted_summary_editor.queue_current();
                    if !this.tabs[index].write_in_flight {
                        this.start_next_submitted_draft_save(index, cx);
                    }
                    cx.notify();
                }
            });
        })
        .detach();
    }

    fn start_next_submitted_draft_save(&mut self, index: usize, cx: &mut Context<Root>) {
        if self.tabs.get(index).is_none_or(|tab| tab.write_in_flight) {
            return;
        }
        let Some(tab) = self.tabs.get_mut(index) else {
            return;
        };
        let Some(save) = tab.submitted_summary_editor.start_next() else {
            if tab.submitted_summary_editor.close_after_save
                && tab.submitted_summary_editor.is_current_durable()
            {
                self.finish_close_tab(index, cx);
            }
            return;
        };
        tab.submitted_summary_editor.save_generation = tab
            .submitted_summary_editor
            .save_generation
            .saturating_add(1);
        let token = SubmittedDraftCallbackToken {
            workspace_instance: self.workspace_instance,
            tab_instance: tab.instance_generation,
            repository_key: tab.repository.cache_key(),
            pull_request: tab.pull_request.number,
            generation: tab.submitted_summary_editor.save_generation,
        };
        let expected_generation = tab.submitted_summary_editor.durable.generation;
        let repository = tab.repository.clone();
        let pull_request = tab.pull_request.number;
        let active_review = save.snapshot.active_review.clone();
        let drafts = save.snapshot.drafts.clone();
        let store = self.submitted_draft_store.clone();
        self.status = "Saving submitted-review draft… durability pending.".into();
        let task = cx.background_spawn(async move {
            store
                .save_if_current(
                    &repository,
                    pull_request,
                    expected_generation,
                    active_review.as_ref(),
                    &drafts,
                )
                .map_err(|error| format!("{error:#}"))
        });
        cx.spawn(async move |root, cx| {
            let result = task.await;
            let _ = root.update(cx, |root, cx| {
                let Root::Review(this) = root else { return };
                this.apply_submitted_draft_save_completion(&token, result, cx);
            });
        })
        .detach();
    }

    fn apply_submitted_draft_save_completion(
        &mut self,
        token: &SubmittedDraftCallbackToken,
        result: Result<SubmittedDraftStoreSnapshot, String>,
        cx: &mut Context<Root>,
    ) -> bool {
        let Some(index) = self.tabs.iter().position(|tab| {
            tab.repository.cache_key() == token.repository_key
                && tab.pull_request.number == token.pull_request
        }) else {
            return false;
        };
        let repository_key = self.tabs[index].repository.cache_key();
        let completion = apply_submitted_draft_save_if_current(
            token,
            self.workspace_instance,
            self.tabs[index].instance_generation,
            &repository_key,
            self.tabs[index].pull_request.number,
            &mut self.tabs[index].submitted_summary_editor,
            result,
        );
        let Some(completion) = completion else {
            return false;
        };
        let mut saved = false;
        match completion {
            Ok(()) => {
                self.status = "Submitted-review draft is durable.".into();
                saved = true;
            }
            Err(error) => {
                let editor = &mut self.tabs[index].submitted_summary_editor;
                editor.pending = None;
                editor.close_after_save = false;
                editor.persistence_error = Some(format!(
                    "Submitted-review draft was not made durable; text remains open and close was refused: {error}"
                ));
                self.status = editor.persistence_error.clone().unwrap_or_default();
                if self.active_tab == Some(index) {
                    self.submitted_summary_input
                        .update(cx, |input, cx| input.set_disabled(false, cx));
                }
            }
        }
        if self.tabs[index]
            .submitted_summary_editor
            .pending_clear
            .is_some()
        {
            self.start_pending_submitted_draft_clear(index, cx);
        } else if saved {
            self.start_next_submitted_draft_save(index, cx);
        }
        self.update_shared_composer_disabled(cx);
        cx.notify();
        true
    }

    fn request_submitted_draft_clear(
        &mut self,
        index: usize,
        captured: SubmittedSummaryDraft,
        cx: &mut Context<Root>,
    ) {
        let Some(tab) = self.tabs.get_mut(index) else {
            return;
        };
        tab.submitted_summary_editor.queue_clear(captured);
        self.start_pending_submitted_draft_clear(index, cx);
    }

    fn start_pending_submitted_draft_clear(&mut self, index: usize, cx: &mut Context<Root>) {
        let Some(tab) = self.tabs.get_mut(index) else {
            return;
        };
        if tab.write_in_flight
            || tab.submitted_summary_editor.clear_in_flight
            || tab.submitted_summary_editor.in_flight.is_some()
        {
            return;
        }
        let Some(clear) = tab.submitted_summary_editor.pending_clear.take() else {
            return;
        };
        let durable_has_predecessor = tab
            .submitted_summary_editor
            .durable
            .drafts
            .iter()
            .any(|draft| same_draft_history(draft, &clear.captured));
        if !durable_has_predecessor {
            tab.submitted_summary_editor.persistence_error = Some(
                "Remote edit was acknowledged, but the durable local predecessor changed before clear. It was preserved and no automatic clear or replay was attempted."
                    .into(),
            );
            self.status = tab
                .submitted_summary_editor
                .persistence_error
                .clone()
                .unwrap_or_default();
            if self.active_tab == Some(index) {
                self.submitted_summary_input
                    .update(cx, |input, cx| input.set_disabled(false, cx));
            }
            return;
        }
        let expected_generation = tab.submitted_summary_editor.durable.generation;
        tab.submitted_summary_editor.clear_in_flight = true;
        tab.submitted_summary_editor.save_generation = tab
            .submitted_summary_editor
            .save_generation
            .saturating_add(1);
        let token = SubmittedDraftCallbackToken {
            workspace_instance: self.workspace_instance,
            tab_instance: tab.instance_generation,
            repository_key: tab.repository.cache_key(),
            pull_request: tab.pull_request.number,
            generation: tab.submitted_summary_editor.save_generation,
        };
        let repository = tab.repository.clone();
        let pull_request = tab.pull_request.number;
        let store = self.submitted_draft_store.clone();
        let clear_review = clear.captured.review.coordinates.clone();
        let clear_body = clear.captured.body.clone();
        let task = cx.background_spawn(async move {
            store
                .clear_if_current(
                    &repository,
                    pull_request,
                    expected_generation,
                    &clear_review,
                    &clear_body,
                )
                .map_err(|error| format!("{error:#}"))
        });
        cx.spawn(async move |root, cx| {
            let result = task.await;
            let _ = root.update(cx, |root, cx| {
                let Root::Review(this) = root else { return };
                this.apply_submitted_draft_clear_completion(&token, &clear.captured, result, cx);
            });
        })
        .detach();
    }

    fn apply_submitted_draft_clear_completion(
        &mut self,
        token: &SubmittedDraftCallbackToken,
        captured: &SubmittedSummaryDraft,
        result: Result<SubmittedDraftStoreSnapshot, String>,
        cx: &mut Context<Root>,
    ) -> bool {
        let Some(index) = self.tabs.iter().position(|tab| {
            token.matches_values(
                self.workspace_instance,
                tab.instance_generation,
                &tab.repository.cache_key(),
                tab.pull_request.number,
                tab.submitted_summary_editor.save_generation,
            )
        }) else {
            return false;
        };
        let completion = self.tabs[index]
            .submitted_summary_editor
            .complete_clear(captured, result);
        match completion {
            Ok(still_exact) => {
                if still_exact {
                    self.status = "Acknowledged submitted-review edit and durably cleared only its exact sent local draft.".into();
                } else {
                    self.status = "Acknowledged edit cleared its exact predecessor, while newer local text was retained and queued against the tombstone generation.".into();
                }
                if self.active_tab == Some(index) {
                    self.submitted_summary_input
                        .update(cx, |input, cx| input.set_disabled(false, cx));
                }
                self.start_next_submitted_draft_save(index, cx);
            }
            Err(error) => {
                let editor = &mut self.tabs[index].submitted_summary_editor;
                editor.close_after_save = false;
                editor.persistence_error = Some(format!(
                    "Remote edit was acknowledged, but its exact local draft could not be durably cleared; newer or foreign text was preserved: {error}"
                ));
                self.status = editor.persistence_error.clone().unwrap_or_default();
                if self.active_tab == Some(index) {
                    self.submitted_summary_input
                        .update(cx, |input, cx| input.set_disabled(false, cx));
                }
            }
        }
        self.update_shared_composer_disabled(cx);
        cx.notify();
        true
    }

    fn begin_submitted_summary_edit(
        &mut self,
        review: cibergit::domain::PullRequestReview,
        window: &mut Window,
        cx: &mut Context<Root>,
    ) {
        let Some(index) = self.active_tab else { return };
        if !self.restore_pending_active_tab_input_in_window(window, cx) {
            self.status = "Submitted-review input restoration has not reached this exact tab; zero text was staged.".into();
            cx.notify();
            return;
        }
        if self.tabs[index].write_in_flight
            || self.tabs[index].submitted_summary_editor.clear_in_flight
            || self.tabs[index]
                .submitted_summary_editor
                .pending_clear
                .is_some()
        {
            self.status =
                "Wait for the submitted-review write and exact local clear to settle before selecting another review."
                    .into();
            cx.notify();
            return;
        }
        if !self.tabs[index].submitted_summary_editor.is_ready() {
            self.status = if self.tabs[index]
                .submitted_summary_editor
                .conflict()
                .is_some()
            {
                "Resolve the two preserved same-review draft versions before editing.".into()
            } else {
                "Wait for submitted-review draft recovery, or retry the failed local read, before editing."
                    .into()
            };
            cx.notify();
            return;
        }
        let staged_body = self.submitted_summary_input.read(cx).value().to_string();
        self.tabs[index]
            .submitted_summary_editor
            .store_active_body(staged_body);
        let tab = &self.tabs[index];
        let fresh = tab.details.as_ref().and_then(|details| {
            details
                .reviews
                .iter()
                .find(|candidate| candidate.coordinates == review.coordinates)
        });
        let Some(fresh) = fresh.cloned() else {
            self.status =
                "Fresh submitted-review evidence changed; refresh Activity before editing.".into();
            cx.notify();
            return;
        };
        if let Err(reason) = submitted_review_edit_action(
            &tab.repository,
            tab.pull_request.number,
            &fresh,
            fresh.body.clone(),
        ) {
            self.status = format!("Submitted review edit unavailable: {reason}");
            cx.notify();
            return;
        }
        self.tabs[index].editing_pending_summary = false;
        let (body, source_refreshed, resumed) =
            self.tabs[index].submitted_summary_editor.begin(fresh);
        self.schedule_submitted_draft_save(index, cx);
        self.submitted_summary_input.update(cx, |input, cx| {
            input.set_value(body, window, cx);
            input.focus(window, cx);
        });
        self.status = if source_refreshed {
            "Fresh review source adopted; your typed summary draft was retained.".into()
        } else if resumed {
            "Resumed the retained draft for this submitted review.".into()
        } else {
            "Editing a fresh author-owned submitted review summary.".into()
        };
        cx.notify();
    }

    fn prepare_submitted_summary_confirmation(&mut self, cx: &mut Context<Root>) {
        let Some(index) = self.active_tab else { return };
        if self.active_tab_input_restore.is_some() {
            self.status = "Wait for this tab's exact submitted-review text to be restored before preparing confirmation.".into();
            cx.notify();
            return;
        }
        if self.tabs[index].write_in_flight
            || self.tabs[index].submitted_summary_editor.clear_in_flight
            || self.tabs[index]
                .submitted_summary_editor
                .pending_clear
                .is_some()
        {
            self.status = "Another mutation is still in progress.".into();
            return;
        }
        let Some(draft) = self.tabs[index]
            .submitted_summary_editor
            .active_draft()
            .cloned()
        else {
            self.status = "Choose an author-owned submitted review first.".into();
            return;
        };
        let frozen_review = draft.review;
        let current = self.tabs[index]
            .details
            .as_ref()
            .and_then(|details| {
                details
                    .reviews
                    .iter()
                    .find(|candidate| candidate.coordinates == frozen_review.coordinates)
            })
            .cloned();
        let Some(current) = current.filter(|current| current == &frozen_review) else {
            self.status =
                "Fresh submitted-review evidence changed; zero writes sent. Choose Edit again to adopt the new source while retaining your typed draft."
                    .into();
            return;
        };
        let body = self.submitted_summary_input.read(cx).value().to_string();
        let changed = self.tabs[index]
            .submitted_summary_editor
            .store_active_body(body.clone());
        if changed {
            self.schedule_submitted_draft_save(index, cx);
        }
        if !self.tabs[index]
            .submitted_summary_editor
            .is_current_durable()
        {
            self.status = "The exact visible submitted-review draft is not durable yet. Wait for save completion (or resolve its error), then review the exact edit again.".into();
            cx.notify();
            return;
        }
        match submitted_review_edit_action(
            &self.tabs[index].repository,
            self.tabs[index].pull_request.number,
            &current,
            body,
        ) {
            Ok(action) => {
                self.tabs[index].submitted_confirmation_generation = self.tabs[index]
                    .submitted_confirmation_generation
                    .checked_add(1)
                    .expect("submitted confirmation generation overflow");
                let generation = self.tabs[index].submitted_confirmation_generation;
                self.tabs[index].confirmation = Some(NativeConfirmation::UpdateSubmittedSummary {
                    generation,
                    action: Box::new(action),
                });
                self.inspector_open = true;
                self.status =
                    "Submitted review summary frozen; explicit confirmation is required.".into();
            }
            Err(reason) => {
                self.status = format!("Submitted review edit unavailable: {reason}");
            }
        }
        cx.notify();
    }

    fn submitted_confirmation_index(&self, token: &SubmittedConfirmationToken) -> Option<usize> {
        if self.active_tab_input_restore.is_some() {
            return None;
        }
        let index = self.active_tab?;
        let tab = self.tabs.get(index)?;
        token
            .matches_values(
                self.workspace_instance,
                tab.instance_generation,
                &tab.repository.cache_key(),
                tab.pull_request.number,
                tab.confirmation.as_ref(),
            )
            .then_some(index)
    }

    fn confirm_submitted_summary(
        &mut self,
        token: SubmittedConfirmationToken,
        cx: &mut Context<Root>,
    ) {
        let Some(index) = self.submitted_confirmation_index(&token) else {
            self.status =
                "That submitted-review confirmation is no longer current; zero writes sent.".into();
            cx.notify();
            return;
        };
        if self.tabs[index].write_in_flight {
            return;
        }
        let exact_durable_body = match &token.action {
            ReviewAuxiliaryAction::UpdateSubmittedSummary { review, body, .. } => self.tabs[index]
                .submitted_summary_editor
                .active_draft()
                .is_some_and(|draft| {
                    same_review_coordinates(&draft.review.coordinates, review)
                        && draft.body == *body
                }),
            _ => false,
        } && self.tabs[index]
            .submitted_summary_editor
            .is_current_durable();
        if !exact_durable_body {
            self.status = "The visible submitted-review draft changed or is not durably saved; the frozen confirmation sent zero writes. Review the exact edit again.".into();
            cx.notify();
            return;
        }
        self.tabs[index].confirmation = None;
        self.dispatch_auxiliary_action(token.action, cx);
    }

    fn cancel_submitted_summary_confirmation(
        &mut self,
        token: &SubmittedConfirmationToken,
        cx: &mut Context<Root>,
    ) -> bool {
        let Some(index) = self.submitted_confirmation_index(token) else {
            self.status =
                "That submitted-review confirmation is no longer current; zero writes sent.".into();
            cx.notify();
            return false;
        };
        if self.tabs[index].write_in_flight {
            return false;
        }
        self.tabs[index].confirmation = None;
        self.status =
            "Submitted review edit cancelled; draft retained and zero writes sent.".into();
        cx.notify();
        true
    }

    fn prepare_file_comment_confirmation(&mut self, cx: &mut Context<Root>) {
        let Some(index) = self.active_tab else { return };
        if !self.shared_composer_admitted(index) {
            return;
        }
        if self.tabs[index].write_in_flight {
            self.status =
                "Wait for the active review write before confirming this file comment.".into();
            return;
        }
        let input_body = self.composer_input.read(cx).value().to_string();
        let (draft_id, target, durable, staged_body) = match &self.tabs[index].interactions {
            InteractionState::Ready(controller) => {
                let Some(composer) = controller.file_composer.as_ref() else {
                    self.status = "No file-level composer is open.".into();
                    return;
                };
                (
                    composer.draft_id.clone(),
                    composer.target.clone(),
                    composer.durable,
                    composer.body.clone(),
                )
            }
            InteractionState::Loading => {
                self.status = "Review recovery is still loading.".into();
                return;
            }
            InteractionState::RecoveryRequired(reason) => {
                self.status = reason.clone();
                return;
            }
        };
        if !durable || staged_body != input_body {
            self.persist_composer(cx);
            self.status = "The exact file-level text must finish saving locally; review the write again afterward."
                .into();
            return;
        }
        if input_body.is_empty() {
            self.status = "A file-level comment body is required.".into();
            return;
        }
        let Some(draft_id) = draft_id else {
            self.status = "The file-level draft has no durable identity.".into();
            return;
        };
        let Some(pending) = self.tabs[index].pending_snapshot.as_ref() else {
            self.status = "File-level comments are pending-only in this release, and no existing pending review was observed for the selected account. The local draft is retained; nothing was posted and no pending review was created."
                .into();
            return;
        };
        let Some(source) = pending.file_comment_source.clone() else {
            self.status = "The existing pending review lacks complete fresh file-comment evidence. Refresh Activity; the local draft is retained and zero writes were sent."
                .into();
            return;
        };
        if source.current_base_sha != target.base_sha
            || source.current_head_sha != target.commit_sha
            || source.repository.cache_key() != self.tabs[index].repository.cache_key()
            || source.review.remote_id != pending.review.coordinates.remote_id
        {
            self.status = "The fresh pending review and exact canonical file target no longer match. Refresh before confirming; the draft is retained."
                .into();
            return;
        }
        let Some(generation) = self.tabs[index].file_confirmation_generation.checked_add(1) else {
            self.status =
                "File-comment confirmation identity is exhausted; reopen this tab.".into();
            return;
        };
        self.tabs[index].file_confirmation_generation = generation;
        self.tabs[index].confirmation = Some(NativeConfirmation::PendingFileComment {
            generation,
            draft_id,
            body: input_body,
            target,
            source: Box::new(source),
        });
        self.inspector_open = true;
        self.inspector_scroll.set_offset(point(px(0.), px(0.)));
        self.status = "Review the exact pending-only file comment before sending.".into();
        cx.notify();
    }

    fn cancel_file_comment_confirmation(
        &mut self,
        token: &FileCommentConfirmationToken,
        cx: &mut Context<Root>,
    ) {
        let Some(index) = self.tabs.iter().position(|tab| {
            token.matches_values(
                self.workspace_instance,
                tab.instance_generation,
                &tab.repository.cache_key(),
                tab.pull_request.number,
                tab.confirmation.as_ref(),
            )
        }) else {
            self.status =
                "That file-comment confirmation is no longer current; zero writes sent.".into();
            cx.notify();
            return;
        };
        self.tabs[index].confirmation = None;
        self.status =
            "File-comment confirmation cancelled; local draft retained and zero writes sent."
                .into();
        cx.notify();
    }

    fn confirm_file_comment(
        &mut self,
        token: FileCommentConfirmationToken,
        cx: &mut Context<Root>,
    ) {
        let Some(index) = self.tabs.iter().position(|tab| {
            token.matches_values(
                self.workspace_instance,
                tab.instance_generation,
                &tab.repository.cache_key(),
                tab.pull_request.number,
                tab.confirmation.as_ref(),
            )
        }) else {
            self.status = "That file-comment confirmation is stale; zero writes sent and the draft remains available."
                .into();
            cx.notify();
            return;
        };
        if !self.shared_composer_admitted(index) {
            self.status =
                "The workspace or active action changed; zero file-comment writes sent.".into();
            cx.notify();
            return;
        }
        let visible_body = self.composer_input.read(cx).value().to_string();
        if !file_confirmation_matches_visible_body(&token, &visible_body) {
            self.tabs[index].confirmation = None;
            self.persist_composer(cx);
            let staged = matches!(
                &self.tabs[index].interactions,
                InteractionState::Ready(controller)
                    if controller.file_composer.as_ref().is_some_and(|composer|
                        composer.draft_id.as_deref() == Some(token.draft_id.as_str())
                            && composer.target == token.target
                            && composer.body == visible_body)
            );
            self.status = if staged {
                "The visible file-comment text changed after confirmation opened. Zero writes were sent; the new text is being retained locally and must be reviewed again."
                    .into()
            } else {
                "The visible file-comment text changed after confirmation opened. Zero writes were sent, but the new text could not be staged; keep this composer open and save again."
                    .into()
            };
            cx.notify();
            return;
        }
        let Some(NativeConfirmation::PendingFileComment { source, .. }) =
            self.tabs[index].confirmation.clone()
        else {
            return;
        };
        let still_fresh = self.tabs[index]
            .pending_snapshot
            .as_ref()
            .and_then(|pending| pending.file_comment_source.as_ref())
            == Some(source.as_ref());
        let exact_draft = matches!(
            &self.tabs[index].interactions,
            InteractionState::Ready(controller)
                if controller.file_composer.as_ref().is_some_and(|composer|
                    composer.durable
                        && composer.draft_id.as_deref() == Some(token.draft_id.as_str())
                        && composer.body == token.body
                        && composer.target == token.target)
        );
        if !still_fresh || !exact_draft {
            self.tabs[index].confirmation = None;
            self.status = "The pending source or exact local file draft changed after confirmation opened; zero writes sent. Review the retained draft again."
                .into();
            cx.notify();
            return;
        }
        self.tabs[index].confirmation = None;
        self.start_file_comment_write(*source, token, cx);
    }

    fn start_file_comment_write(
        &mut self,
        source: cibergit::domain::PendingFileCommentSource,
        confirmed: FileCommentConfirmationToken,
        cx: &mut Context<Root>,
    ) {
        let Some(index) = self.active_tab else { return };
        if !self.shared_composer_admitted(index) {
            return;
        }
        let (repository, number, mut composition, store, authority, expected, operation_id) = {
            let tab = &mut self.tabs[index];
            let InteractionState::Ready(controller) = &mut tab.interactions else {
                self.status = "Review recovery is unavailable.".into();
                return;
            };
            let operation_id = match controller.prepare_pending_file_comment(&source) {
                Ok(operation_id) => operation_id,
                Err(error) => {
                    self.status = error;
                    return;
                }
            };
            let exact = controller.composition.operations.iter().any(|operation| {
                operation.id == operation_id
                    && matches!(
                        operation.payload.as_ref(),
                        Some(cibergit::participation::ReviewOperationPayload::PendingFileComment(intent))
                            if intent.draft_id == confirmed.draft_id
                                && intent.body == confirmed.body
                                && intent.target == cibergit::participation::ReviewCommentTarget::File(confirmed.target.clone())
                                && intent.pending.pending_review.remote_id == confirmed.pending_source.review.remote_id
                    )
            });
            if !exact {
                let _ = controller.composition.cancel_prepared(&operation_id);
                self.status = "Frozen file-comment preparation changed; zero writes sent.".into();
                return;
            }
            tab.details_generation += 1;
            tab.write_in_flight = true;
            (
                tab.repository.clone(),
                tab.pull_request.number,
                controller.composition.clone(),
                controller.store.clone(),
                controller.authority.clone(),
                controller.durable_composition.clone(),
                operation_id,
            )
        };
        self.composer_input
            .update(cx, |input, cx| input.set_disabled(true, cx));
        let workspace_instance = self.workspace_instance;
        let tab_instance = self.tabs[index].instance_generation;
        let identity = repository.cache_key();
        let (latest, lock, sequence) = self.next_review_state_write(&identity, number);
        let completion_latest = latest.clone();
        let completion_operation_id = operation_id.clone();
        let attempt_id = next_attempt_id(&operation_id);
        let provider = GithubProvider::new(repository.account.clone());
        let task = cx.background_spawn(async move {
            let fallback = expected.clone();
            let execution = match lock.lock() {
                Err(_) => Err("Review recovery save lock failed; zero writes sent.".to_owned()),
                Ok(_guard) if latest.load(Ordering::Acquire) != sequence => Err(
                    "A newer review-state write superseded this file-comment preparation; zero writes sent."
                        .to_owned(),
                ),
                Ok(_guard) => authority.execute_if_current(&store, expected.as_ref(), || {
                    provider.execute_review_operation(
                        &repository,
                        &mut composition,
                        &store,
                        &operation_id,
                        &attempt_id,
                    )
                }),
            };
            let (outcome, durable) = match execution {
                Ok((outcome, durable)) => (outcome, durable),
                Err(reason) => (
                    ProviderMutationOutcome::PreflightRejected { reason },
                    fallback,
                ),
            };
            if matches!(outcome, ProviderMutationOutcome::PreflightRejected { .. }) {
                let _ = composition.cancel_prepared(&operation_id);
            }
            (composition, durable, outcome)
        });
        cx.spawn(async move |root, cx| {
            let (composition, durable, outcome) = task.await;
            let _ = root.update(cx, |root, cx| {
                let Root::Review(this) = root else { return };
                if this.workspace_instance != workspace_instance
                    || completion_latest.load(Ordering::Acquire) != sequence
                {
                    return;
                }
                let Some(index) = this.tabs.iter().position(|tab| {
                    tab.instance_generation == tab_instance
                        && tab.repository.cache_key() == identity
                        && tab.pull_request.number == number
                }) else {
                    return;
                };
                let owns_action = matches!(
                    &this.tabs[index].interactions,
                    InteractionState::Ready(controller)
                        if controller.composition.operations.iter().any(|operation| {
                            operation.id == completion_operation_id
                                && matches!(
                                    operation.target,
                                    cibergit::participation::ReviewOperationTarget::SynchronizePendingFileComment { .. }
                                )
                        })
                );
                if !owns_action {
                    return;
                }
                this.tabs[index].write_in_flight = false;
                if let InteractionState::Ready(controller) = &mut this.tabs[index].interactions {
                    controller.composition = composition;
                    controller.durable_composition = durable;
                    if matches!(outcome, ProviderMutationOutcome::Acknowledged(_))
                        && controller.file_composer.as_ref().is_some_and(|composer| {
                            composer.draft_id.as_deref() == Some(confirmed.draft_id.as_str())
                                && composer.body == confirmed.body
                                && composer.target == confirmed.target
                        })
                    {
                        controller.file_composer = None;
                    }
                }
                if this.active_tab == Some(index) {
                    this.composer_input
                        .update(cx, |input, cx| input.set_disabled(false, cx));
                }
                this.status = match outcome {
                    ProviderMutationOutcome::Acknowledged(_) => "File-level comment added to the exact selected-account pending review; the review remains unsubmitted."
                        .into(),
                    ProviderMutationOutcome::PreflightRejected { reason } => format!(
                        "File-level comment was not sent; the local draft is retained: {reason}"
                    ),
                    ProviderMutationOutcome::Uncertain { reason, .. } => format!(
                        "File-level comment outcome is uncertain and will not replay automatically; the frozen operation remains recoverable: {reason}"
                    ),
                };
                this.rebuild_diff(index, this.wide);
                this.refresh_details(index, cx);
                cx.notify();
            });
        })
        .detach();
    }

    fn dispatch_auxiliary_action(&mut self, action: ReviewAuxiliaryAction, cx: &mut Context<Root>) {
        let Some(index) = self.active_tab else { return };
        if !general_read_tab_can_start(self.tabs[index].submitted_summary_editor.close_after_save) {
            return;
        }
        if self.tabs[index].write_in_flight {
            self.status = "Another mutation is still in progress.".into();
            return;
        }
        let submitted_summary_edit = matches!(
            &action,
            ReviewAuxiliaryAction::UpdateSubmittedSummary { .. }
        );
        let submitted_summary_clear = match &action {
            ReviewAuxiliaryAction::UpdateSubmittedSummary { review, body, .. } => self.tabs[index]
                .submitted_summary_editor
                .active_draft()
                .filter(|draft| {
                    same_review_coordinates(&draft.review.coordinates, review)
                        && draft.body == *body
                })
                .cloned(),
            _ => None,
        };
        let repository = self.tabs[index].repository.clone();
        let number = self.tabs[index].pull_request.number;
        let tab_instance = self.tabs[index].instance_generation;
        let workspace_instance = self.workspace_instance;
        let identity = repository.cache_key();
        let operation_id = next_attempt_id("review-auxiliary");
        let request = ReviewAuxiliaryRequest {
            attempt_id: next_attempt_id(&operation_id),
            operation_id,
            action,
        };
        let key = match ReviewKey::for_repository("github", &repository, number) {
            Ok(key) => key,
            Err(error) => {
                self.status = error.to_string();
                return;
            }
        };
        self.tabs[index].details_generation += 1;
        self.tabs[index].write_in_flight = true;
        if submitted_summary_edit && self.active_tab == Some(index) {
            self.submitted_summary_input
                .update(cx, |input, cx| input.set_disabled(true, cx));
        }
        let journal_root = self.interaction_root.clone();
        let provider = GithubProvider::new(repository.account.clone());
        let task = cx.background_spawn(async move {
            let journal =
                ActionJournal::open(&journal_root, key).map_err(
                    |reason| ProviderMutationOutcome::<
                        cibergit::domain::ReviewAuxiliaryAcknowledgement,
                    >::PreflightRejected {
                        reason: format!("Cannot open caller journal; zero writes sent: {reason}"),
                    },
                );
            match journal {
                Ok(journal) => {
                    dispatch_auxiliary(&journal, &provider, &repository, number, &request)
                }
                Err(outcome) => outcome,
            }
        });
        cx.spawn(async move |root, cx| {
            let outcome = task.await;
            let _ = root.update(cx, |root, cx| {
                let Root::Review(this) = root else { return };
                if this.workspace_instance != workspace_instance {
                    return;
                }
                let Some(index) = this.tabs.iter().position(|tab| {
                    tab.repository.cache_key() == identity
                        && tab.pull_request.number == number
                        && tab.instance_generation == tab_instance
                }) else {
                    return;
                };
                this.tabs[index].write_in_flight = false;
                let acknowledged = matches!(&outcome, ProviderMutationOutcome::Acknowledged(_));
                if submitted_summary_edit && this.active_tab == Some(index) {
                    this.submitted_summary_input.update(cx, |input, cx| {
                        input.set_disabled(acknowledged && submitted_summary_clear.is_some(), cx)
                    });
                }
                this.status = match outcome {
                    ProviderMutationOutcome::Acknowledged(_) => {
                        this.tabs[index].editing_pending_summary = false;
                        this.tabs[index].reply_thread = None;
                        if submitted_summary_edit {
                            "Submitted review summary edit acknowledged exactly; refreshing authoritative activity."
                                .into()
                        } else {
                            "Review action acknowledged; refreshing authoritative activity.".into()
                        }
                    }
                    ProviderMutationOutcome::PreflightRejected { reason } => {
                        format!("Review action was not sent: {reason}")
                    }
                    ProviderMutationOutcome::Uncertain { reason, .. } => format!(
                        "Review action outcome is uncertain and will not replay automatically: {reason}"
                    ),
                };
                if acknowledged && let Some(captured) = submitted_summary_clear {
                    this.request_submitted_draft_clear(index, captured, cx);
                } else {
                    this.start_next_submitted_draft_save(index, cx);
                }
                this.refresh_details(index, cx);
                cx.notify();
            });
        })
        .detach();
    }

    fn reconcile_action_journal(&mut self, cx: &mut Context<Root>) {
        let Some(index) = self.active_tab else { return };
        if self.tabs[index].submitted_summary_editor.close_after_save {
            self.status = "Wait for the local draft close operation to finish.".into();
            return;
        }
        if self.tabs[index].write_in_flight {
            self.status = "Wait for the active write before reconciling outcomes.".into();
            return;
        }
        let repository = self.tabs[index].repository.clone();
        let number = self.tabs[index].pull_request.number;
        let completion = ActionJournalCompletionToken {
            workspace_instance: self.workspace_instance,
            tab_instance: self.tabs[index].instance_generation,
            repository_key: repository.cache_key(),
            pull_request: number,
        };
        let key = match ReviewKey::for_repository("github", &repository, number) {
            Ok(key) => key,
            Err(error) => {
                self.status = error.to_string();
                return;
            }
        };
        let journal_root = self.interaction_root.clone();
        self.tabs[index].write_in_flight = true;
        self.status = "Reading authoritative state to reconcile started actions…".into();
        let provider = GithubProvider::new(repository.account.clone());
        let task = cx.background_spawn(async move {
            let journal = ActionJournal::open(&journal_root, key).map_err(anyhow::Error::msg)?;
            let operations = journal.operations().map_err(anyhow::Error::msg)?;
            let details = provider.details(&repository, number)?;
            let pending = provider.pending_review(&repository, number)?;
            let mut resolved = 0usize;
            let mut still_uncertain = Vec::new();
            for operation in operations.iter().filter(|operation| {
                matches!(
                    operation.status,
                    JournalStatus::InFlight | JournalStatus::Uncertain { .. }
                )
            }) {
                let (operation_id, attempt_id) = journal_identity(&operation.request);
                let observation = match &operation.request {
                    JournalRequest::Auxiliary(request) => {
                        observe_auxiliary(&request.action, &details, pending.as_ref())
                    }
                    JournalRequest::Merge {
                        preparation,
                        request,
                    } => provider
                        .prepare_merge(&repository, number, &preparation.reviewed_head_sha)
                        .ok()
                        .and_then(|fresh| observe_merge(&request.action, preparation, &fresh)),
                    JournalRequest::Lifecycle(_) => None,
                    JournalRequest::Discussion(request) => match &request.action {
                        PullRequestDiscussionAction::Edit {
                            comment,
                            selected_author,
                            body,
                            ..
                        } => match provider.reconcile_pr_comment(&repository, number, comment) {
                            ProviderReadEvidence::Observed(observed)
                                if observed.body == *body
                                    && observed.author.as_deref().is_some_and(|author| {
                                        author.eq_ignore_ascii_case(selected_author)
                                    }) => Some((
                                true,
                                true,
                                format!(
                                    "Exact known comment {} has the frozen edited body.",
                                    comment.remote_id
                                ),
                            )),
                            ProviderReadEvidence::Observed(_) => None,
                            ProviderReadEvidence::Inconclusive { .. } => None,
                        },
                        // Create has no returned ID in a lost acknowledgement,
                        // and absence after delete is explicitly inconclusive.
                        PullRequestDiscussionAction::Create { .. }
                        | PullRequestDiscussionAction::Delete { .. } => None,
                    },
                };
                match observation {
                    Some((true, completed, evidence)) => {
                        journal
                            .mark_acknowledged(operation_id, attempt_id, completed, evidence)
                            .map_err(anyhow::Error::msg)?;
                        resolved += 1;
                    }
                    Some((false, _, evidence)) => {
                        still_uncertain.push(format!(
                            "{} · The current object differs from the request, but that does not prove this attempt was NotApplied after later external changes: {evidence}",
                            journal_operation_description(operation)
                        ));
                    }
                    None => {
                        let limitation = match &operation.request {
                            JournalRequest::Auxiliary(request)
                                if matches!(request.action, ReviewAuxiliaryAction::Reply { .. }) =>
                            {
                                "No safe exact-ID reply observation route exists: the frozen request contains the target thread/review/body but no provider reply ID, and GitHub does not preserve the local attempt ID."
                            }
                            _ => {
                                "The fresh read did not provide complete exact identity and payload evidence for this request."
                            }
                        };
                        still_uncertain.push(format!(
                            "{} · {limitation}",
                            journal_operation_description(operation)
                        ));
                    }
                }
            }
            let operations = journal.operations().map_err(anyhow::Error::msg)?;
            Ok::<_, anyhow::Error>((resolved, still_uncertain, operations))
        });
        cx.spawn(async move |root, cx| {
            let result = task.await.map_err(|error| format!("{error:#}"));
            let _ = root.update(cx, |root, cx| {
                let Root::Review(this) = root else { return };
                let Some(index) = this.apply_action_journal_completion(&completion, result) else {
                    return;
                };
                this.refresh_details(index, cx);
                cx.notify();
            });
        })
        .detach();
    }

    fn apply_action_journal_completion(
        &mut self,
        completion: &ActionJournalCompletionToken,
        result: ActionJournalReconciliationResult,
    ) -> Option<usize> {
        let index = self.tabs.iter().position(|tab| {
            completion.matches_values(
                self.workspace_instance,
                tab.instance_generation,
                &tab.repository.cache_key(),
                tab.pull_request.number,
            )
        })?;
        self.tabs[index].write_in_flight = false;
        self.status = match result {
            Ok((resolved, uncertain, operations)) => {
                self.tabs[index].journal_operations = operations;
                self.tabs[index].journal_error = None;
                if uncertain.is_empty() {
                    format!(
                        "Authoritative reconciliation resolved {resolved} auxiliary / merge action(s); explicit retry is allowed only for proven NotApplied attempts."
                    )
                } else {
                    format!(
                        "Resolved {resolved} auxiliary / merge action(s); {} remain frozen. {} No replay occurred.",
                        uncertain.len(),
                        uncertain.join(" | ")
                    )
                }
            }
            Err(error) => {
                format!("Authoritative reconciliation read failed; journal remains frozen: {error}")
            }
        };
        Some(index)
    }

    fn reconcile_review_operations(&mut self, cx: &mut Context<Root>) {
        let Some(index) = self.active_tab else { return };
        if self.tabs[index].submitted_summary_editor.close_after_save {
            return;
        }
        if self.tabs[index].write_in_flight {
            self.status =
                "Wait for the active operation before reconciling review outcomes.".into();
            return;
        }
        let (repository, number, store, authority, expected, read_epoch) = {
            let tab = &mut self.tabs[index];
            let InteractionState::Ready(controller) = &tab.interactions else {
                self.status = "Review recovery must load before reconciliation.".into();
                return;
            };
            if controller.unresolved_operations() == 0 {
                self.status = "No review-composition outcomes require reconciliation.".into();
                return;
            }
            tab.details_generation += 1;
            tab.write_in_flight = true;
            (
                tab.repository.clone(),
                tab.pull_request.number,
                controller.store.clone(),
                controller.authority.clone(),
                controller.durable_composition.clone(),
                TabReadEpoch {
                    instance: tab.instance_generation,
                    generation: tab.interaction_generation,
                },
            )
        };
        if self.active_tab == Some(index) {
            self.composer_input
                .update(cx, |input, cx| input.set_disabled(true, cx));
            self.review_summary_input
                .update(cx, |input, cx| input.set_disabled(true, cx));
        }
        self.status =
            "Reading exact review identities under local authority; no write will be dispatched…"
                .into();
        let identity = repository.cache_key();
        let (latest, lock, sequence) = self.next_review_state_write(&identity, number);
        let provider = GithubProvider::new(repository.account.clone());
        let task = cx.background_spawn(async move {
            let _guard = lock
                .lock()
                .map_err(|_| "Review reconciliation sequencing lock failed.".to_owned())?;
            if latest.load(Ordering::Acquire) != sequence {
                return Ok(None);
            }
            authority
                .reconcile_if_current(&store, expected.as_ref(), &repository, number, || {
                    let details = provider
                        .details(&repository, number)
                        .map_err(|error| format!("Details read failed: {error:#}"))?;
                    let pending = provider
                        .pending_review(&repository, number)
                        .map_err(|error| format!("Pending-review read failed: {error:#}"))?;
                    Ok((details, pending))
                })
                .map(Some)
        });
        cx.spawn(async move |root, cx| {
            let result = task.await;
            let _ = root.update(cx, |root, cx| {
                let Root::Review(this) = root else { return };
                let Some(index) = this.tabs.iter().position(|tab| {
                    tab.repository.cache_key() == identity
                        && tab.pull_request.number == number
                        && read_epoch.matches(tab.instance_generation, tab.interaction_generation)
                }) else {
                    return;
                };
                this.tabs[index].write_in_flight = false;
                if this.active_tab == Some(index) {
                    this.composer_input
                        .update(cx, |input, cx| input.set_disabled(false, cx));
                    this.review_summary_input
                        .update(cx, |input, cx| input.set_disabled(false, cx));
                }
                this.status = match result {
                    Ok(Some(report)) => {
                        let resolved = report.resolved();
                        let unresolved = report.unresolved();
                        this.tabs[index].details = Some(report.details.clone());
                        this.tabs[index].pending_snapshot = report.pending.clone();
                        this.tabs[index].details_state = LoadState::Ready;
                        if let InteractionState::Ready(controller) =
                            &mut this.tabs[index].interactions
                        {
                            controller.composition = report.composition.clone();
                            controller.durable_composition = Some(report.composition);
                            controller.install_pending_snapshot(report.pending);
                            controller.reconciliation_results = report.items;
                        }
                        if unresolved == 0 {
                            format!(
                                "Durably reconciled {resolved} exact review outcome(s). No provider mutation was sent."
                            )
                        } else {
                            format!(
                                "Durably reconciled {resolved} exact review outcome(s); {unresolved} remain frozen because identity or payload proof is incomplete. No provider mutation was sent."
                            )
                        }
                    }
                    Ok(None) => {
                        "A newer local review-state action superseded this reconciliation; no outcome was changed."
                            .into()
                    }
                    Err(error) => format!(
                        "Review reconciliation did not change durable state; operations remain frozen: {error}"
                    ),
                };
                this.rebuild_diff(index, this.wide);
                cx.notify();
            });
        })
        .detach();
    }

    fn load_comparison(
        &mut self,
        index: usize,
        revision: Revision,
        advancing: bool,
        cx: &mut Context<Root>,
    ) {
        let generation = self.issue_request_generation();
        let Some(tab) = self.tabs.get_mut(index) else {
            return;
        };
        tab.request_generation = generation;
        let repository = tab.repository.clone();
        let number = tab.pull_request.number;
        let key = repository.cache_key();
        let prior_canonical = tab.canonical_full_revision.clone();
        tab.state = LoadState::Loading(
            if advancing {
                "Loading newer revision…"
            } else {
                "Loading immutable comparison…"
            }
            .into(),
        );
        let store = self.store.clone();
        let task = cx.background_spawn(async move {
            let provider = GithubProvider::new(repository.account.clone());
            if let Some(path) = repository.local_path.as_deref()
                && let Ok(comparison) = local_pr_inventory(path, &revision)
            {
                let plan = LocalFileLoadPlan {
                    revision: comparison.revision.clone(),
                    full_pr: true,
                };
                return Ok((comparison, false, true, Some(plan)));
            }
            match provider.comparison(&repository, number, &revision) {
                Ok(comparison) => Ok((comparison, false, false, None)),
                Err(error) => match store
                    .as_ref()
                    .and_then(|store| store.load_comparison(&repository, number, &revision).ok())
                {
                    Some(cached) => Ok((cached, true, false, None)),
                    None => Err(error),
                },
            }
        });
        cx.spawn(async move |root, cx| {
            let result = task.await;
            let _ = root.update(cx, |root, cx| {
                let Root::Review(this) = root else { return };
                let Some(tab_index) = this.tabs.iter().position(|tab| {
                    tab.repository.cache_key() == key
                        && tab.pull_request.number == number
                        && tab.request_generation == generation
                        && (!advancing || tab.canonical_full_revision == prior_canonical)
                }) else {
                    return;
                };
                match result {
                    Ok((comparison, cached, local_inventory, load_plan)) => {
                        if !cached && let Some(store) = &this.store {
                            let _ = store.save_comparison(
                                &this.tabs[tab_index].repository,
                                number,
                                &comparison,
                            );
                        }
                        if advancing {
                            if let Some(session) =
                                &mut this.tabs[tab_index].canonical_session
                                && let Err(error) = session.advance(comparison)
                            {
                                this.tabs[tab_index].state =
                                    LoadState::Error(format!("Cannot advance: {error:#}"));
                                cx.notify();
                                return;
                            }
                            let canonical = this.tabs[tab_index]
                                .canonical_session
                                .clone()
                                .expect("advanced canonical session");
                            this.tabs[tab_index].canonical_full_revision =
                                canonical.revision().clone();
                            this.tabs[tab_index].request_sessions.clear();
                            this.tabs[tab_index].session = Some(canonical);
                            this.tabs[tab_index]
                                .comparison_picker
                                .select_request(ComparisonRequest::FullPullRequest);
                            this.tabs[tab_index].comparison_picker.inventory = None;
                            this.tabs[tab_index].comparison_picker.notice = Some(
                                "Advanced to the observed published snapshot; selection reset to Full pull request."
                                    .into(),
                            );
                            this.tabs[tab_index].selected_local_file_load = load_plan;
                        } else {
                            let session = ReviewSession::new(comparison);
                            this.tabs[tab_index].canonical_full_revision =
                                session.revision().clone();
                            this.tabs[tab_index].canonical_session = Some(session.clone());
                            this.tabs[tab_index].session = Some(session);
                            this.tabs[tab_index]
                                .comparison_picker
                                .select_request(ComparisonRequest::FullPullRequest);
                            this.tabs[tab_index].selected_local_file_load = load_plan;
                        }
                        if let Some((files, selected)) =
                            this.tabs[tab_index].session.as_ref().map(|session| {
                                (
                                    session.comparison().files.clone(),
                                    session.selected_file().map(file_key),
                                )
                            })
                        {
                            this.tabs[tab_index].file_tree.sync(&files);
                            if let Some(selected) = selected
                                && let Some(row) =
                                    this.tabs[tab_index].file_tree.reveal_file(&selected)
                            {
                                this.tabs[tab_index]
                                    .file_tree_scroll
                                    .scroll_to_item(row, ScrollStrategy::Nearest);
                            }
                        }
                        this.tabs[tab_index].state = if cached {
                            LoadState::Cached("Offline · immutable comparison from cache".into())
                        } else {
                            LoadState::Ready
                        };
                        this.tabs[tab_index].local_inventory = local_inventory;
                        this.rebuild_diff(tab_index, this.wide);
                        this.load_interactions(tab_index, cx);
                        this.schedule.succeeded(&format!("pr:{key}:{number}"));
                        this.save_workspace();
                        this.persist_session(tab_index, cx);
                        this.load_commit_inventory(tab_index, cx);
                        if local_inventory {
                            this.load_selected_local_file(tab_index, cx);
                        } else {
                            this.persist_session(tab_index, cx);
                        }
                    }
                    Err(error) => {
                        this.tabs[tab_index].state =
                            LoadState::Error(format!("Comparison unavailable: {error:#}"));
                        this.schedule.failed(&format!("pr:{key}:{number}"));
                    }
                }
                cx.notify();
            });
        })
        .detach();
    }

    fn refresh_active(&mut self, cx: &mut Context<Root>) {
        self.refresh_active_with_intent(true, cx);
    }

    fn refresh_active_with_intent(&mut self, explicit: bool, cx: &mut Context<Root>) {
        let Some(index) = self.active_tab else { return };
        if self.tabs[index].submitted_summary_editor.close_after_save {
            return;
        }
        self.refresh_metadata(index, explicit, cx);
        self.refresh_details_with_intent(index, explicit, cx);
        self.refresh_lifecycle_with_intent(index, explicit, cx);
    }

    fn refresh_metadata(&mut self, index: usize, explicit: bool, cx: &mut Context<Root>) {
        let Some((repository, number, effective_explicit)) =
            self.tabs.get_mut(index).and_then(|tab| {
                if !general_read_tab_can_start(tab.submitted_summary_editor.close_after_save) {
                    return None;
                }
                tab.metadata_refresh
                    .begin_admission(explicit)
                    .map(|effective| (tab.repository.clone(), tab.pull_request.number, effective))
            })
        else {
            return;
        };
        let admission = match self.general_reads.begin(&repository.account) {
            Ok(admission) => admission,
            Err(read_sync::ReadDeferral::Busy) => {
                self.tabs[index]
                    .metadata_refresh
                    .defer_admission(effective_explicit);
                return;
            }
            Err(read_sync::ReadDeferral::Server(notice)) => {
                self.tabs[index]
                    .metadata_refresh
                    .defer_admission(effective_explicit);
                self.status = notice.into();
                cx.notify();
                return;
            }
        };
        let tab = &mut self.tabs[index];
        tab.metadata_generation += 1;
        let read_epoch = TabReadEpoch {
            instance: tab.instance_generation,
            generation: tab.metadata_generation,
        };
        let read_workspace_instance = self.workspace_instance;
        let key = repository.cache_key();
        let (read_token, cache) = admission.into_parts();
        let task =
            cx.background_spawn(async move {
                let outcome = GithubProvider::new(repository.account.clone())
                    .pull_request_conditional(&repository, number, cache);
                (read_token, outcome)
            });
        cx.spawn(async move |root, cx| {
            let (read_token, outcome) = task.await;
            let _ = root.update(cx, |root, cx| {
                let Root::Review(this) = root else { return };
                let (result, cache, directive, failure) = outcome.into_parts();
                if !general_read_callback_is_current(
                    read_workspace_instance,
                    this.workspace_instance,
                ) {
                    this.general_reads
                        .complete(&read_token, &directive, cache, false);
                    return;
                }
                let matching_index = this.tabs.iter().position(|tab| {
                    tab.repository.cache_key() == key
                        && tab.pull_request.number == number
                        && read_epoch.matches(tab.instance_generation, tab.metadata_generation)
                });
                let superseded = matching_index.is_some_and(|index| {
                    this.tabs[index].metadata_refresh.superseded_by_explicit()
                });
                let accept_payload = matching_index.is_some() && !superseded && result.is_ok();
                let disposition =
                    this.general_reads
                        .complete(&read_token, &directive, cache, accept_payload);
                if !disposition.matching_operation_released {
                    return;
                }
                let follow_up = matching_index
                    .map(|index| this.tabs[index].metadata_refresh.complete())
                    .unwrap_or(false);
                if let Some(index) = matching_index
                    && follow_up
                {
                    this.refresh_metadata(index, true, cx);
                    this.resume_general_read_followups(cx);
                    return;
                }
                if let Some(index) = matching_index {
                    let tab = &mut this.tabs[index];
                    match result {
                        Ok(pull_request) if disposition.payload_accepted => {
                            tab.stack.observe_selected_revision(&pull_request.head_sha);
                            if let Some(session) = &mut tab.canonical_session {
                                session.observe_revision(pull_request.revision());
                            }
                            if matches!(
                                tab.comparison_picker.request,
                                ComparisonRequest::FullPullRequest
                            ) && let Some(session) = &mut tab.session
                            {
                                session.observe_revision(pull_request.revision());
                            }
                            tab.pull_request = pull_request;
                            this.schedule.succeeded(&format!("pr:{key}:{number}"));
                        }
                        Ok(_) => {}
                        Err(_) => {
                            this.status = general_read_failure_notice(failure).into();
                            this.schedule.failed(&format!("pr:{key}:{number}"));
                        }
                    }
                }
                this.resume_general_read_followups(cx);
                cx.notify();
            });
        })
        .detach();
    }

    fn refresh_lifecycle(&mut self, index: usize, cx: &mut Context<Root>) {
        self.refresh_lifecycle_with_intent(index, true, cx);
    }

    fn refresh_lifecycle_with_intent(
        &mut self,
        index: usize,
        explicit: bool,
        cx: &mut Context<Root>,
    ) {
        let Some((repository, number, effective_explicit)) =
            self.tabs.get_mut(index).and_then(|tab| {
                if !general_read_tab_can_start(tab.submitted_summary_editor.close_after_save) {
                    return None;
                }
                tab.lifecycle_refresh
                    .begin_admission(explicit)
                    .map(|effective| (tab.repository.clone(), tab.pull_request.number, effective))
            })
        else {
            return;
        };
        let admission = match self.general_reads.begin(&repository.account) {
            Ok(admission) => admission,
            Err(read_sync::ReadDeferral::Busy) => {
                self.tabs[index]
                    .lifecycle_refresh
                    .defer_admission(effective_explicit);
                return;
            }
            Err(read_sync::ReadDeferral::Server(notice)) => {
                self.tabs[index]
                    .lifecycle_refresh
                    .defer_admission(effective_explicit);
                self.status = notice.into();
                cx.notify();
                return;
            }
        };
        let tab = &mut self.tabs[index];
        tab.lifecycle_generation = tab.lifecycle_generation.saturating_add(1);
        let read_epoch = TabReadEpoch {
            instance: tab.instance_generation,
            generation: tab.lifecycle_generation,
        };
        let read_workspace_instance = self.workspace_instance;
        let identity = repository.cache_key();
        if tab.lifecycle.snapshot.is_none() {
            tab.lifecycle_state = LoadState::Loading("Loading lifecycle metadata…".into());
        }
        let (read_token, _cache) = admission.into_parts();
        let task = cx.background_spawn(async move {
            let provider = GithubProvider::new(repository.account.clone());
            let outcome = provider.general_read(|provider| {
                let snapshot = provider.pr_lifecycle_snapshot(&repository, number)?;
                let choices = provider.pr_lifecycle_choices(&repository)?;
                Ok((snapshot, choices))
            });
            (read_token, outcome)
        });
        cx.spawn(async move |root, cx| {
            let (read_token, outcome) = task.await;
            let _ = root.update(cx, |root, cx| {
                let Root::Review(this) = root else { return };
                let (result, cache, directive, failure) = outcome.into_parts();
                if !general_read_callback_is_current(
                    read_workspace_instance,
                    this.workspace_instance,
                ) {
                    this.general_reads
                        .complete(&read_token, &directive, cache, false);
                    return;
                }
                let matching_index = this.tabs.iter().position(|tab| {
                    tab.repository.cache_key() == identity
                        && tab.pull_request.number == number
                        && read_epoch.matches(tab.instance_generation, tab.lifecycle_generation)
                });
                let superseded = matching_index.is_some_and(|index| {
                    this.tabs[index]
                        .lifecycle_refresh
                        .superseded_by_explicit()
                });
                let accept_payload = matching_index.is_some() && !superseded && result.is_ok();
                let disposition = this.general_reads.complete(
                    &read_token,
                    &directive,
                    cache,
                    accept_payload,
                );
                if !disposition.matching_operation_released {
                    return;
                }
                let follow_up = matching_index
                    .map(|index| this.tabs[index].lifecycle_refresh.complete())
                    .unwrap_or(false);
                if let Some(index) = matching_index
                    && follow_up
                {
                    this.refresh_lifecycle(index, cx);
                    this.resume_general_read_followups(cx);
                    return;
                }
                if let Some(index) = matching_index {
                    let tab = &mut this.tabs[index];
                    match result {
                    Ok((snapshot, choices)) if disposition.payload_accepted => {
                        let install = tab
                            .lifecycle
                            .install_snapshot(snapshot)
                            .and_then(|()| tab.lifecycle.install_choices(choices));
                        match install {
                            Ok(()) => tab.lifecycle_state = LoadState::Ready,
                            Err(error) => {
                                tab.lifecycle_state = LoadState::Error(format!(
                                    "Lifecycle response rejected without changing comparison state: {error}"
                                ));
                            }
                        }
                    }
                    Ok(_) => {}
                    Err(_) => {
                        tab.lifecycle_state = LoadState::Error(
                            general_read_failure_notice(failure).into(),
                        );
                    }
                    }
                }
                this.resume_general_read_followups(cx);
                cx.notify();
            });
        })
        .detach();
    }

    fn stage_active_metadata_inputs(&mut self, cx: &mut Context<Root>) {
        let Some(index) = self.active_tab else { return };
        let title = self.metadata_title_input.read(cx).value().to_string();
        let body = self.metadata_body_input.read(cx).value().to_string();
        let base = self.metadata_base_input.read(cx).value().to_string();
        self.tabs[index].lifecycle.stage_metadata(title, body, base);
    }

    fn begin_metadata_edit(&mut self, window: &mut Window, cx: &mut Context<Root>) {
        let Some(index) = self.active_tab else { return };
        if self.tabs[index].write_in_flight {
            self.status =
                "Wait for the current request to finish before preparing another change.".into();
            cx.notify();
            return;
        }
        match self.tabs[index].lifecycle.begin_metadata_edit() {
            Ok(form) => {
                self.metadata_title_input
                    .update(cx, |input, cx| input.set_value(form.title, window, cx));
                self.metadata_body_input
                    .update(cx, |input, cx| input.set_value(form.body, window, cx));
                self.metadata_base_input.update(cx, |input, cx| {
                    input.set_value(form.base_branch, window, cx)
                });
                self.status =
                    "Editing isolated mutable metadata; Apply freezes one exact changed field."
                        .into();
            }
            Err(error) => self.status = error,
        }
        cx.notify();
    }

    fn apply_metadata_edit(&mut self, cx: &mut Context<Root>) {
        let Some(index) = self.active_tab else { return };
        if self.tabs[index].write_in_flight {
            self.status =
                "Wait for the current request to finish before preparing another change.".into();
            cx.notify();
            return;
        }
        self.stage_active_metadata_inputs(cx);
        let operation_id = next_attempt_id("pr-lifecycle");
        let attempt_id = next_attempt_id(&operation_id);
        match self.tabs[index]
            .lifecycle
            .prepare_metadata_apply(operation_id, attempt_id)
        {
            Ok(()) => {
                self.status =
                    "Exact metadata delta frozen; review it before confirming one provider action."
                        .into()
            }
            Err(error) => self.status = format!("Metadata was not prepared: {error}"),
        }
        cx.notify();
    }

